  kyiv_mohyla: { n: 'Kyiv-Mohyla-akademiet grundlægges', p: 'Kyiv', d: 'Metropoliten Petro Mohyla forener Kyivs broderskoleskole med lavra-skolen til kollegiet — Østeuropas intellektuelle kraftcenter i de følgende 150 år.' },
