  khotyn_1621: { n: 'Slaget ved Khotyn', p: 'Khotyn, Ukraine', d: 'Polsk-litauiske og zaporozjiske styrker under den døende storhetman Chodkiewicz og Sahajdatsjnyjs kosakker holder sultan Osman 2.s langt større hær tilbage i en måned; begge imperier underskriver, udmattede.' },
