  mazepa: { n: 'Hetman Ivan Mazepa', p: 'Baturyn, Ukraine', d: 'Protektor for kirker og Kyiv-Mohyla-akademiet, der styrede Hetmanstaten i to årtier; som 69-årig satte han alt på ét kort — Sveriges Karl 12. — og betalte med sin hovedstad, sit ry i Moskva og sin plads i russisk dæmonologi.' },
  baturyn_sack: { n: 'Baturyns ødelæggelse', p: 'Baturyn, Ukraine', d: 'Dage efter Mazepas træk stormer Mensjikovs moskovitiske korps kosakhovedstaden og massakrerer garnisonen og byboerne — krigens åbende grusomhed og en ukrainsk erindring i sig selv.' },
  poltava: { n: 'Slaget ved Poltava', p: 'Poltava, Ukraine', d: 'Peter 1. knuser Karl 12.s svensker og Mazepas kosakker; Sverige forlader stormagtrækkerne, Hetmanstaten mister sin udenrigspolitiske frihed — og med den sin statlighed.' },
  orlyk_constitution: { n: 'Pylyp Orlyks forfatning', p: 'Bender (i eksil)', d: 'Valgt hetman i eksil efter Poltava vedtager Orlyk og kosakternes generelle råd en "Pagt og Forfatning", der binder hetmanen til råd, domstole og fri kosakdom — regnet blandt Europas tidligste moderne forfatninger.' },
  koliyivshchyna: { n: 'Kolijivsjtjyna (hajdamakoprøret)', p: 'Uman, Ukraine', d: 'Det største hajdamakoprør mod adelsstyret på højre bred: Zaliznjak og Honta tager Uman midt i grusomheder på alle sider; russiske regulære tropper knuser det inden for uger. Sjevtjenko gjorde det til sit digt "Hajdamaky".' },
  sich_destroyed: { n: 'Katharina 2. ødelægger Sitsjen', p: 'Zaporozjiska Sitsj', d: 'Mens kosakhæren felttog mod tyrkerne, nedbrænder general Tekelis korps det ubeskyttede Sitsj ved overraskelsesordre; den femogfirsårige sidste kish-otaman Kalnysjevskij tilbringer et kvart århundrede i fængsel på Solovki.' },
  dashkevych: { n: 'Ostap Dasjkevytj', p: 'Kaniv, Ukraine', d: 'Starost af Kaniv og Tjerkasy, som krønikerne regner blandt de første ledere — og den første kaldet hetman — af de ukrainske kosakker; to årtiers togter nåede Otsjakiv og den krimiske kyst.' },
  vyshnevetsky: { n: 'Dmytro Vysjnevetskyj (Bajda)', p: 'Mala Khortytsja, Ukraine', d: 'Fyrst-starost, der byggede en fæstning på Mala Khortytsja (1556) — frøet til Zaporozjiska Sitsj — og forenede lavlandshærene; forrådt i Moldavien og henrettet i Istanbul.' },
  kishka: { n: 'Samiilo Kisjka', p: 'Zaporozjiska Sitsj', d: 'To gange senior for de registrerede kosakker og en helt i dumadigtene: taget af tyrkerne til en galej, befriede han sig selv og sine roere ved at erobre skibet og dets kanoner.' },
  shakh: { n: 'Jakiv Sjakh', p: 'Zaporozjiska Sitsj', d: 'Kish-otaman med titlen "lavlandshetman" i kilderne: han tog på togter mod Krim og Moldavien og faldt i slag mod tatarerne.' },
  oryshovsky: { n: 'Jan Orysjovskyj', p: 'Kaniv, Ukraine', d: 'Registreret kosaksenior, som kronen regnede som hetman: han holdt den splittede hær i tjeneste og slog til mod de krimiske og nogajske ulusser.' },
  kosynsky: { n: 'Krysjtof Kosynskyj', p: 'Bila Tserkva, Ukraine', d: 'Kaniv-hundredefører og hetman for de registrerede kosakker: hans opstand i 1591 erobrede Bila Tserkva-borgen og åbnede kosakoprørernes æra; slået ved Pjatka døde han af sine sår (1593).' },
  loboda: { n: 'Hryhorij Loboda', p: 'Zaporozjiska Sitsj', d: 'Hetman for nizovi-hæren, der marcherede med Nalyvajkos oprørere mod Hviderusland; dræbt af oprørere fra egen lejr i stridighederne i 1596.' },
  shaula: { n: 'Matvij Sjaula', p: 'Zaporozjiska Sitsj', d: 'Efterfulgte Loboda over det brudte oprør i 1596: efter Solonytsja holdt han den spredte hær samlet i tre år mere — en dunkel afslutning på et dunkelt embede.' },
  baibuza: { n: 'Tykhin Bajbuza', p: 'Zaporozjiska Sitsj', d: 'Hetman for zaporozjerne, hvis togter i 1597 nåede Donau-fæstningerne — et af slægtens mørkeste navne, husket i en folkesang.' },
  izapovich: { n: 'Hryhorij Izapovytj', p: 'Zaporozjiska Sitsj', d: 'Registreret hetman i det store plyndringstiår: hærens tjajkaer brændte igen langs den krimiske og osmanniske kyst i hans år.' },
  borodavka: { n: 'Jakiv Borodavka-Neroda', p: 'Zaporozjiska Sitsj', d: 'Hetman for den uregistrerede hær gennem aftalen i Rzeszów 1619; afsat og dræbt i lejren ved Khotyn 1621, da Sahajdatsjnyj tog bulavaen i krig.' },
  doroshenko_m: { n: 'Mykhailo Dorosjenko', p: 'Tjerkasy, Ukraine', d: 'Hetman, der genopbyggede kosakkernes troværdighed efter Cecora — hædret af både zar og konge — og ledte det berømte krimfelttog i 1628, hvor han faldt nær Perekop.' },
