  gulak: { n: 'Maksym Hulak', p: 'Zaporozjiska Sitsj', d: 'Slægtens sidste før-Khmelnytskyj-hetman: krønikenotater om hans togter mod de krimiske ulusser er næsten alt, der er tilbage af ham.' },
  khmelnytsky_yu: { n: 'Jurij Khmelnytskyj', p: 'Tjyhyryn, Ukraine', d: 'Khmelnytskyjs søn, to gange hetman (1657–63, 1677–81): skiftede polske, russiske og osmanniske herrer, efterhånden som Ruinaen dybnede, og endte sine dage som munk.' },
  vyhovsky: { n: 'Ivan Vyhovskyj', p: 'Haditj, Ukraine', d: 'Hetman 1657–59: hans Haditj-union førte Ukraine tilbage til statsfællesskabet som et ruthensk hertugdømme, og Konotop tilintetgjorde en moskovitisk hær — men Kyivs oberster vendte sig mod ham; myrdet af kosakrivaler (1664).' },
  teterya: { n: 'Pavlo Teteria', p: 'Korsun, Ukraine', d: 'Højbre-hetman i polsk bane (1663–66): flygtede ind i Moldavien, da hans oberster gjorde mytteri, og døde dér.' },
  briukhovetsky: { n: 'Ivan Brjukhovetskyj', p: 'Haditj, Ukraine', d: 'Den moskovitisk støttede venstrebre-hetman (1663–68): kyssede korset til zaren — og gjorde så oprør under guvernører og skatter; menneskemængden, der rejste sig med ham, flængede ham.' },
  doroshenko_p: { n: 'Petro Dorosjenko', p: 'Tjyhyryn, Ukraine', d: 'Ruinaens fineste statsmand: hetman for højre bredden og siden for begge, spillede han Warszawa, Moskva og Istanbul mod hinanden for et uafhængigt kosakfyrstendømme, holdt Tjyhyryn mod alt — og endte i ærefuld eksil nær Moskva.' },
  mnohohrishny: { n: 'Demian Mnohohrisjnyj', p: 'Baturyn, Ukraine', d: 'Venstrebre-hetman (1668–72): en dygtig general, der genopbyggede orden omkring Baturyn, indtil Moskva på falske anklager sendte ham i eksil til Sibirien.' },
  khanenko: { n: 'Mykhailo Khanenko', p: 'Uman, Ukraine', d: 'Hetman for det propolske parti på højre bredden (1669–74): imødegik Dorosjenko med polske hære og tabte til både ham og Horden.' },
  samus: { n: 'Samiilo Samus', p: 'Korsun, Ukraine', d: 'Hetman for den genoprettede højbre-hær (1693–1704): holdt de genoprettede regimenter i felten mod Horden, indtil han overgav bulavaen til Mazepa.' },
  kunytsky: { n: 'Stefan Kunnytskyj', p: 'Bila Tserkva, Ukraine', d: 'Propolsk højbre-hetman (1683–84), hvis kosakkavaleri red Wiens undsætning til hjælp — og som døde kort efter i polsk fangenskab.' },
  mohyla: { n: 'Andrij Mohyla', p: 'Nemyriv, Ukraine', d: 'Moldavisk fyrst af Mohyla-huset, der holdt den propolske højbre-hetmanstilling (1684–89) i kampen mod Dorosjenkos parti.' },
  samoilovych: { n: 'Ivan Samojlovytj', p: 'Baturyn, Ukraine', d: 'Venstrebre-hetman (1672–87): konsoliderede Hetmanstaten og dens skoler og faldt så, da krimfelttoget i 1687 mislykkedes — eksileret til Sibiriens Jenisejsk.' },
  skoropadsky_i: { n: 'Ivan Skoropadskyj', p: 'Hlukhiv, Ukraine', d: 'Hetman valgt efter Mazepas frafald (1708–22): loyal mod Peter 1. og alligevel berøvet magten — det kejserlige kollegium regerede ved siden af ham, mens embedet tømtes.' },
