  poverty_point: { n: 'Poverty Point', p: 'Poverty Point, Louisiana', d: 'Louisianas jægere og samlere — uden landbrug, uden keramik — bygger et omfattende jordkompleks af koncentriske volde ved nedre Mississippi og importerer kobber, sten og skaller fra hen over et halvt kontinent.' },
