  chimu: { n: 'Chimú — Chan Chan', p: 'Chan Chan, Peru', d: 'Jordens største lerby — 20 km² af omkringmurede citadeller — behersker det meste af Perus kyst med kanaler, reservoirer og skatter — indtil inkaerne fører dets guldsmede bort til Cusco.' },
  thule: { n: 'Thule-ekspansionen', p: 'North Slope, Alaska', d: 'Inuit-hvalfangere i skindbåde og med hundeslæder spreder sig fra Alaska til Grønland på tre århundreder og afløser det ældre dorset-folk — i dagens inuitters forfædre, hjemme dér, hvor næsten ingen andre bor.' },
  mesa_verde: { n: 'Mesa Verdes klippeboliger', p: 'Mesa Verde, Colorado', d: 'De forfædres pueblobyer flytter hel ind i klippealkoverne — Cliff Palace alene har 150 rum — før tørke og spændinger tømmer mesaerne ved år 1300.' },
  haudenosaunee: { n: 'Haudenosaunee-forbundet', p: 'Onondaga, New York', d: 'Fredsskaberen og Hiawatha forener fem krigsførende nationer under Fredens Store Træ i Onondaga — høvdinge valgt af klanmødrene, beslutninger af rådet; forbundet samles stadig i dag, og dets føderale idéer genlyder i den amerikanske union.' },
