  mexico_independence: { n: 'Grito de Dolores', p: 'Dolores, Mexico', d: 'Ved midnat den 16. september 1810 ringer præsten Miguel Hidalgo i sogneklokken og råber uafhængighed — elleve års krig ender med, at de tre garantiers hær marcherer ind i Mexico City.' },
  brazil_independence: { n: 'Brasiliens uafhængighed', p: 'Ipiranga, São Paulo', d: '"Independência ou morte!" — prins Pedro trækker sit sværd ved Ipiranga-bækken, og Brasilien forlader Portugal uden krig og beholder en monark frem til 1889.' },
  trail_of_tears: { n: 'Tårenes vej', p: 'Sydlige Appalachia → Oklahoma', d: 'Efter Indian Removal Act tvinges omkring 60.000 mennesker af cherokeser-, choctaw-, chickasaw-, creek- og seminole-nationerne vest for Mississippi; tusinder dør undervejs, og Højesterets dom i deres favør ignoreres simpelthen.' },
  gold_rush: { n: 'Guldfeberen i Californien', p: 'Sutters mølle, Californien', d: 'Guld i American River tiltrækker 300.000 mennesker ad land og hav på tre år — San Francisco bliver en by over natten, og Californien en stat i 1850, på land taget fra Mexico uger efter det første fund.' },
  transcontinental_rr: { n: 'Den første transkontinentale jernbane', p: 'Promontory Summit, Utah', d: 'Irske og kinesiske hold driver Union Pacific og Central Pacific mod hinanden; den gyldne spiger falder den 10. maj 1869, og en rejse fra kyst til kyst falder fra måneder til en uge.' },
  canada_confed: { n: 'Canadisk konføderation', p: 'Ottawa', d: 'Ontario, Quebec, Nova Scotia og New Brunswick forenes som Dominion of Canada — "fred, orden og god regering", den første koloni, der byttede imperium mod ansvarligt selvstyre.' },
  abolition_brazil: { n: 'Brasilien afskaffer slaveriet', p: 'Rio de Janeiro', d: 'Lei Áurea gør ende på Amerikas sidste slaveregime — af omkring fire millioner afrikanere og efterkommere slavet over 350 år — uden jord eller kompensation til de frigivne; monarkiet falder inden for atten måneder.' },
  klondike: { n: 'Guldfeberen i Klondike', p: 'Klondike, Yukon', d: 'Hundredtusinder af guldgravere slæber et ton udstyr hver over Chilkoot-passet til Yukon; boomet brænder ud på to år og efterlader spøgelsesbyer — og Jack London.' },
  mexican_revolution: { n: 'Den mexicanske revolution', p: 'Mexico', d: 'Díaz’ fald åbner et årti af borgerkrig — Zapatas "Tierra y Libertad", Villas kavaleri, forfatningen i 1917 med arbejds- og landrettigheder — en million døde, og en nation genskabt af sine muralmalere.' },
  cuban_revolution: { n: 'Den cubanske revolution', p: 'Sierra Maestra, Cuba', d: 'Castro, Che og firs ekspeditionsmænd lander fra Granma; to års guerrillakrig i Sierra Maestra ender med dem ridende ind i Havana — jordreform og alfabetiseringskampagner hjemme, eksil og krise ude.' },
  aboriginal: { n: 'Australske aboriginerkulturer', p: 'Arnhem Land, Australien', d: 'Over 65.000 års uafbrudt kultur — verdens ældste — med mundtlige historier, der måske husker virkelige istidskystlinjer.' },
