/* jp translations — Emperors of Japan (added 2026-10-28) */
Object.assign(window.DATA_DA, {
  jp_jimmu: { n: 'Jimmu', p: 'Kashihara, Japan', d: 'Legendarisk første kejser, oldebarn af solgudinden Amaterasu; Japan daterer sin uafbrudte kejserlinje fra hans tronbestigelse — traditionelt år 660 f.Kr.' },
  jp_suizei: { n: 'Suizei', p: 'Asuka, Japan', d: 'Anden kejser — traditionens første optegnede tronfølger; en af de tidlige monarker, som ingen uafhængige vidnesbyrd overlever om.' },
  jp_annei: { n: 'Annei', p: 'Asuka, Japan', d: 'Tredje legendariske kejser; krønikerne husker kun hans palads i Kawachi og en regeringstid på otteogtredive år.' },
  jp_itoku: { n: 'Itoku', p: 'Asuka, Japan', d: 'Fjerde legendariske kejser; husket især gennem slægtslinjen — hans linje løber ubrudt til den nuværende kejser.' },
  jp_kosho: { n: 'Kōshō', p: 'Asuka, Japan', d: 'Femte legendariske kejser; intet fra hans tid kan verificeres — historikerne placerer de første sikre datoer et årtusind senere.' },
  jp_koan: { n: 'Kōan', p: 'Asuka, Japan', d: 'Sjette legendariske kejser, tilskrevet en regeringstid på 101 år — en af flere umuligt lange perioder i de tidlige kongelister.' },
  jp_korei: { n: 'Kōrei', p: 'Asuka, Japan', d: 'Syvende legendariske kejser; traditionen siger, at hans mor var den første kejserindegemal født uden for kongeslægten.' },
  jp_kogen: { n: 'Kōgen', p: 'Asuka, Japan', d: 'Den ottende af de ”udokumenterbare” kejsere; efter hans regeringstid bliver krønikerne markant mere detaljerede.' },
  jp_kaika: { n: 'Kaika', p: 'Asuka, Japan', d: 'Niende og sidste af de tidlige kejsere, hvis regeringstider alene hviler på slægtslinjer.' },
  jp_sujin: { n: 'Sujin', p: 'Asuka, Japan', d: 'Semi-legendarisk ”rigets første hersker”: krønikerne tilskriver ham de første provinsguvernører og Ise-helligdommens præstelinje.' },
  jp_suinin: { n: 'Suinin', p: 'Asuka, Japan', d: 'Under ham, siger traditionen, blev begravelse af levende tjenere afløst af lerfigurer i haniwa-stil — og den første sumokamp blev udkæmpet.' },
  jp_keiko: { n: 'Keikō', p: 'Asuka, Japan', d: 'Den legendariske kejser i Yamato Takeru-sagaen — hans søns felttog mod øst fylder Japans ældste heltefortælling.' },
  jp_seimu: { n: 'Seimu', p: 'Asuka, Japan', d: 'Legendarisk kejser, tilskrevet den første organisering af de store hoffklaner i arvelige embeder.' },
  jp_chuai: { n: 'Chūai', p: 'Asuka, Japan', d: 'Død på felttog i Kyūshū; hans enke Jingū førte derefter hoffet gennem en berømt — og mytisk — erobring af Korea.' },
  jp_ojin: { n: 'Ōjin', p: 'Naniwa (Osaka), Japan', d: 'Semi-legendarisk beskytter af vævere, skrivere og heste fra kontinentet; dyrket efter sin død som Hachiman, krigsguden.' },
  jp_nintoku: { n: 'Nintoku', p: 'Naniwa (Osaka), Japan', d: 'Skal hvile i Daisen Kofun — en nøglehulsgrav med større grundareal end Gizas store pyramide; Jordens største grav målt på areal.' },
  jp_richu: { n: 'Richū', p: 'Kawachi, Japan', d: 'Den første af de spinkle 400-talsregeringer; krønikerne gemmer kun tronfølgefejder og paladspladser fra hans tid.' },
  jp_hanzei: { n: 'Hanzei', p: 'Kawachi, Japan', d: 'Kejser fra 400-tallet, hvis brødre kæmpede om tronfølgen — et vindue ind i Yamato-tidens brutale hofpolitik.' },
  jp_ingyo: { n: 'Ingyō', p: 'Kawachi, Japan', d: 'En lang regeringstid, husket for straffe mod adelsmænd, der forfalskede de første husstandsregistre — og for det tronfølgekaos, der fulgte.' },
  jp_anko: { n: 'Ankō', p: 'Kawachi, Japan', d: 'Myrdet i sin søvn af en adelsmand, hvis hustru han havde krævet — Japans første optegnede kejsermord.' },
  jp_yuryaku: { n: 'Yūryaku', p: 'Kawachi, Japan', d: 'En kraftfuld, frygtet konge; kinesiske annaler registrerer ham måske som ”kong Bu”, der bad om opbakning mod egne hofrivaler.' },
  jp_seinei: { n: 'Seinei', p: 'Kawachi, Japan', d: 'Yūryakus barnebarn; fem stille år — derefter gik tronen til sønnerne af den onkel, Yūryaku havde dræbt.' },
  jp_kenso: { n: 'Kensō', p: 'Kawachi, Japan', d: 'Regerede knap to år; 700-tallets krønikeskrivere kunne kun huske hans palads og hans tidlige død.' },
  jp_ninken: { n: 'Ninken', p: 'Kawachi, Japan', d: 'Gennem sine døtres ægteskaber knyttedes hans linje til Keitais — alle senere kejsere stammer fra den forening.' },
  jp_buretsu: { n: 'Buretsu', p: 'Kawachi, Japan', d: 'Skildret af krønikerne som en grusom drengekonge; hans barnløse død endte den direkte linje og førte Keitai til tronen.' },
  jp_keitai: { n: 'Keitai', p: 'Omi, Japan', d: 'Opvokset langt fra hoffet i Omi; hans tronbestigelse gjorde ham til en slags anden dynastistifter — alle kejsere siden stammer fra ham.' },
  jp_ankan: { n: 'Ankan', p: 'Kawachi, Japan', d: 'Regerede fire år; kilderne dvæler ved hans paladser og vandværker frem for hans politik.' },
  jp_senka: { n: 'Senka', p: 'Kawachi, Japan', d: 'Hans død bragte den unge halvbror Kinmei på tronen — forfaderen til alle senere kejsere.' },
  jp_kinmei: { n: 'Kinmei', p: 'Asuka, Japan', d: 'Den første kejser, kilderne lader os datere med sikkerhed; buddhismen kom til hoffet fra Paekche i hans regeringstid (552).' },
  jp_bidatsu: { n: 'Bidatsu', p: 'Asuka, Japan', d: 'Hoffkampene om buddhismen tilspidsedes under ham; Iwai-oprøret satte Yamatos greb om Kyūshū på prøve.' },
  jp_yomei: { n: 'Yōmei', p: 'Asuka, Japan', d: 'En hengiven konvertit, død inden for to år; den tronfølgestrid, der fulgte, gav den reelle magt til Soga-slægten.' },
  jp_sushun: { n: 'Sushun', p: 'Asuka, Japan', d: 'Sat på tronen af Soga-slægten — og dræbt af den, da han vendte sig mod buddhismens velgørere.' },
  jp_suiko: { n: 'Suiko', p: 'Asuka, Japan', d: 'Japans første regerende kejserinde; med regenten Shōtoku Taishi sendte hun de første udsendinge til Sui-Kina og førte buddhismen frem.' },
  jp_jomei: { n: 'Jomei', p: 'Asuka, Japan', d: 'Åbnede officielle forbindelser med Tang-Kina (630) — de første kentōshi-ekspeditioner, der skulle omforme japansk statskunst.' },
  jp_kogyoku: { n: 'Kōgyoku', p: 'Naniwa (Osaka), Japan', d: 'Anden regerende kejserinde; hendes hof væltedes ved Isshi-hændelsen i 645, statskuppet bag Taika-reformerne.' },
  jp_kotoku: { n: 'Kōtoku', p: 'Naniwa (Osaka), Japan', d: 'Taika-reformens kejser: afskaffede arvelige godser, udråbte et centraliseret rige og regerede fra den nye hovedstad Naniwa (Ōsaka).' },
  jp_saimei: { n: 'Saimei', p: 'Asuka, Japan', d: 'Kōgyoku genindsat under nyt navn; hun døde, mens hun udrustede en flåde for at redde allierede Paekche fra Tang og Silla.' },
  jp_tenji: { n: 'Tenji', p: 'Otsu, Japan', d: 'Efter at Japans flåde blev udslettet ved Paekchon (663), beordrede han den første skrevne lovbog og flyttede hoffet til Ōtsu.' },
  jp_kobun: { n: 'Kōbun', p: 'Otsu, Japan', d: 'Døde i Jinshin-krigen — arvefølgestriden mod sin onkel Tenmu, der afgjorde dynastiets fremtid.' },
  jp_tenmu: { n: 'Tenmu', p: 'Asuka, Japan', d: 'Vandt Jinshin-krigen og regerede med en kraft uden mage; beordrede de første nationalhistorier og gav buddhismen statslig opbakning.' },
  jp_jito: { n: 'Jitō', p: 'Asuka, Japan', d: 'Tredje regerende kejserinde — Tenmus enke og politiske arving; under hende blev den planlagte hovedstad Fujiwara-kyō grundlagt.' },
  jp_monmu: { n: 'Monmu', p: 'Fujiwara-kyō, Japan', d: 'Barnebarn af Tenmu og Jitō; hans regeringstid indledte Japans første planlagte hovedstad på kinesisk vis og æraen under Taihō-loven.' },
  jp_genmei: { n: 'Genmei', p: 'Nara, Japan', d: 'Fjerde regerende kejserinde; beordrede Kojiki udarbejdet og flyttede hoffet til Heijō-kyō (Nara) i 710.' },
  jp_gensho: { n: 'Genshō', p: 'Nara, Japan', d: 'Femte regerende kejserinde, en stabiliserende regent mellem halvsøsterens og nevøens regeringer; ritsuryō-staten modnes.' },
  jp_shomu: { n: 'Shōmu', p: 'Nara, Japan', d: 'Beordrede den kæmpestore bronzebuddha i Tōdaiji; hans epidemiramte regeringstid gjorde buddhismen til statens skjold.' },
  jp_koken: { n: 'Kōken', p: 'Nara, Japan', d: 'Sjette regerende kejserinde; indviede Tōdaijis buddha og overlevede fætterens oprør, mens en ministers magt voksede omkring hende.' },
  jp_junnin: { n: 'Junnin', p: 'Nara, Japan', d: 'Afsat efter tre år og sendt af sted for at dø i eksil på Awaji, da den pensionerede kejserinde Kōken generobrede hoffet.' },
  jp_shotoku: { n: 'Shōtoku', p: 'Nara, Japan', d: 'Kōkens anden regeringstid; munken Dōkyō manglede kun en profeti for at nå tronen — Nara-buddhismens store skandale.' },
  jp_konin: { n: 'Kōnin', p: 'Nara, Japan', d: 'Førte Tenji-linjen tilbage til tronen; hans hof, på vagt over for Naras templer, begyndte at planlægge en ny hovedstad.' },
  jp_kanmu: { n: 'Kanmu', p: 'Kyoto, Japan', d: 'Energisk reformator, der flyttede hovedstaden to gange og endte i Heian-kyō (794) — Kyotos tolv århundreders historie begynder.' },
  jp_heizei: { n: 'Heizei', p: 'Kyoto, Japan', d: 'Abdicerede efter tre år og forsøgte at trække hoffet tilbage til Nara — hans oprør blev knust af broderen Saga.' },
  jp_saga: { n: 'Saga', p: 'Kyoto, Japan', d: 'Sejrherre fra oprøret i 810, digterkejser og mæcen for Kūkai; hans regeringstid satte tonen for den forfinede Heian-kultur.' },
  jp_junna: { n: 'Junna', p: 'Kyoto, Japan', d: 'En sparsommelig, boglig kejser, der støttede Kūkais Shingon-skole og strammede ritsuryō-budgetterne.' },
  jp_ninmyo: { n: 'Ninmyō', p: 'Kyoto, Japan', d: 'Jōwa-hændelsen (842) ved hans hof udrensede den gamle garde — udrensningen, der åbnede vejen for Fujiwara-overmagten.' },
  jp_montoku: { n: 'Montoku', p: 'Kyoto, Japan', d: 'En kort, rolig regeringstid, husket som springbrættet for Fujiwara Yoshifusa — snart regent for en barnlig kejser.' },
  jp_seiwa: { n: 'Seiwa', p: 'Kyoto, Japan', d: 'Kronet som otteårig under sin bedstefar Yoshifusa — den første barnlige kejser og det første ægte Fujiwara-regentskab.' },
  jp_yozei: { n: 'Yōzei', p: 'Kyoto, Japan', d: 'Afsat som syttenårig efter lunefulde voldsudfald; manøvren med at erstatte ham rystede regenternes egne regler.' },
  jp_koko: { n: 'Kōkō', p: 'Kyoto, Japan', d: 'Hævet til tronen som femoghalvtredsårig lydig nødløsning; med ham bliver tronen tydeligt en gevinst i Fujiwara Mototsunes hænder.' },
  jp_uda: { n: 'Uda', p: 'Kyoto, Japan', d: 'Støttede sig til ikke-Fujiwara-ministre for at modbalancere regenterne og trak sig tidligt tilbage til et munkelevet ved Ninna-ji.' },
  jp_daigo: { n: 'Daigo', p: 'Kyoto, Japan', d: 'Den gyldne ”Engi”-tid — direkte styre uden regenter; glansen brast, da Sugawara Michizane blev forvist og døde.' },
  jp_suzaku: { n: 'Suzaku', p: 'Kyoto, Japan', d: 'Barnlig kejser, mens Taira no Masakados og Fujiwara Sumitomos oprør rystede riget (Jōhei–Tengyō-tiden).' },
  jp_murakami: { n: 'Murakami', p: 'Kyoto, Japan', d: 'Den sidste regering med direkte kejserstyre — ”Tenryaku no chi”, husket som Heian-kulturen på sit mest selvsikre.' },
  jp_reizei: { n: 'Reizei', p: 'Kyoto, Japan', d: 'Skrøbeligt helbred og partistridigheder: hans korte regeringstid så Anna-hændelsen, udrensningen der styrkede Fujiwara Kanemichi.' },
  jp_enyu: { n: 'En’yū', p: 'Kyoto, Japan', d: 'Kronet som elleveårig under Fujiwara-opsyn; omkring ham størknede regentskabet til fast rutine.' },
  jp_kazan: { n: 'Kazan', p: 'Kyoto, Japan', d: 'Dygtig og alvorlig, men udspejlet af Fujiwara Kaneie; abdicerede som nittenårig og aflagde munkeløfter ved Ninna-ji.' },
  jp_ichijo: { n: 'Ichijō', p: 'Kyoto, Japan', d: 'Heian-pragten på sit højeste: Fujiwara Michinagas opstigen, Sei Shōnagons Pudebogen og Murasaki Shikibus Genji ved hoffet.' },
  jp_sanjo: { n: 'Sanjō', p: 'Kyoto, Japan', d: 'En øjensygdom og Fujiwara Michinagas pres tvang ham til abdikation — hans egne sønner blev sprunget helt over.' },
  jp_go_ichijo: { n: 'Go-Ichijō', p: 'Kyoto, Japan', d: 'Søn af Michinagas datter; med broderen Go-Suzaku tilhørte tronen Fujiwara mere end nogensinde.' },
  jp_go_suzaku: { n: 'Go-Suzaku', p: 'Kyoto, Japan', d: 'En stille regeringstid under Fujiwara Yorimichi; hoffets forfinelse var på sit højeste, mens orden i provinserne stille udhuledes.' },
  jp_go_reizei: { n: 'Go-Reizei', p: 'Kyoto, Japan', d: 'Barnløs; arvefejden mellem rivaliserende Fujiwara-huse begyndte udglidningen mod de hofskabte krige.' },
  jp_go_sanjo: { n: 'Go-Sanjō', p: 'Kyoto, Japan', d: 'Første kejser i 170 år med en ikke-Fujiwara-mor; han tøjlede de domæner, der nærede regenternes rigdom.' },
  jp_shirakawa: { n: 'Shirakawa', p: 'Kyoto, Japan', d: 'Abdicerede for i fire årtier at herske mere end regenterne — hans inseistyre blev magtens nye centrum.' },
  jp_horikawa: { n: 'Horikawa', p: 'Kyoto, Japan', d: 'Barnlig kejser under Shirakawas inseistyre; hofkulturen — poesi, malerkunst, antologier — blomstrede videre.' },
  jp_toba: { n: 'Toba', p: 'Kyoto, Japan', d: 'Trådte tilbage som sekstenårig og kom derefter til at herske over årtiers inseipolitik; hans to huse armerede de kommende borgerkrige.' },
  jp_sutoku: { n: 'Sutoku', p: 'Kyoto, Japan', d: 'Tvunget til abdikation; hans forsøg på at vende tilbage i 1156 udløste Hōgen-krigen, og han døde i eksil i Sanuki.' },
  jp_konoe: { n: 'Konoe', p: 'Kyoto, Japan', d: 'Døde som treogtyveårig; kapløbet om hans efterfølgelse tændte lunten til Hōgen-krigen året efter.' },
  jp_go_shirakawa: { n: 'Go-Shirakawa', p: 'Kyoto, Japan', d: 'Skabte det skæbnesvangre kompromis i 1155; som klosterkejser overlevede han Taira-clanen og holdt de første shōgun i skak i årtier.' },
  jp_nijo: { n: 'Nijō', p: 'Kyoto, Japan', d: 'Kom i kollision med sin klosterlevende far; Heiji-opstanden (1160) udslettede Minamoto Yoshitomo og løftede Taira Kiyomori til overmagt.' },
  jp_rokujo: { n: 'Rokujō', p: 'Kyoto, Japan', d: 'Kronet som spæd, afsat som treårig af Taira Kiyomori — tydeligt bevis på, hvor hofmagten nu lå.' },
  jp_takakura: { n: 'Takakura', p: 'Kyoto, Japan', d: 'Kiyomoris svigersøn; abdicerede for at sætte den Taira-blodede smådreng Antoku på tronen — og riget kogte over.' },
  jp_antoku: { n: 'Antoku', p: 'Kyoto, Japan', d: 'Taira-drengekejseren druknede ved Dan-no-ura (1185), da klanens flåde faldt — sagnet siger, at det kejserlige sværd sank med ham.' },
  jp_go_toba: { n: 'Go-Toba', p: 'Kyoto, Japan', d: 'Digter og mæcen for den anden kejserlige antologi; førte senere hoffets sidste væbnede opstand mod Kamakura — Jōkyū-krigen (1221) — og døde i eksil på Oki.' },
  jp_tsuchimikado: { n: 'Tsuchimikado', p: 'Kyoto, Japan', d: 'Regerede under Minamoto- og Fujiwara-opsyn; forvist efter sin faders mislykkede Jōkyū-krig, døde han langt borte i Awa.' },
  jp_juntoku: { n: 'Juntoku', p: 'Kyoto, Japan', d: 'Sluttede sig til sin far Go-Tobas oprør mod shōgunerne; forvist til Sado efter nederlaget.' },
  jp_chukyo: { n: 'Chūkyō', p: 'Kyoto, Japan', d: 'Indsat som kejser midt i Jōkyū-krigen og afsat inden for få måneder — shōgunernes første afsættelse af en kejser.' },
  jp_go_horikawa: { n: 'Go-Horikawa', p: 'Kyoto, Japan', d: 'Valgt af Kamakura som en sikker voksen; hans regeringstid fæstnede hoffets orden efter krigen under bakufu-opsyn.' },
  jp_shijo: { n: 'Shijō', p: 'Kyoto, Japan', d: 'Døde brat som tiårig; shōgunerne udnyttede overraskelsen til at vride arvefølgen over til Tsuchimikado-linjen.' },
  jp_go_saga: { n: 'Go-Saga', p: 'Kyoto, Japan', d: 'Hans to sønner grundlagde de rivaliserende Jimyōin- og Daikakuji-linjer — aftalen om at skifte til tronen, som senere kløvede hoffet i to.' },
  jp_go_fukakusa: { n: 'Go-Fukakusa', p: 'Kyoto, Japan', d: 'Jimyōin-kejser presset til at abdicere ung til fordel for broren — naget mellem de to linjer blev kun dybere.' },
  jp_kameyama: { n: 'Kameyama', p: 'Kyoto, Japan', d: 'Daikakuji-kejser under det første mongolangreb (1274); linjerne skændtes om hans efterfølger, og aftalen størknede.' },
  jp_go_uda: { n: 'Go-Uda', p: 'Kyoto, Japan', d: 'Kejser under den anden mongolinvasion (1281); patriarch for Daikakuji-linjen i aftalen om at skiftes til tronen.' },
  jp_fushimi: { n: 'Fushimi', p: 'Kyoto, Japan', d: 'Jimyōin-kejser og kalligraf; hans hoflinje blev en stor waka-skole — selv om den reelle magt lå hos bakufu.' },
  jp_go_fushimi: { n: 'Go-Fushimi', p: 'Kyoto, Japan', d: 'Regerede tre år under skifteaftalen; hans vrede protester over vilkårene fordybede fejden mellem de to linjer.' },
  jp_go_nijo: { n: 'Go-Nijō', p: 'Kyoto, Japan', d: 'Forsøgte personligt styre både mod regenter og rivaliserende linje; døde ung og brat som treogtyveårig.' },
  jp_hanazono: { n: 'Hanazono', p: 'Kyoto, Japan', d: 'Dagbogsskrivende, from og kunstinteresseret; hans erindringer om at være holdt uden for magten er et sjældent kejserligt selvportræt fra tiden.' },
  jp_go_daigo: { n: 'Go-Daigo', p: 'Kyoto, Japan', d: 'Væltede Kamakura-shōgunatet (1333) og genindførte kortvarigt direkte styre; da Ashikaga Takauji vendte sig imod ham, grundlagde hans modstand det Sydlige Hof.' },
  jp_go_murakami: { n: 'Go-Murakami', p: 'Kyoto, Japan', d: 'Kejser for det Sydlige Hof, som regerede fra Yoshino og flyttede lejr; hans linje bevarede de ”ægte” kejserlige insignier gennem årtiers krig.' },
  jp_chokei: { n: 'Chōkei', p: 'Kyoto, Japan', d: 'Sydlig kejser i lang tilbagetog; Yoshino-sagen blegned, efterhånden som krigerkoalitionerne skiftede til det ashikagiske Nord.' },
  jp_go_kameyama: { n: 'Go-Kameyama', p: 'Kyoto, Japan', d: 'Sidste sydlige kejser; udleverede insignierne til Nord i 1392 og ”forenede” dermed hoffene på Nords vilkår.' },
  jp_kogon: { n: 'Kōgon', p: 'Kyoto, Japan', d: 'Indsat af Hōjō-regenterne efter Go-Daigos første opstand; strøget af tavlen, da Go-Daigo vendte tilbage i 1333.' },
  jp_komyo: { n: 'Kōmyō', p: 'Kyoto, Japan', d: 'Ashikaga Takaujis første nordlige kejser efter Kenmu-restaurationens sammenbrud; de ægte insignier forblev i syd.' },
  jp_suko: { n: 'Sukō', p: 'Kyoto, Japan', d: 'Nordlig kejser, afsat midt i Kan’ō-urolighederne — Ashikaga-brødrenes fejde, der rystede begge hoffer.' },
  jp_go_kogon: { n: 'Go-Kōgon', p: 'Kyoto, Japan', d: 'En lang nordlig regeringstid, mens den sydlige lejr strejfede omkring; Kyotos hofkultur overlevede på krigens nordside.' },
  jp_go_enyu: { n: 'Go-En’yū', p: 'Kyoto, Japan', d: 'Nordlig kejser, mens Yoshimitsus shōgunat voksede frem; abdicerede til fordel for den unge Go-Komatsu, hvis regering skulle forene hoffene.' },
  jp_go_komatsu: { n: 'Go-Komatsu', p: 'Kyoto, Japan', d: 'Sidste nordlige tronprætendent og derefter enekejser efter unionen i 1392 — første hersker over den genforenede kejserlinje.' },
  jp_shoko: { n: 'Shōkō', p: 'Kyoto, Japan', d: 'Døde barnløs; tronen sprang til en sidegren, og skifteaftalen mellem de to linjer udløb stille.' },
  jp_go_hanazono: { n: 'Go-Hanazono', p: 'Kyoto, Japan', d: 'Hans seksogtrediveårige regering endte tre år før Ōnin-krigen — den sidste ro, før Kyoto brændte.' },
  jp_go_tsuchimikado: { n: 'Go-Tsuchimikado', p: 'Kyoto, Japan', d: 'Kejser gennem Ōnin-krigen (1467–77), der slugte Kyoto; hoffet blev fattigt, provinspræget og overset.' },
  jp_go_kashiwabara: { n: 'Go-Kashiwabara', p: 'Kyoto, Japan', d: 'Så fattig, at hans kroning blev udsat i enogtyve år — kejsertronen på sit dybeste punkt.' },
  jp_go_nara: { n: 'Go-Nara', p: 'Kyoto, Japan', d: 'Regerede gennem Sengoku-krigene; tronen overlevede på lån, gaver og salg af kejserlig kalligrafi.' },
  jp_ogimachi: { n: 'Ōgimachi', p: 'Kyoto, Japan', d: 'Så Nobunaga slå sig ned i Kyoto (1568) og genoprette hoffets finanser; abdicerede til fordel for Go-Yōzei.' },
  jp_go_yozei: { n: 'Go-Yōzei', p: 'Kyoto, Japan', d: 'Indsat under Toyotomi Hideyoshi og sat til side af Tokugawa — hans regeringstid spænder over Japans genforening og Edos erobring af politiken.' },
  jp_go_mizunoo: { n: 'Go-Mizunoo', p: 'Kyoto, Japan', d: 'Gift med shōgunens datter, hvilket forseglede forliget mellem hof og bakufu; den senere strid om de lilla kapper til templerne forsurede forholdet.' },
  jp_meisho: { n: 'Meishō', p: 'Kyoto, Japan', d: 'Syvende regerende kejserinde — den første i 850 år; abdicerede til fordel for halvbroderen Go-Kōmyō.' },
  jp_go_komyo: { n: 'Go-Kōmyō', p: 'Kyoto, Japan', d: 'En ildfuld ung kritiker af shōgunatets hovmod; døde som toogtyveårig midt i vedvarende rygter om gift.' },
  jp_go_sai: { n: 'Go-Sai', p: 'Kyoto, Japan', d: 'Hævet til tronen efter Go-Kōmyōs pludselige død; abdicerede til fordel for Reigen og grundlagde Go-Sai-linjen som hoffets reserve.' },
  jp_reigen: { n: 'Reigen', p: 'Kyoto, Japan', d: 'Abdicerede tidligt og tilbragte tredive år som en formidabel klosterkejser — den sidste med reel politisk tyngde.' },
  jp_higashiyama: { n: 'Higashiyama', p: 'Kyoto, Japan', d: 'Genroku-pragten — Chikamatsus skuespil, Bashōs haiku — blomstrede, mens den reelle magt sad i Edo.' },
  jp_nakamikado: { n: 'Nakamikado', p: 'Kyoto, Japan', d: 'Regerede gennem Kyōhō-reformerne; hoffets værdighed kom sig, efterhånden som shōgunernes finanser gik ned ad bakke.' },
  jp_sakuramachi: { n: 'Sakuramachi', p: 'Kyoto, Japan', d: 'Sammen med rådgiveren Kanamori reddede han hoffets finanser og genoplivede ceremonier, der længe havde ligget brak — en stille kejserlig renæssance.' },
  jp_momozono: { n: 'Momozono', p: 'Kyoto, Japan', d: 'Døde som enogtyveårig; tronen gik til hans søster — Japans næstsidste regerende kejserinde.' },
  jp_go_sakuramachi: { n: 'Go-Sakuramachi', p: 'Kyoto, Japan', d: 'Tiende og sidste regerende kejserinde; en omhyggelig værge for sin unge nevø og en skarpsindig hoffigur i mange år efter.' },
  jp_go_momozono: { n: 'Go-Momozono', p: 'Kyoto, Japan', d: 'Døde barnløs som nittenårig uden at udpege en arving; hoffet improviserede en adoption for at holde arvefølgen ubrudt.' },
  jp_kokaku: { n: 'Kōkaku', p: 'Kyoto, Japan', d: 'Valgt fra en sidegren som otteårig; en kraftfuld lang regeringstid, der genopbyggede kejserdømmets prestige på tærsklen til bakumatsu.' },
  jp_ninko: { n: 'Ninkō', p: 'Kyoto, Japan', d: 'En from og flittig kejser; hans regeringstid så hungersnød, Tenpō-reformerne og de første drøn af spørgsmålet om udlændinge.' },
  jp_komei: { n: 'Kōmei', p: 'Kyoto, Japan', d: 'Kompromisløst imod udlændinge; hans hofdekreter mod Japans åbning gav næring til bakumatsu-krisen — døde brat som sexogtrediveårig.' },
  jp_meiji: { n: 'Meiji', p: 'Tokyo, Japan', d: 'Kejseren bag moderniseringsmiraklet efter restaurationen: forfatning, jernbaner, industri — og sejre over Kina og Rusland.' },
  jp_taisho: { n: 'Taishō', p: 'Tokyo, Japan', d: 'Skrøbeligt helbred holdt ham ude af politiken og flyttede magten til partiregeringerne — Japans korte ”Taishō-demokrati”.' },
  jp_showa: { n: 'Shōwa (Hirohito)', p: 'Tokyo, Japan', d: 'Regerede gennem krig, nederlag, besættelse og et økonomisk mirakel — toogtredive år, den længste regeringstid i japansk historie.' },
  jp_akihito: { n: 'Akihito', p: 'Tokyo, Japan', d: 'Heisei-kejseren, der gjorde tronen til en stemme for fred og erindring; abdicerede frivilligt — den første i to århundreder.' },
  jp_naruhito: { n: 'Naruhito', p: 'Tokyo, Japan', d: 'Reiwa-æraens kejser, historiker med fokus på middelalderens vandveje; det symbolske kongedømme fortsætter ind i et fjerde årti af fred.' },
});

/* Roman rulers (189 entries) — 2026-10-29 */
Object.assign(window.DATA_DA, {
  rk_romulus: { n: 'Romulus', p: 'Rom', d: 'Legendarisk grundlægger og første konge; ifølge romersk myte opfostret af en ulvinde gav han sit navn til byen, dens første legioner og dens første senatorer.' },
  rk_numa: { n: 'Numa Pompilius', p: 'Rom', d: 'Den fromme anden konge, som får æren for Roms kalender, dets præsteskaber og Janus-templet, hvis porte holdt sig lukkede i fredstid.' },
  rk_tullus: { n: 'Tullus Hostilius', p: 'Rom', d: 'Den krigerske tredje konge, der ødelagde Alba Longa og flyttede dets folk til Rom — et styre, som legenderne slutter med pest og tordenlyn.' },
  rk_ancus: { n: 'Ancus Marcius', p: 'Rom', d: 'Barnebarn af Numa; han udvidede Rom til havet ved at grundlægge Ostia og spændte over Tiberen med den første Pons Sublicius.' },
  rk_tarquinius_priscus: { n: 'Tarquinius Priscus', p: 'Rom', d: 'Femte konge, etrusker af fødsel; han drænede Forum, begyndte Circus Maximus og lovede det store Jupiter-tempel på Kapitol.' },
  rk_servius_tullius: { n: 'Servius Tullius', p: 'Rom', d: 'Sjette konge og stor reformator — han talte Roms befolkning ind i stammer og centurier og skabte folketællingen, forsamlingerne og Serviusmuren.' },
  rk_superbus: { n: 'Tarquinius Superbus', p: 'Rom', d: 'Den sidste, tyranniske konge; vreden over hans familie udløste oprøret i 509 f.Kr., der endte monarkiet og grundlagde republikken.' },
  rr_brutus: { n: 'Lucius Junius Brutus', p: 'Rom', d: 'Republikkens første konsul; han jog tarquinierne ud og henrettede sine egne sønner for at have sammensvoret om deres tilbagevenden.' },
  rr_publicola: { n: 'Publius Valerius Publicola', p: 'Rom', d: 'Fire gange konsul og folkets ven — hans love tog økserne fra liktorerne og gav den unge republik dens forfatning.' },
  rr_cincinnatus: { n: 'Cincinnatus', p: 'Rom', d: 'Indkaldt fra plogen for at blive diktator slog han aequierne på seksten dage og gav straks den højeste magt fra sig.' },
  rr_camillus: { n: 'Camillus', p: 'Rom', d: 'Erobreren af Veii og Roms anden grundlægger — han reddede byen, efter at gallerne brændte den i 390 f.Kr.' },
  rr_appius_claudius: { n: 'Appius Claudius Caecus', p: 'Rom', d: 'Censor, der byggede Via Appia og Roms første vandledning; blind og gammel overtalte han senatet til at nægte fred med Pyrrhos.' },
  rr_fabius_cunctator: { n: 'Fabius Maximus Cunctator', p: 'Rom', d: 'Diktator efter, at Hannibal havde knust Rom ved Trasimeno; hans forsinkende “fabianske strategi” reddede staten — og skaffede ham de dristiges had.' },
  rr_scipio_africanus: { n: 'Scipio Africanus', p: 'Rom', d: 'Roms bedste hærfører; han bar krigen til Afrika og besejrede Hannibal ved Zama i 202 f.Kr. og afsluttede dermed den anden punerkrig.' },
  rr_cato: { n: 'Cato den Ældre', p: 'Rom', d: 'Censor af streng, gammel romersk dyd; han afsluttede hver tale med “Kartago skal ødelægges” — og den tredje punerkrig fulgte.' },
  rr_tiberius_gracchus: { n: 'Tiberius Gracchus', p: 'Rom', d: 'Tribun, der forsøgte at give offentlig jord til de fattige; slået ihjel af senatorer på Forum — republikkens første politiske blodbad i generationer.' },
  rr_gaius_gracchus: { n: 'Gaius Gracchus', p: 'Rom', d: 'Yngre bror og radikal tribun bag kornuddelingen og udvidet statsborgerskab; jaget ned og dræbt, da senatet slog tilbage.' },
  rr_marius: { n: 'Gaius Marius', p: 'Rom', d: 'Syv gange konsul; han åbnede legionerne for mænd uden jord og udslettede kimbrerne og teutonerne — men hans fejde med Sulla fik Rom til at bløde.' },
  rr_sulla: { n: 'Sulla', p: 'Rom', d: 'Første hærfører, der marcherede mod Rom selv; som diktator slagtede han fjender gennem proskriptionslister og gav derefter — forbløffende nok — magten tilbage.' },
  rr_pompey: { n: 'Pompeius den Store', p: 'Rom', d: 'Rensede havet for pirater og erobrede Østen, tre gange konsul og Caesars store rival — myrdet på en egyptisk strand efter Pharsalos.' },
  rr_crassus: { n: 'Marcus Licinius Crassus', p: 'Rom', d: 'Den rigeste mand i Rom og den tredje i det første triumvirat; han marcherede mod Parthien for ærens skyld og døde ved Carrhae med sine legioner tabt i ørkenen.' },
  rr_cicero: { n: 'Cicero', p: 'Rom', d: 'Konsul, der afslørede den catilarianske sammensværelse med sine taler; Roms største taler og en varig stemme for forfatningsmæssig frihed.' },
  rr_m_brutus: { n: 'Marcus Junius Brutus', p: 'Rom', d: 'Caesars ven og republikkens sidste forsvarer — leder af frigørerne, der dræbte diktatoren, besejret og død ved Filippi.' },
  rr_cassius: { n: 'Gaius Cassius Longinus', p: 'Rom', d: 'Den drivende hjerne bag idus i marts; han rejste Østen mod triumvirerne og døde ved Filippi, vildledt af en falsk melding.' },
  rr_lepidus: { n: 'Lepidus', p: 'Rom', d: 'Den tredje i det andet triumvirat, altid den mindre part; presset ud af Oktavian og efterladt til at ende sine dage som Pontifex Maximus.' },
  rr_antony: { n: 'Marcus Antonius', p: 'Rom', d: 'Briljant hærfører og triumvir, Caesars højre hånd; hans allianse — og kærlighed — med Kleopatra endte ved Actium og et selvmords sværd.' },
  rr_octavian: { n: 'Oktavian', p: 'Rom', d: 'Caesars atten år gamle arving, der overlevede og besejrede hver rival; i 27 f.Kr. omdøbte senatet ham til Augustus — monarki i republikansk klædning.' },
  re_augustus: { n: 'Augustus', p: 'Rom', d: 'Første kejser; han bevarede republikkens skal, mens han selv styrede alt — fyrre år med fred, der fandt Rom i tegl og efterlod det i marmor.' },
  re_tiberius: { n: 'Tiberius', p: 'Rom', d: 'Modvillig, briljant og sur kejser, der trak sig tilbage til Capri og lod pretorianeren Sejanus terrorisere Rom med forræderirettssager.' },
  re_caligula: { n: 'Caligula', p: 'Rom', d: 'Ung kejser, der begyndte elsket og endte som et udyr — kilderne anklager ham for grusomhed, spildt guld og planer om at gøre sin hest til konsul.' },
  re_claudius: { n: 'Claudius', p: 'Rom', d: 'Den stammende lærd, ingen regnede med; han erobrede Britannien, drænede Fucino-søen og styrede riget med uventet kompetence.' },
  re_nero: { n: 'Nero', p: 'Rom', d: 'Moremyrder og showman af en kejser; Rom brændte i 64, han skyldte på de kristne, byggede det gyldne hus — og senatet erklærede ham folkefjende.' },
  re_galba: { n: 'Galba', p: 'Rom', d: 'De fire kejsers år begynder: en streng gammel general, myrdet af pretorianerne efter syv måneder med gerrige reformer.' },
  re_otho: { n: 'Otho', p: 'Rom', d: 'Pretorianernes yndling, der regerede femoghalvfems dage og tabte Bedriacum til Vitellius — og dræbte sig selv, for at borgerkrigen ikke skulle vokse.' },
  re_vitellius: { n: 'Vitellius', p: 'Rom', d: 'Den gladspiste sejrherre fra det første Bedriacum; otte måneder senere brændte de flaviske hære Cremona og slæbte ham gennem Rom til hans død.' },
  re_vespasian: { n: 'Vespasian', p: 'Rom', d: 'Den kløgtige general fra muldyrhandelen, der endte borgerkrigen, begyndte Colosseum — og beskattede urin for at fylde statskassen igen.' },
  re_titus: { n: 'Titus', p: 'Rom', d: 'Elsket kejser i ulykkernes tid: han fuldendte Colosseum, begravde Vesuvs døde, bekæmpede den store brand i 80 — og døde alt for tidligt.' },
  re_domitian: { n: 'Domitian', p: 'Rom', d: 'Effektiv autokrat og skrækken for aristokratiet; han genopbyggede Rom, befæstede linjen Rhinen–Donau — og døde i et paladskomplot.' },
  re_nerva: { n: 'Nerva', p: 'Rom', d: 'Aldrende senator, løftet frem for at genoprette friheden efter Domitian; barnløs adopterede han Trajan og åbnede de fem gode kejseres tidsalder.' },
  re_trajan: { n: 'Trajan', p: 'Rom', d: '“Bedst af fyrster” — under ham nåede Rom sin største udstrækning, fra de dakiske guldminer til den Persiske Golf, og Forum fik sin søjle.' },
  re_hadrian: { n: 'Hadrian', p: 'Rom', d: 'Den rejsende bygmesterkejser, der konsoliderede grænserne — Hadrians Mur, Pantheon — og omdøbte Judæa, efter at have knust dets oprør.' },
  re_antoninus_pius: { n: 'Antoninus Pius', p: 'Rom', d: 'Den roligste regeringstid i romersk historie — treogtyve år uden større krig, riget på sit mest blomstrende, Antoninusmuren ved grænsen.' },
  re_marcus_aurelius: { n: 'Marcus Aurelius', p: 'Rom', d: 'Filosofen på tronen; han skrev Meditationerne i lejren, mens pest og markomanniske indtrængende hamrede på Donau-grænsen.' },
  re_lucius_verus: { n: 'Lucius Verus', p: 'Rom', d: 'Medkejser med Marcus Aurelius; han vandt den partiske krig, mens hans generaler gjorde arbejdet, og døde af pest på hjemvejen.' },
  re_commodus: { n: 'Commodus', p: 'Rom', d: 'Marcus Aurelius’ søn og Roms mareridt; han kæmpede som gladiator i sin egen arena, omdøbte månederne efter sig selv — og blev kvalt af en bryder.' },
  re_pertinax: { n: 'Pertinax', p: 'Rom', d: 'Streng søn af en frigivet slave; pretorianerne — allerede solgt til Didius Julianus — dræbte ham efter syvogfirs dage med disciplin.' },
  re_didius_julianus: { n: 'Didius Julianus', p: 'Rom', d: 'Han købte riget på pretorianernes auktion — og mistede det på ni uger til Septimius Severus, marcherende fra Donau.' },
  re_septimius_severus: { n: 'Septimius Severus', p: 'Rom', d: 'Soldaterkejser født i Afrika og grundlægger af det severanske dynasti; hans dødsråd — berig soldaterne, foragt alt det andet.' },
  re_caracalla: { n: 'Caracalla', p: 'Rom', d: 'Drabsmanden på sin bror Geta og på sin egen pretorianerpræfekt; hans edikt i 212 gjorde enhver fri indbygger i riget til romersk borger.' },
  re_geta: { n: 'Geta', p: 'Rom', d: 'Caracallas bror og med-Augustus i to år; myrdet i deres mors arme, hans minne fordømt og hans navn mejslet væk fra monumenterne.' },
  re_macrinus: { n: 'Macrinus', p: 'Antiokia', d: 'Pretorianerpræfekt, der tog purpuren efter Caracallas mord — den første kejser uden for senatsklassen; fjorten måneder senere var han død.' },
  re_elagabalus: { n: 'Elagabalus', p: 'Rom', d: 'Teenage-præstkejser for den syriske solgud El-Gabal; hans skandaler vækkede så megen væmmelse hos pretorianerne, at de dræbte ham og hans mor i lejren.' },
  re_severus_alexander: { n: 'Severus Alexander', p: 'Rom', d: 'Styret af sin mor Julia Mamaea; mild og rådgivet af den store jurist Ulpian — og myrdet i Mainz, da hæren ville have en hårdere mand.' },
  re_maximinus_thrax: { n: 'Maximinus Thrax', p: 'Rom', d: 'Kæmpestor bondegeneral, den første af soldaterkejserne; tre års endeløs krig, før egne tropper dræbte ham uden for Aquileia.' },
  re_gordian_i: { n: 'Gordian I', p: 'Kartago', d: 'Velhavende prokonsul, udråbt til kejser i Afrika mod Maximinus; efter seksogtredive dage besejret — han hængte sig med sit kappebælte.' },
  re_gordian_ii: { n: 'Gordian II', p: 'Kartago', d: 'Søn og partner af Gordian I; han faldt i slaget foran Kartago, og hans far fulgte ham i døden inden for timer.' },
  re_pupienus: { n: 'Pupienus', p: 'Rom', d: 'Senatorkejser, valgt af senatet til at møde Maximinus; tyrannens hær havde allerede dræbt ham — derefter dræbte pretorianerne også Pupienus.' },
  re_balbinus: { n: 'Balbinus', p: 'Rom', d: 'Pupienus’ tvistende medkejser, valgt for at blide folket; begge blev slæbt ud af paladset og dræbt af pretorianerne.' },
  re_gordian_iii: { n: 'Gordian III', p: 'Rom', d: 'Tretten år gammel barnebarn af den første Gordian; han marcherede mod Persien og vandt ved Resaena — og blev fortrængt af sin egen præfekt Philippus.' },
  re_philip_arab: { n: 'Philippus Arabs', p: 'Rom', d: 'Han sluttede fred med Persien og fejrede Roms tusindårsdag med pragtfulde lege — så faldt han for Decius nær Verona.' },
  re_decius: { n: 'Decius', p: 'Rom', d: 'Befalede den rigsdækkende forfølgelse af kristne; han og hans søn døde i kamp mod goterne ved Abritus — de første kejsere dræbt af barbarer.' },
  re_trebonianus_gallus: { n: 'Trebonianus Gallus', p: 'Rom', d: 'Han købte fred fra goterne med guld, pesten kom alligevel — og hans egne soldater overgav ham til Aemilianus ved Interamna.' },
  re_aemilian: { n: 'Aemilianus', p: 'Rom', d: 'Tre måneder som kejser; udråbt for at have slået goterne tilbage, myrdet af egne mænd, da Valerian marcherede fra Rhinen.' },
  re_valerian: { n: 'Valerian', p: 'Rom', d: 'Den eneste kejser, der nogensinde blev taget til fange i slag — taget levende ved Edessa af den persiske konge Shapur I, hvis fange han forblev til sin død.' },
  re_gallienus: { n: 'Gallienus', p: 'Rom', d: 'Medregent, mens faren sad i fangenskab, blev han en briljant, dødsdømt improvisator — han holdt kernen, mens Gallien og Palmyra brød ud, til han faldt for egne officerer.' },
  re_claudius_gothicus: { n: 'Claudius Gothicus', p: 'Rom', d: 'Kavalerigeneral, der knuste goterne ved Naissus; pesten hentede ham, før han kunne samle det knuste rige igen.' },
  re_quintillus: { n: 'Quintillus', p: 'Rom', d: 'Claudius’ bror, valgt af senatet mod hærens vilje; et klogt selvmord efter nogle få dage løste striden.' },
  re_aurelian: { n: 'Aurelian', p: 'Rom', d: 'Verdens genopretter — han tog Zenobia af Palmyra og det galliske rige tilbage, byggede Roms sidste mur — og døde i officerernes komplot.' },
  re_tacitus: { n: 'Tacitus', p: 'Rom', d: 'En femoghalvfjerdsårig senator, hæren valgte efter et interregnum; han døde i Tyana, på vej østpå mod gotere og persere.' },
  re_florianus: { n: 'Florianus', p: 'Rom', d: 'Tacitus’ halvbror; Østhærene nægtede at acceptere ham og udråbte Probus — uger senere dræbte egne mænd ham i Tarsos.' },
  re_probus: { n: 'Probus', p: 'Rom', d: 'Genopretter af Rhinens og Donaus grænser, plantede vinmarker op ad Donaudalen; hans soldater, sat til afvandingsarbejde, dræbte ham i Sirmium.' },
  re_carus: { n: 'Carus', p: 'Rom', d: 'Pretorianerpræfekt blevet kejser; han slog quadierne og sarmaterne, men døde — legenden siger ramt af lyn — før han indtog Ktesifon.' },
  re_carinus: { n: 'Carinus', p: 'Rom', d: 'Carus’ ældste søn, luksuselskende og grusom; han vandt slaget ved Margus — og blev dræbt der af en tribun, hvis hustru han havde forført.' },
  re_numerian: { n: 'Numerian', p: 'Rom', d: 'Carus’ yngre søn, digter og taler; svigerfaren Aper blev fundet sammen med drengens lig — Diokletian huggede ham ned foran hæren.' },
  re_diocletian: { n: 'Diokletian', p: 'Nikomedia', d: 'Den store omorganisator: tetrarkiet, dobbelt så mange provinser, prisediktter, den store kristenforfølgelse — og så den første kejser, der gik frivilligt af, for at dyrke kål i Split.' },
  re_maximian: { n: 'Maximian', p: 'Milano', d: 'Diokletians rå medkejser i vest, i kamp mod røvere, briter og tronranere; tvunget til at abdicere sammen med sin kollega, intrigerede han til det sidste.' },
  re_constantius_chlorus: { n: 'Constantius Chlorus', p: 'Trier', d: 'Tetrarkiets vestlige Cæsar, derefter Augustus; han generobrede Britannien fra Allectus og døde i York, efter at have udnævnt sin søn Konstantin til arving.' },
  re_galerius: { n: 'Galerius', p: 'Sirmium', d: 'Arkitekten bag den store kristenforfølgelse; døende i kvaler ophævede han den med edikt i 311 — en ændring, kristne huskede med ærefrygt.' },
  re_severus_ii: { n: 'Severus II', p: 'Milano', d: 'Constantius’ Cæsar, forfremmet til Augustus; Maxentius’ oprør og Maximians forræderi udleverede ham til henrettelse uden for Rom.' },
  re_maxentius: { n: 'Maxentius', p: 'Rom', d: 'Tronraneren ved Tiberen, der druknede i den — hans hær brød sammen ved Milviske Bro mod Konstantins korstegn.' },
  re_maximinus_daza: { n: 'Maximinus Daza', p: 'Antiokia', d: 'Den vildeste af forfølgerne; Galerius’ nevø kæmpede Licinius tilbage til Taurus, døde så af sygdom i Tarsos — med forfølgelsen ophævet.' },
  re_constantine_i: { n: 'Konstantin den Store', p: 'Konstantinopel', d: 'Søn af Constantius; han samlede riget efter Milviske Bro, legaliserede kristendommen og grundlagde Konstantinopel som et nyt Rom.' },
  re_licinius: { n: 'Licinius', p: 'Sirmium', d: 'Konstantins svoger og sidste rival; besejret ved Chrysopolis, afsat trods et løfte om sikkerhed — og henrettet inden for et år.' },
  re_constantine_ii: { n: 'Konstantin II', p: 'Trier', d: 'Konstantins ældste søn; han krævede mere af vesten fra sine brødre og blev dræbt i et baghold ved Aquileia, treogtredive år gammel.' },
  re_constans: { n: 'Constans', p: 'Milano', d: 'Konstantins yngste søn, sejrherre over sin bror Konstantin II; han fremmedgjorde hæren med yndlinger og døde på flugt fra Magnentius’ kup.' },
  re_constantius_ii: { n: 'Constantius II', p: 'Konstantinopel', d: 'Mistankefuld, længe regerende midterste søn og arianer; han kæmpede mod Persien og et dusin tronranere og døde af feber på vej for at kæmpe mod Julian.' },
  re_julian: { n: 'Julian den frafaldne', p: 'Antiokia', d: 'Filosofkejser, der forsøgte at vække de gamle guder til live og skære hofspild; han døde af et sår i Persien-felttoget, enogtredive år gammel.' },
  re_jovian: { n: 'Jovian', p: 'Ancyra', d: 'Valgt under tilbagetrækningen fra Ktesifon; han købte hærens vej ud med persisk territorium og døde otte måneder senere i Ancyra, i sin fars hus.' },
  re_valentinian_i: { n: 'Valentinian I', p: 'Trier', d: 'Pannonisk soldat, der delte riget med sin bror Valens; han forsvarede Rhinen vildt og døde af raseri, råbende til udsendinge.' },
  re_valens: { n: 'Valens', p: 'Konstantinopel', d: 'Østkejser under sin bror; han lod de gotiske flygtninge krydse Donau, kæmpede mod dem halvt ubevæbnede — og brændte levende ved Adrianopel.' },
  re_gratian: { n: 'Gratian', p: 'Trier', d: 'Begavet søn af Valentinian I, delagtig i magten fra barndommen; han droppede den hedenske titel Pontifex Maximus — og blev forladt af sin hær til fordel for tronraneren Maximus.' },
  re_valentinian_ii: { n: 'Valentinian II', p: 'Milano', d: 'Barnekejser, først marionet for sin mor Justina, så for Theodosius; fundet hængt i Vienne — Ambrosius prædikede hans begravelse.' },
  re_theodosius_i: { n: 'Theodosius den Store', p: 'Konstantinopel', d: 'Sidste kejser, der styrede begge halvdele; han gjorde nikænsk kristendom til statsreligion og efterlod sine sønner øst og vest — en deling, der aldrig helede.' },
  re_honorius: { n: 'Honorius', p: 'Ravenna', d: 'Den intet-gørende kejser i Ravenna, der fik Stilicho dræbt; Alarik plyndrede Rom i 410, mens han, snerrede man, passede sine høns.' },
  re_constantius_iii: { n: 'Constantius III', p: 'Ravenna', d: 'Generalen, der trak vesten tilbage fra randen — tronranere knust, gotere bosat i Gallien — medkejser i syv måneder, før lungebetændelsen tog ham.' },
  re_joannes: { n: 'Johannes', p: 'Ravenna', d: 'Overnotar, der blev kejser, da Honorius døde; Aetius kom med hunner for sent til at redde ham fra Galla Placidias østhær.' },
  re_valentinian_iii: { n: 'Valentinian III', p: 'Rom', d: 'Galla Placidias dreng på den vestlige trone; han tabte Afrika til vandalerne, dræbte Aetius med egne hænder — og blev hugget ned af Aetius’ mænd.' },
  re_petronius_maximus: { n: 'Petronius Maximus', p: 'Rom', d: 'Senatoren bag mordet på Aetius og Valentinian; to måneders magt — sluttet med, at den romerske mængde stenede ham, mens vandalflåden lukkede sig ind.' },
  re_avitus: { n: 'Avitus', p: 'Arles', d: 'Gallo-romersk aristokrat, gjort til kejser med visigotisk hjælp; Ricimer afsatte ham, og han endte sine dage som biskop i Piacenza.' },
  re_majorian: { n: 'Majorian', p: 'Ravenna', d: 'Den sidste vestkejser, der virkelig forsøgte — love mod skattemisbrug stadig citeret, en generobringsflåde tabt ved Cartagena; Ricimer lod ham klæde af og halshugge.' },
  re_libius_severus: { n: 'Libius Severus', p: 'Ravenna', d: 'Ricimers skyggekejser, aldrig anerkendt af øst; han døde i Rom — forgiftet, sagde rygtet, af sin egen protektor.' },
  re_anthemius: { n: 'Anthemius', p: 'Rom', d: 'Østens valg, en græker fra en stor arkitektslægt; hans felttog mod vandalerne mislykkedes, og Ricimer belejrede og dræbte ham.' },
  re_olybrius: { n: 'Olybrius', p: 'Rom', d: 'Gift ind i det theodosianske dynasti, Ricimers valg som kejser; syv stille måneder — så vattersot, med det vestlige rige fire år fra udslettelse.' },
  re_glycerius: { n: 'Glycerius', p: 'Ravenna', d: 'Gundobads udnævnelse efter Ricimers død; Julius Nepos gik i land ved Portus, hæren deserterede — og Glycerius endte som biskop i Salona.' },
  re_julius_nepos: { n: 'Julius Nepos', p: 'Salona', d: 'Østens legitime vestkejser; Orestes jagede ham til Dalmatien i 475 — han holdt Salona, indtil sin egen hushovmester knivstak ham.' },
  re_romulus_augustulus: { n: 'Romulus Augustulus', p: 'Ravenna', d: 'Drengen “lille Augustus” — den sidste vestkejser; Odoaker pensionerede ham af til Campanien, og det vestlige rige ophørte simpelthen.' },
  bz_arcadius: { n: 'Arcadius', p: 'Konstantinopel', d: 'Første kejser af den blivende østlige halvdel — en svag yngling styret af ministre som Rufinus og evnukken Eutropius, mens vesten faldt fra hinanden.' },
  bz_theodosius_ii: { n: 'Theodosius II', p: 'Konstantinopel', d: 'Toogfyrre år med den boglige kejser, hvis Theodosianske Lovværk og Theodosius-mure i Konstantinopel overlevede ham med et årtusinde.' },
  bz_marcian: { n: 'Marcian', p: 'Konstantinopel', d: 'Soldaterkejser gift med Pulcheria; han nægtede Attila skat — guld til sine soldater, intet til fjenden — og koncilet i Chalkedon blev afholdt under ham.' },
  bz_leo_i: { n: 'Leo I', p: 'Konstantinopel', d: 'Første kejser, kronet af patriarken; han brød goternes greb om hæren med isauriske rekrutter — og den store flåde mod vandalernes Kartago led skibbrud ved Kap Bon.' },
  bz_leo_ii: { n: 'Leo II', p: 'Konstantinopel', d: 'Barnebarn af Leo I og Zeno, kronet som seksårig, død af feber som syvårig — tronen gik til hans far Zeno.' },
  bz_zeno: { n: 'Zeno', p: 'Konstantinopel', d: 'Isaurisk kejser to gange næsten styrtet — af Basiliscus, så af oprør; hans Henotikon forsøgte at lukke kirkestriden, og det vestlige rige ophørte i hans regeringstid.' },
  bz_basiliscus: { n: 'Basiliscus', p: 'Konstantinopel', d: 'Tronraner og bror af kejserinden Verina — admiralen, der mistede Kap Bon-flåden; hans monofysitiske edikter udløste optøjer, og Zeno vendte uimodsagt tilbage.' },
  bz_anastasius_i: { n: 'Anastasius I', p: 'Konstantinopel', d: 'Omsorgsfuld finansgeni — 320.000 pund guld i reserve, den lange mur bygget, møntvæsenet reformeret; folkemængder gjorde oprør over hans monofysitiske sympatier.' },
  bz_justin_i: { n: 'Justin I', p: 'Konstantinopel', d: 'Illyrisk bondevagt, løftet op af hæren; han hælede det akacianske skisma med Rom og ryddede vejen for sin nevø Justinian.' },
  bz_justinian_i: { n: 'Justinian den Store', p: 'Konstantinopel', d: 'Den sidste latinsktalende kejser og den travleste: generobringen af Afrika og Italien, Corpus Iuris, Hagia Sofia — og overlevet Nika-optøjerne og pesten.' },
  bz_justin_ii: { n: 'Justin II', p: 'Konstantinopel', d: 'Nevø af Justinian; hans persiske og italienske krige tømte statskassen, hans sind gav sig — og han udnævnte Tiberius til arving for at spare riget en arvefølgekrig.' },
  bz_tiberius_ii: { n: 'Tiberius II', p: 'Konstantinopel', d: 'Den gavmilde kejser — han delte Justinians opsparede skat ud i soldaterløn og fattighjælp; Persien og avarerne tog provinser til gengæld.' },
  bz_maurice: { n: 'Maurikios', p: 'Konstantinopel', d: 'Soldaterlærd, der vandt den persiske krig ved at støtte Khosrow II og skrev Strategikon — og så blev henrettet af Fokas med de seks sønner for øjnene.' },
  bz_phocas: { n: 'Fokas', p: 'Konstantinopel', d: 'Centurionen, hvis mytteri indledte rigets mørkeste århundrede; hans skrækvælde sluttede, da Herakleios’ flåde dukkede op foran Konstantinopel.' },
  bz_heraclius: { n: 'Herakleios', p: 'Konstantinopel', d: 'Han trak riget tilbage fra dødens dør — Ktesifon taget, det sande kors genvundet — for derefter at se Syrien, Egypten og Armenien falde til araberne.' },
  bz_constantine_iii: { n: 'Konstantin III', p: 'Konstantinopel', d: 'Herakleios’ ældste søn; han regerede fire måneder og døde af tuberkulose — eller gift, mistænkte mængden — mens Martinas fraktion cirklede.' },
  bz_heraklonas: { n: 'Heraklonas', p: 'Konstantinopel', d: 'Herakleios’ søn med sin niece Martina; lemlæstelsesoptøjerne i september 641 afsatte ham — næsen skåret op — og slægten var slut.' },
  bz_constans_ii: { n: 'Constans II', p: 'Konstantinopel', d: 'Barnebarn af Herakleios; han kæmpede mod arabiske flåder ved mastene, stod i strid med kirken, flyttede til Syrakus — og blev slået ihjel i sit badekar.' },
  bz_constantine_iv: { n: 'Konstantin IV', p: 'Konstantinopel', d: 'Han brød den første arabiske belejring af Konstantinopel med græsk ild i 678 og afsluttede den monothelitiske strid ved det sjette økumeniske koncil.' },
  bz_justinian_ii: { n: 'Justinian II', p: 'Konstantinopel', d: 'Hovmodig søn af Konstantin IV, besejret ved Sebastopolis og afsat med næsen skåret af — han vendte tilbage fra eksil i 705 til en regeringstid af ren hævn.' },
  bz_leontios: { n: 'Leontios', p: 'Konstantinopel', d: 'General blevet tronraner efter Sebastopolis; tre år med arabiske nederlag, så et kup, en næseskæring — og i 706 gjorde Justinian IIs tilbagekomst en ende på ham.' },
  bz_tiberios_iii: { n: 'Tiberios III', p: 'Konstantinopel', d: 'Admiral i Kibyrraiot-flåden, der tog tronen; han holdt østgrænsen godt nok — indtil Justinian II sejlede tilbage med bulgarsk hjælp.' },
  bz_philippikos: { n: 'Philippikos', p: 'Konstantinopel', d: 'Han halshuggede Justinian II i hippodromen, genoptændte den monothelitiske strid — og tabte Armenien til araberne, før et blindningskup fjernede ham.' },
  bz_anastasios_ii: { n: 'Anastasios II', p: 'Konstantinopel', d: 'Forberedte sig strengt på den kommende arabiske belejring — kornmagasiner, en flåde, endda et spionplot mod kalifen; egne tropper gjorde mytteri og valgte en munk.' },
  bz_theodosios_iii: { n: 'Theodosios III', p: 'Konstantinopel', d: 'Den modvillige skatteembedsmand, som oprørerne kronede; to år med arabisk fremrykning senere trak han sig tilbage til et kloster og lod Leo III kæmpe belejringen.' },
  bz_leo_iii: { n: 'Leo III', p: 'Konstantinopel', d: 'Han brød den årslange arabiske belejring 717–718 med græsk ild og bulgarske allierede, rekodificerede loven — og indledte ikonoklasmen.' },
  bz_constantine_v: { n: 'Konstantin V', p: 'Konstantinopel', d: 'Briljant og brutal soldat, der knuste bulgarerne ved Ankhialos og genopbyggede themerne — og gjorde ikonoklasmen til en udrensning af dem, der ærede ikonerne.' },
  bz_artabasdos: { n: 'Artabasdos', p: 'Konstantinopel', d: 'Konstantin Vs svoger, der holdt hovedstaden i seksten måneder og genoprettede ikonerne; blindet med sine sønner, da borgerkrigen gik imod ham.' },
  bz_leo_iv: { n: 'Leo IV', p: 'Konstantinopel', d: 'Søn af Konstantin V og khanen af khasarernes datter; moderat i ikonsagen, standede han abbasiderne og efterlod riget til sin tiårige søn.' },
  bz_constantine_vi: { n: 'Konstantin VI', p: 'Konstantinopel', d: 'Barnekejseren under sin mors regentskab; efter fejl mod bulgarere og arabere, og et angreb på Irene, blindede hendes agenter ham i hans eget soveværelse.' },
  bz_irene: { n: 'Irene af Athen', p: 'Konstantinopel', d: 'Den første kvinde, der styrede riget alene; hun genoprettede ikonerne ved det andet koncil i Nikæa og døde i eksil på Lesbos, da hendes ministre kronede Nikeforos.' },
  bz_nikephoros_i: { n: 'Nikeforos I', p: 'Konstantinopel', d: 'Gerrig logothet-kejser; han genopbyggede finanserne, tabte slag til araberne — og til Krums bulgarere, hvis khan lavede et drikkebæger af hans kranie.' },
  bz_staurakios: { n: 'Staurakios', p: 'Konstantinopel', d: 'Båret bort fra Pliska-katastrofen med et dødeligt sår; ti ugers nominelt styre — derefter kronede han sin svoger Mikael I og tog munkekappen.' },
  bz_michael_i: { n: 'Mikael I', p: 'Konstantinopel', d: 'From, prangende, hjælpeløs; hans hær flygtede fra Krum ved Versinikia, tropperne hyldede Leo den Armenske — og Mikaels sønner blev kastreret og sat i kloster.' },
  bz_leo_v: { n: 'Leo V', p: 'Konstantinopel', d: 'Han slog bulgarerne ved Mesembria og købte fred, genoptog så ikonoklasmen — og blev hugget ned ved julemorgensbønnerne af mændene, han stolede på.' },
  bz_michael_ii: { n: 'Mikael II', p: 'Konstantinopel', d: 'Den stammende amoriske grundlægger; han brændte Thomas Slavens årslange belejring ud af hovedstaden, tabte Kreta og Sicilien — og efterlod ikonoklastkompromiset til sin søn.' },
  bz_theophilos: { n: 'Theophilos', p: 'Konstantinopel', d: 'Den sidste ikonoklast — alvorlig, retfærdighedskærlig, en bygger af paladser; hans Amorion faldt til kalifens hære i 838, årtiets sår.' },
  bz_michael_iii: { n: 'Mikael III', p: 'Konstantinopel', d: 'Ikonoklasmen sluttede under hans mor Theodora; han kæmpede mod abbasiderne, sendte Kyrillos og Methodios til slaverne — og opfostrede den makedonske Basileios, der dræbte ham.' },
  bz_basil_i: { n: 'Basileios I', p: 'Konstantinopel', d: 'Bonde, hestetræner, morder på sin protektor; han rekodificerede loven i Basilika og omkom under jagt — muligvis myrdet af Leo VIs folk.' },
  bz_leo_vi: { n: 'Leo VI', p: 'Konstantinopel', d: 'Den Vise — fire ægteskaber for en søn skabte Tetragami-skandalen; han tabte den bulgarske krig til Symeon, skrev prædikener og håndbøger — og kronede det makedonske århundrede.' },
  bz_alexander: { n: 'Alexander', p: 'Konstantinopel', d: 'Leos dovne medkejser i ét år; han rev sin brors monumenter ned, ofrede til en statue af Zeus — og døde af dysenteri efter en tzykanionkamp.' },
  bz_constantine_vii: { n: 'Konstantin VII', p: 'Konstantinopel', d: 'Lærdekejseren, født i purpur; regentskaber lod ham vente toogtredive år, men De Administrando og De Ceremoniis blev Bysants hukommelse.' },
  bz_romanos_i: { n: 'Romanos I', p: 'Konstantinopel', d: 'Admiral, der gjorde sig selv til øverste kejser over den unge Konstantin VII — fireogtyve år med sund fornuft, nederlag til Symeon, jordlove — indtil hans sønner forrådte ham.' },
  bz_romanos_ii: { n: 'Romanos II', p: 'Konstantinopel', d: 'Smuk, nydelsessyg søn af den lærde; Nikeforos Fokas tog Kreta for ham, og han døde fireogtyve år gammel — gift mistænkt.' },
  bz_nikephoros_ii: { n: 'Nikeforos II', p: 'Konstantinopel', d: 'Den blege, munkeansigtede erobrer af Kreta og Antiokia; han giftede sig med Theofano og beskattede kirken — og blev myrdet i sit eget soveværelse af Tzimiskes og kejserinden.' },
  bz_john_i_tzimiskes: { n: 'Johannes I Tzimiskes', p: 'Konstantinopel', d: 'Den smukke lille general; han knuste Svjatoslavs rusere ved Silistra og marcherede til Bagdads mure — døde af tyfus på det østlige felttog.' },
  bz_basil_ii: { n: 'Basileios II Bulgaroktonos', p: 'Konstantinopel', d: 'Bulgaroktonos’ niogfyrre år var rigets højdepunkt: Bulgarien annekteret, themerne stærke, 200.000 pund i reserve — og ingen arving, den stille katastrofe.' },
  bz_constantine_viii: { n: 'Konstantin VIII', p: 'Konstantinopel', d: 'Broren, der ventede treoghalvfjerds år på at regere alene; tre år med yndlinger og lemlæstelser — så gik tronen til hans døtre Zoe og Theodora.' },
  bz_zoe: { n: 'Zoe', p: 'Konstantinopel', d: 'Halvtreds år og opdraget til at gifte sig med den, hoffet valgte — Romanos III, Mikael IV, Konstantin IX; møntværkstedet prægede hendes ansigt ved siden af hver ægtemands.' },
  bz_romanos_iii: { n: 'Romanos III', p: 'Konstantinopel', d: 'Zoes første ægtemand, en intellektuel, der legede kejser; skatterne steg, et syrisk angreb fejlede — og han druknede i sit badekar, mens kilderne blot trak på skuldrene over kejserinden.' },
  bz_michael_iv: { n: 'Mikael IV', p: 'Konstantinopel', d: 'Zoes smukke elsker, gjort til kejser af sin bror, evnukken Johannes; epilepsien åd ham op, mens bulgarerne rejste sig — han døde som munk, krigen vundet ved Ostrovo.' },
  bz_michael_v: { n: 'Mikael V', p: 'Konstantinopel', d: 'Adoptivnevø af Mikael IV; han forviste sin velgører Zoe i hovmod — folket gjorde oprør i fire dage, og han blev fjernet blindet, til et kloster.' },
  bz_theodora: { n: 'Theodora', p: 'Konstantinopel', d: 'Zoes yngre søster, medkejserinde under optøjerne i 1042, endelig enehersker i 1055 — streng, kysk, fireoghalvfjerds, den sidste af det makedonske hus.' },
  bz_constantine_ix: { n: 'Konstantin IX', p: 'Konstantinopel', d: 'Zoes tredje ægtemand; hans hof var Konstantinopels gyldne eftermiddag — jura, filosofi — men mønten forringedes, og Manzikerts frø blev sået.' },
  bz_michael_vi: { n: 'Mikael VI', p: 'Konstantinopel', d: 'Den aldrende civilist, Theodora valgte; han gav østgeneralerne en kold skulder, Isak Komnenos marcherede — og abdikationen købte ham en ærefuld pensionering.' },
  bz_isaac_i: { n: 'Isak I', p: 'Konstantinopel', d: 'Første Komnenos-kejser; han rev kirkens jorder og aristokratiske forleninger tilbage, fik en forkølelse i en storm — og overlod tronen til Konstantin X Dukas.' },
  bz_constantine_x: { n: 'Konstantin X', p: 'Konstantinopel', d: 'Civilt styre igen — hæren ubetalt, grænserne udtyndet; normannerne gjorde ende på Italien, tyrkere hærgede Armenien, og hans enke giftede sig snart igen.' },
  bz_romanos_iv: { n: 'Romanos IV', p: 'Konstantinopel', d: 'Soldaterkejser, der marcherede for at stoppe turkmenernes hærgningstogter; forrådt ved Manzikert — taget til fange af Alp Arslan, løskøbt, blindet, død.' },
  bz_michael_vii: { n: 'Mikael VII', p: 'Konstantinopel', d: '“Parapinakios” — kejseren bag den dyre brød; Psellos’ elev, han så på, mens normannerne tog Bari og statskassen kollapsede under petsjenegerkrigen.' },
  bz_nikephoros_iii: { n: 'Nikeforos III', p: 'Konstantinopel', d: 'Den aldrende general, Anatolien rejste mod Mikael VII; tre års kaos — så endte Alexios Komnenos’ tronran ham i et kloster.' },
  bz_alexios_i: { n: 'Alexios I', p: 'Konstantinopel', d: 'Han genopbyggede fra afgrunden — venetiansk handel mod guld, petsjenegerne knust ved Levounion, og det første korstog ført sikkert forbi, til hans aftales fordel.' },
  bz_john_ii: { n: 'Johannes II', p: 'Konstantinopel', d: '“Johannes den Gode”, den mildeste i en vild slægt; Donaufelttog, Ungarn tæmmet, Antiokia skræmt til lydighed — han døde af en jagtskade, og de fattige sørgede over ham.' },
  bz_manuel_i: { n: 'Manuel I', p: 'Konstantinopel', d: 'Den vestliggørende ridderkejser; turneringer, diplomati fra Ungarn til Outremer, Myriokephalon overlevet — og riget glimrede, indtil det ikke gjorde det mere.' },
  bz_alexios_ii: { n: 'Alexios II', p: 'Konstantinopel', d: 'Elleve år gammel arving under sin regerende mor; Andronikos red ind, mængden myrdede Maria af Antiokia — og drengen blev kvalt med en buestreng.' },
  bz_andronikos_i: { n: 'Andronikos I', p: 'Konstantinopel', d: 'Briljant, brutal skræk for aristokratiet; to års terror — så rev Isak Angelos’ kup og en hippodrommængde ham i stykker.' },
  bz_isaac_ii: { n: 'Isak II', p: 'Konstantinopel', d: 'Han slog normannerne, spildte statskassen på fester, tabte Bulgarien til asenerne — og blev blindet, så genindsat, af egen bror og søn.' },
  bz_alexios_iii: { n: 'Alexios III', p: 'Konstantinopel', d: 'Han blindede Isak og bankrupterede staten; da det fjerde korstogs flåde nåede Det Gyldne Horn i 1203, flygtede han med juvelerne i en fiskerbåd.' },
  bz_alexios_iv: { n: 'Alexios IV', p: 'Konstantinopel', d: 'Han lovede korsfarerne månen for sin fars trone — kunne ikke betale, og Mourtzouflos’ fraktion kvalte ham, mens byen sultede.' },
  bz_alexios_v: { n: 'Alexios V', p: 'Konstantinopel', d: 'To måneders heroisk forsvar — den venetianske flåde brændt foran murene; så flygtede han, og korsfarerne henrettede ham ved Theodosius-søjlen.' },
  bz_theodore_i: { n: 'Teodor I Laskaris', p: 'Nikaia', d: 'Restrigets overlever: fra Nikaia slog han latinerne, tog en patriark-bekræftet krone og giftede sig ind i de store slægter for at holde græsk Asien.' },
  bz_john_iii: { n: 'Johannes III Dukas Vatatzes', p: 'Nikaia', d: 'Den største af nikeaenerne — Rhyndakos vundet, Kreta taget, Bulgarien standset, Konstantinopel blokeret; grækerne kanoniserede ham som Johannes den Barmhjertige.' },
  bz_theodore_ii: { n: 'Teodor II Laskaris', p: 'Nikaia', d: 'Lærd på tronen — korrespondance, filosofi, en kerne af uddannede nye mænd; epilepsi og dødsfald i familien skyggede fire korte år.' },
  bz_john_iv: { n: 'Johannes IV Laskaris', p: 'Nikaia', d: 'Kronet som syvårig, blindet som elleveårig — på Mikael Palaiologos’ juleordre, samme dag Konstantinopel blev generobret; drengen levede videre i en fæstning.' },
  bz_michael_viii: { n: 'Mikael VIII Palaiologos', p: 'Konstantinopel', d: 'Han tog Konstantinopel fra latinerne i 1261 og genforenede kirken i Lyon for at holde Karl af Anjou i skak — hadet, frygtet, effektiv til det sidste.' },
  bz_andronikos_ii: { n: 'Andronikos II', p: 'Konstantinopel', d: 'From og sparsommelig til rigets skade — skatter skåret, flåden ophugget, det katalanske kompagni sluppet løs og ubetalt; barnebarnets borgerkrig endte hans seksogfyrre år.' },
  bz_andronikos_iii: { n: 'Andronikos III', p: 'Konstantinopel', d: 'En yngling af skandaler, der regerede overraskende godt — lovkodificering, Lésvos generobret, Epiros vundet tilbage — mens osmannerne tog deres første fodfæste ved Gallipoli.' },
  bz_john_v: { n: 'Johannes V', p: 'Konstantinopel', d: 'Et halvt århundrede med borgerkrige, osmansk vasal og en pavelig omvendelsesturné; han døde som Bayezids vasal, hans rige en by plus spredte havne.' },
  bz_john_vi: { n: 'Johannes VI', p: 'Konstantinopel', d: 'Stor domestikos, der blev medkejser gennem borgerkrig; han gav sin datter til en osmansk bey, trak sig tilbage til et kloster — og skrev sit eget forsvar i historien.' },
  bz_andronikos_iv: { n: 'Andronikos IV', p: 'Konstantinopel', d: 'Han tog tronen fra sin far Johannes V med osmansk og genovesisk hjælp — og mistede den på samme måde; Gallipoli forblev tyrkisk alligevel.' },
  bz_john_vii: { n: 'Johannes VII', p: 'Konstantinopel', d: 'Fem måneders tronran mellem bedstefar og onkel; senere holdt han Konstantinopel for Manuel II mod Bayezid og forhandlede med Timurs storm.' },
  bz_manuel_ii: { n: 'Manuel II', p: 'Konstantinopel', d: 'Lærdekejser af det lange tilbagetog — den berømte samtale om troen med en perser, tiggerturnéer til vestlige hoffer, der bragte lidt hjælp.' },
  bz_john_viii: { n: 'Johannes VIII', p: 'Konstantinopel', d: 'Han søgte kirkeforening i Firenze og vestlig hjælp ved Varna — ingen af delene holdt; Pisanello og Benozzo Gozzoli malede hans mærkelige hat for evigt.' },
  bz_constantine_xi: { n: 'Konstantin XI Palaiologos', p: 'Konstantinopel', d: 'Den sidste romerske kejser; han døde med sværdet i hånden i brædden ved St. Romanus-porten, mens Mehmed 2.s hær tog Konstantinopel den 29. maj 1453.' },
});

/* pharaohs of Egypt - 143 entries (2026-10-29) */
Object.assign(window.DATA_DA, {
  ph_narmer: { n: 'Narmer', p: 'Hierakonpolis, Egypten', d: 'Foreneren, der samlede Øvre og Nedre Egypten under én krone — hans udskårne palette viser ham som den første konge af den første store territoriale stat på Jorden.' },
  ph_aha: { n: 'Hor-Aha', p: 'Memfis, Egypten', d: 'Traditionens grundlægger af Memfis, hvis grav ved Abydos rummede tjenere, begravet for at tjene deres konge i livet efter døden.' },
  ph_djer: { n: 'Djer', p: 'Abydos, Egypten', d: 'Egyptere fra senere århundreder dyrkede hans grav ved Abydos som guden Osiris’ egen grav.' },
  ph_djet: { n: 'Djet', p: 'Abydos, Egypten', d: 'Hans gravstele, udsmykket med et slangemærke, er et af de fineste bevarede værker fra den tidligdynastiske periode.' },
  ph_merneith: { n: 'Merneith', p: 'Abydos, Egypten', d: 'Dronning og regent for barnekongen Den, opført blandt både konger og dronninger — meget muligt Egyptens første kvindelige hersker.' },
  ph_den: { n: 'Den', p: 'Abydos, Egypten', d: 'Den første til at føre titlen Øvre og Nedre Egyptens konge med dobbeltkronen; hans lange regeringstid satte mønsteret for den unge stat.' },
  ph_anedjib: { n: 'Anedjib', p: 'Memfis, Egypten', d: 'En urolig regeringstid, husket for oprør i Øvre Egypten og samtidige påstande om, at han havde tilranet sig tronen.' },
  ph_semerket: { n: 'Semerkhet', p: 'Abydos, Egypten', d: 'Senere tradition, formidlet af Manetho, kaldte hans en ulykkesregering — alligevel fik han en fuld kongelig begravelse ved Abydos.' },
  ph_qaa: { n: 'Qa’a', p: 'Abydos, Egypten', d: 'Sidste konge af 1. dynasti, begravet med et rigt hof omkring sig; hans død udløste en arvefølgestrid.' },
  ph_hotepsekhemwy: { n: 'Hotepsekhemwy', p: 'Memfis, Egypten', d: 'Grundlægger af 2. dynasti; hans navn — “de to magter er i fred” — lover forsoning efter den dynastiske krise, der afsluttede 1. dynasti.' },
  ph_raneb: { n: 'Raneb', p: 'Memfis, Egypten', d: 'Første konge, der satte solguden Ra i sit navn, et tidligt tegn på soltroen, som skulle beherske Det Gamle Rige.' },
  ph_nynetjer: { n: 'Nynetjer', p: 'Memfis, Egypten', d: 'En regeringstid på næsten fyrre år, optegnet i kongeanalerne; derefter gled dynastiet ind i årtier med omstridt arvefølge.' },
  ph_peribsen: { n: 'Peribsen', p: 'Abydos, Egypten', d: 'Den eneste konge, der satte guden Seth, ikke Horus, over sit navn — et religiøst valg, forskere stadig strides om.' },
  ph_khasekhemwy: { n: 'Khasekhemwy', p: 'Hierakonpolis, Egypten', d: 'Sidste konge af den tidligdynastiske tid og forsoner af Horus og Seth; hans kæmpestore lerstensanlæg ved Abydos er jordens ældste store murstensbygning.' },
  ph_sanakht: { n: 'Sanakht', p: 'Memfis, Egypten', d: 'Muligvis grundlæggeren af 3. dynasti; et relieffragment viser en høj, bred konge, hvis identitet forskere stadig diskuterer.' },
  ph_djoser: { n: 'Djoser', p: 'Memfis, Egypten', d: 'Hans arkitekt Imhotep rejste Trappepyramiden ved Saqqara — verdens første store stenbygning — og begge mænd blev dyrket som guder i 2.000 år.' },
  ph_sekhemkhet: { n: 'Sekhemkhet', p: 'Memfis, Egypten', d: 'Han påbegyndte en anden trappepyramide ved siden af Djosers, men døden efter seks år lod den ligge ufuldendt begravet — fundet intakt i 1952.' },
  ph_khaba: { n: 'Khaba', p: 'Memfis, Egypten', d: 'Sandsynligvis bygherren bag Lagpyramiden ved Zawyet el-Aryan, endnu et tidligt eksperiment med kongelige stengrave.' },
  ph_huni: { n: 'Huni', p: 'Memfis, Egypten', d: 'Sidste konge af 3. dynasti, formentlig den hersker, der påbegyndte pyramiden ved Meidum på tærsklen til Det Gamle Riges storhedstid.' },
  ph_sneferu: { n: 'Snofru', p: 'Memfis, Egypten', d: 'Egyptens største pyramidebygger — han rejste tre, herunder den første ægte, glatsidede pyramide ved Dahshur, og blev husket i generationer som en velgørende idealkonge.' },
  ph_khufu: { n: 'Kheops', p: 'Memfis, Egypten', d: 'Bygherre bag den store pyramide i Giza, det eneste bevarede af oldtidens underværker — 146 meter sten, rettet mod det sande nord inden for en brøkdel af en grad.' },
  ph_djedefre: { n: 'Djedefre', p: 'Memfis, Egypten', d: 'Han flyttede den kongelige nekropol til Abu Rawash, Egyptens højest beliggende pyramideplads, og tilskrives den første kolossale kongelige sphinx.' },
  ph_khafre: { n: 'Kefren', p: 'Memfis, Egypten', d: 'Bygherre bag Gizas anden pyramide og den store sphinx, der vogter den; hans grav ser højere ud end Kheops’, fordi den står på højere grund.' },
  ph_menkaure: { n: 'Mykerinos', p: 'Memfis, Egypten', d: 'Hans pyramide i Giza fik en beklædning af kostbar granit, og de rolige triadestatuer af ham sammen med gudinden Hathor fastlagde idealet for kongelig portrætkunst.' },
  ph_shepseskaf: { n: 'Shepseskaf', p: 'Memfis, Egypten', d: 'Den sidste konge af 4. dynasti opgav pyramiderne til fordel for en kæmpestor, sarkofagformet mastaba ved Saqqara og afsluttede dermed Egyptens største gravbyggertid.' },
  ph_userkaf: { n: 'Userkaf', p: 'Memfis, Egypten', d: 'Grundlægger af 5. dynasti; han byggede det første soltempel — en kæmpeobelisk på en åben gård — og gjorde solkulten til statens ideologi.' },
  ph_sahure: { n: 'Sahure', p: 'Memfis, Egypten', d: 'Hans relieffer skildrer den første egyptiske sørejse til Punt og de ældste flådescener; hans anlæg i Abusir satte den kunstneriske kanon for generationer.' },
  ph_neferirkare: { n: 'Neferirkare Kakai', p: 'Memfis, Egypten', d: 'Hans tempelarkiv ved Abusir bevarede de ældste kendte administrative og medicinske papyrier fra Egypten.' },
  ph_shepseskare: { n: 'Shepseskare', p: 'Memfis, Egypten', d: 'En dunkel regeringstid klemt inde mellem længere, kun markeret af et ufuldendt soltempel ved Abusir.' },
  ph_neferefre: { n: 'Neferefre', p: 'Memfis, Egypten', d: 'Død omkring tyve år gammel; hans ufuldendte pyramide blev i hast omdannet til en lav mastaba ved Abusir, hvor hans statuer blev begravet.' },
  ph_nyuserre: { n: 'Nyuserre Ini', p: 'Memfis, Egypten', d: 'En regeringstid på tredive år, der fyldte Abusir med monumenter, blandt andet soltemplet, hvis årstidsrelieffer ledsager Egyptens ældste tempelregnskaber.' },
  ph_menkauhor: { n: 'Menkauhor Kaiu', p: 'Memfis, Egypten', d: 'Hans pyramide, “Ras stjerne er fuldkommen”, var tabt i over et århundrede og blev først identificeret i 2008.' },
  ph_djedkare: { n: 'Djedkare Isesi', p: 'Memfis, Egypten', d: 'En regeringstid på fyrre år med administrativ reform, i hvis slutning de første beskyttende besværgelser optrådte i de kongelige pyramider — pyramideteksternes spirer.' },
  ph_unas: { n: 'Unas', p: 'Memfis, Egypten', d: 'Sidste konge af 5. dynasti; hans pyramide ved Saqqara bærer de første indhuggede pyramidetekster, menneskehedens ældste religiøse litteratur, som lover kongen evigt liv blandt stjernerne.' },
  ph_teti: { n: 'Teti', p: 'Memfis, Egypten', d: 'Grundlægger af 6. dynasti, senere sagt at være myrdet af sine egne livvagter; hans embedsmænds rige grave er en vigtig kilde til tiden.' },
  ph_userkare: { n: 'Userkare', p: 'Memfis, Egypten', d: 'Han tog tronen mellem Teti og Pepi I, og senere egyptisk erindring mistænkte ham for Tetis mord.' },
  ph_pepi_i: { n: 'Pepi I', p: 'Memfis, Egypten', d: 'Han overlevede en haremssammensværgelse, regerede i fire årtier og efterlod en tårnhøj kobberstatue — den største metalfigur fra oldtidens Nærorient.' },
  ph_merenre_i: { n: 'Merenre Nemtyemsaf I', p: 'Memfis, Egypten', d: 'Han sendte den berømte guvernør Harkhuf dybt ind i Nubien, døde ung og efterlod tronen til en lille dreng.' },
  ph_pepi_ii: { n: 'Pepi II', p: 'Memfis, Egypten', d: 'En regeringstid på omkring halvfems år — formentlig historiens længste — der åbnede med et brev, der lovede en dansende dværg, og sluttede med Det Gamle Rige i forfald.' },
  ph_merenre_ii: { n: 'Merenre Nemtyemsaf II', p: 'Memfis, Egypten', d: 'En konge af et enkelt år, kendt næsten kun gennem den dronning, der fulgte efter ham.' },
  ph_nitocris: { n: 'Nitokris', p: 'Memfis, Egypten', d: 'Herodots og Manethos sidste hersker af 6. dynasti, historiens første navngivne kvindelige farao — uanset om en dronning med det navn virkelig regerede.' },
  ph_khety_i: { n: 'Meryibre Khety', p: 'Herakleopolis, Egypten', d: 'Grundlægger af det herakleopolitiske dynasti, der gjorde krav på nord, mens thebanske fyrster samlede magt i syd — de to magters balance i den første mellemperiode.' },
  ph_intef_i: { n: 'Intef I', p: 'Theben, Egypten', d: 'Den første thebanske hersker af sin slægt, der tog den kongelige kartouche, da Theben rejste sig mod det herakleopolitiske Egypten.' },
  ph_intef_ii: { n: 'Intef II', p: 'Theben, Egypten', d: '“Skønhedens bringer”, hvis halvtredsårige regeringstid skubbede Thebens grænse nordpå forbi Abydos og satte genforeningen i bevægelse.' },
  ph_intef_iii: { n: 'Intef III', p: 'Theben, Egypten', d: 'Han fuldendte Thebens magtopbygning, og hans svigersøn Mentuhotep II skulle høste det genforenede kongerige; århundreder senere blev han stadig dyrket i Koptos.' },
  ph_mentuhotep_ii: { n: 'Mentuhotep II', p: 'Theben, Egypten', d: 'Genforeneren — han knuste det herakleopolitiske nord og indledte Mellemriget; hans terrasserede tempel ved Deir el-Bahari blev et forbillede, der blev efterlignet i årtusinder.' },
  ph_mentuhotep_iii: { n: 'Mentuhotep III', p: 'Theben, Egypten', d: 'Han sendte den første optegnede ekspedition til landet Punt og genåbnede handelen på det Røde Hav efter borgerkrigene.' },
  ph_mentuhotep_iv: { n: 'Mentuhotep IV', p: 'Theben, Egypten', d: 'En dunkel skikkelse til sidst — den kongelige opsynsmand Amenemhat, som udbrød stenen til hans sarkofaglåg, tog formentlig selv tronen som Amenemhat I.' },
  ph_amenemhat_i: { n: 'Amenemhat I', p: 'Itj-taui, Egypten', d: 'Grundlægger af 12. dynasti: han flyttede hovedstaden til den nybyggede by Itj-taui og gjorde sin søn til medregent — en klog forholdsregel, for han blev myrdet i sit 30. regeringsår.' },
  ph_senusret_i: { n: 'Senusret I', p: 'Itj-taui, Egypten', d: 'Medregenten, der trådte gnidningsfrit til magten; under ham blev Fortællingen om Sinuhe nedskrevet, og hans obelisk i Heliopolis står den dag i dag.' },
  ph_amenemhat_ii: { n: 'Amenemhat II', p: 'Itj-taui, Egypten', d: 'Hans annaler optegner flåder til minedrift i Nubien og handelsekspeditioner til Libanon — Mellemriget på sit kommercielle højdepunkt.' },
  ph_senusret_ii: { n: 'Senusret II', p: 'Itj-taui, Egypten', d: 'Han drænede Fayum-sumpene til landbrugsjord og flyttede sin pyramide til El-Lahun, hvis arbejderby bevarer dagligdagen i det gamle Egypten.' },
  ph_senusret_iii: { n: 'Senusret III', p: 'Itj-taui, Egypten', d: 'Krigeradministratoren, hvis fæstninger kædede Nubiens Anden Katarakt fast, hvis kanaler skar gennem den, og hvis strenge ansigter indførte en ny realisme i kongekunsten.' },
  ph_amenemhat_iii: { n: 'Amenemhat III', p: 'Itj-taui, Egypten', d: 'Mellemrigets økonomiske top — hans labyrint ved Hawara betagede græske besøgende, og hans Fayum-anlæg gjorde sumpen til Egyptens kornkammer.' },
  ph_amenemhat_iv: { n: 'Amenemhat IV', p: 'Itj-taui, Egypten', d: 'Den sidste mandlige konge af 12. dynasti, formentlig den efterfølgende dronnings plejebarn og gemal.' },
  ph_sobekneferu: { n: 'Sobekneferu', p: 'Itj-taui, Egypten', d: 'Den første kvinde, der dokumenteret herskede over Egypten som konge; med hende endte det store 12. dynasti — og Mellemrigets stabilitet.' },
  ph_khendjer: { n: 'Khendjer', p: 'Itj-taui, Egypten', d: 'En konge med semitisk navn fra det svindende 13. dynasti — den eneste farao fra Mellemriget, der kendes at have bygget en pyramide, ved Syd-Saqqara.' },
  ph_khyan: { n: 'Khyan', p: 'Avaris, Egypten', d: 'En hyksoshersker over Avaris, hvis skarabæer spænder fra Kreta til Mesopotamien — de fremmedes kongerige lå midt i en større handelsverden.' },
  ph_apepi: { n: 'Apepi', p: 'Avaris, Egypten', d: 'Hyksoskongen fra senere legende, der kom i strid med Theben — hans by Avaris holdt deltaet i et århundrede, før thebanerne slog tilbage.' },
  ph_seqenenre_tao: { n: 'Seqenenre Tao', p: 'Theben, Egypten', d: 'Thebaneren, hvis mumie bærer forfærdelige øksehug — han faldt formentlig i kamp, da han åbnede Egyptens frihedskrig mod hyksoserne.' },
  ph_kamose: { n: 'Kamose', p: 'Theben, Egypten', d: 'Den sidste konge af 17. dynasti; ordene på hans stele — “Jeg vil frelse Egypten og nedslå asiaterne” — indledte den krig, hans bror Ahmose fuldendte.' },
  ph_ahmose_i: { n: 'Ahmose I', p: 'Theben, Egypten', d: 'Han fordrev hyksoserne fra Egypten og forfulgte dem til Kanaan, grundlagde 18. dynasti og Nyrigets imperium.' },
  ph_amenhotep_i: { n: 'Amenhotep I', p: 'Theben, Egypten', d: 'Sammen med sin mor Ahmose-Nefertari blev han i århundreder dyrket som den beskyttende guddom for Thebens kongelige arbejdsfolk.' },
  ph_thutmose_i: { n: 'Thutmosis I', p: 'Theben, Egypten', d: 'Første farao, der blev begravet i Kongernes Dal; hans hær marcherede til Eufrat, det fjerneste, Egypten nogensinde havde nået.' },
  ph_thutmose_ii: { n: 'Thutmosis II', p: 'Theben, Egypten', d: 'Hans korte regeringstid blev styret af hans store kongelige hustru Hatshepsut; i 2025 blev hans tabte grav det første kongelige gravfund siden Tutankhamons.' },
  ph_hatshepsut: { n: 'Hatshepsut', p: 'Theben, Egypten', d: 'Dronningen, der regerede som fuldgyldig farao i to årtier — handelsekspeditionen til Punt, det terrasserede tempel ved Deir el-Bahari, obelisker højere end nogen tidligere — indtil senere konger hakkede hendes billeder væk.' },
  ph_thutmose_iii: { n: 'Thutmosis III', p: 'Theben, Egypten', d: '“Soldatens farao”: sytten felttog fra Megiddo til Eufrat skabte Egyptens største asiatiske imperium, længe overskygget i historien af den moster, der regerede før ham.' },
  ph_amenhotep_ii: { n: 'Amenhotep II', p: 'Theben, Egypten', d: 'En pralende atletkonge, der skød pile gennem kobbermål — og engang hængte syv dræbte oprørere fra sit skibs bov for at skræmme Syrien.' },
  ph_thutmose_iv: { n: 'Thutmosis IV', p: 'Theben, Egypten', d: 'Han rensede den store sphinx for drivende sand og rejste drømmestelen mellem poterne — monumentets første optegnede restaurering.' },
  ph_amenhotep_iii: { n: 'Amenhotep III', p: 'Theben, Egypten', d: '“Den Prægtige”: han giftede sig med prinsesser fra Babylon til Mitanni, rejste Memnons kolosser og herskede over et imperium i fred og på sit rigeste.' },
  ph_akhenaten: { n: 'Eknaton', p: 'Akhetaton, Egypten', d: 'Kætterkongen — han lukkede de gamle templer, dyrkede kun solskiven Aton, byggede en ny hovedstad ved Amarna og gennemtvang en revolution i kunst og tro, der døde med ham.' },
  ph_tutankhamun: { n: 'Tutankhamon', p: 'Theben, Egypten', d: 'Drengkongen, der genindførte de gamle guder og døde omkring atten år gammel; hans urørte grav, fundet i 1922, gjorde ham til den mest berømte egypter, der nogensinde har levet.' },
  ph_ay: { n: 'Ay', p: 'Theben, Egypten', d: 'En ældet hofmand, der giftede sig med Tutankhamons enke for at nå tronen; hans tiltænkte arving døde ung, og herefter overtog hæren magten.' },
  ph_horemheb: { n: 'Horemheb', p: 'Theben, Egypten', d: 'Generalen, der lukkede Amarna-kapitlet — han udslettede mindet om Eknaton, reformerede domstolene mod korruption og valgte en soldat som sin arving.' },
  ph_ramses_i: { n: 'Ramses I', p: 'Pi-Ramses, Egypten', d: 'En professionel soldat og Horemhebs udvalgte arving, som regerede knap halvandet år og næsten ved et tilfælde grundlagde et dynasti.' },
  ph_seti_i: { n: 'Seti I', p: 'Pi-Ramses, Egypten', d: 'Imperiets genopretter — hans krige generobrede tabt syrisk område, og hans tempel ved Abydos og grav KV17 hører til Egyptens smukkest udsmykkede bygninger.' },
  ph_merneptah: { n: 'Merneptah', p: 'Pi-Ramses, Egypten', d: 'Han knuste en stor libysk invasion i sit femte år, og hans sejershymne rummer den første skriftlige omtale af Israel uden for Bibelen.' },
  ph_seti_ii: { n: 'Seti II', p: 'Pi-Ramses, Egypten', d: 'Hans regeringstid blev bestridt af en rivaliserende konge, Amenmesse, i Theben — hofintriger havde afløst imperiets militære glans.' },
  ph_siptah: { n: 'Siptah', p: 'Pi-Ramses, Egypten', d: 'En lammet drengkonge — hans klumpfod ses på mumien — styret af den magtfulde syriskfødte kansler Bay.' },
  ph_twosret: { n: 'Twosret', p: 'Pi-Ramses, Egypten', d: 'Egyptens anden dokumenterede kvindelige farao; hendes korte styre endte med 19. dynasti midt i den uro, der førte et nyt dynasti til magten.' },
  ph_setnakhte: { n: 'Setnakhte', p: 'Pi-Ramses, Egypten', d: 'En outsider, der bemægtigede sig den ledige trone og genoprettede orden; han grundlagde 20. dynasti og efterlod det til sin berømte søn Ramses III.' },
  ph_ramses_iii: { n: 'Ramses III', p: 'Pi-Ramses, Egypten', d: 'Egyptens sidste store farao — han besejrede havfolkene til lands og til vands i en krig, der reddede det østlige Middelhav, og døde i en haremssammensværgelse, hvis retsprotokol er bevaret.' },
  ph_ramses_iv: { n: 'Ramses IV', p: 'Pi-Ramses, Egypten', d: 'Hans papyrus om stenbrud viser kongelige byggeprojekter i sjælden detalje; doblede kornrationer til arbejderne vidner om en økonomi under pres.' },
  ph_ramses_v: { n: 'Ramses V', p: 'Pi-Ramses, Egypten', d: 'Hans mumie bærer det ældste kendte tilfælde af kopper; hans onkel tog både trone og grav fra ham.' },
  ph_ramses_vi: { n: 'Ramses VI', p: 'Pi-Ramses, Egypten', d: 'Han tilegnede sig sin nevøs grav; gravkammeret i KV9 rummer de fineste kosmiske tekster — solgudens natlige rejse — i Kongernes Dal.' },
  ph_ramses_vii: { n: 'Ramses VII', p: 'Pi-Ramses, Egypten', d: 'Kornpriserne steg voldsomt, og Thebens arbejdere strejkede igen under hans regeringstid — staten manglede både sølv og brød.' },
  ph_ramses_viii: { n: 'Ramses VIII', p: 'Pi-Ramses, Egypten', d: 'Et spøgelse på kongelistene — knap et år på tronen, ingen monumenter, ingen kendt grav, ingen mumie.' },
  ph_ramses_ix: { n: 'Ramses IX', p: 'Pi-Ramses, Egypten', d: 'Under ham undersøgte embedsmændene gravrøverierne, hvis retssagspapyrier er bevaret — staten var i færd med at fortære sine egne døde konger.' },
  ph_ramses_x: { n: 'Ramses X', p: 'Pi-Ramses, Egypten', d: 'En dunkel afsluttende regeringstid: hans arbejdere blev hjemme af frygt for libyske plyndringsfolk, og hans grav blev knap nok påbegyndt.' },
  ph_ramses_xi: { n: 'Ramses XI', p: 'Pi-Ramses, Egypten', d: 'Den sidste Ramses regerede til navnet, mens borgerkrig delte Egypten mellem generaler og Amons ypperstepræster — hans død lukkede Nyriget.' },
  ph_smendes: { n: 'Smendes', p: 'Tanis, Egypten', d: 'Grundlægger af 21. dynasti, som styrede fra Tanis, mens Amons ypperstepræster regerede i Theben — to Egypten i et skrøbeligt fællesskab.' },
  ph_amenemnisu: { n: 'Amenemnisu', p: 'Tanis, Egypten', d: 'En kort, dunkel regeringstid mellem Smendes og den langlivede Psusennes I, i en æra, hvis kilder er tyndet ud til næsten ingenting.' },
  ph_psusennes_i: { n: 'Psusennes I', p: 'Tanis, Egypten', d: 'Hans urørte sølvkiste og guldmaske, fundet i 1940, beviste, at kongerne i Tanis stadig rådede over skatte — i sølv, hvor oldtidens faraoer havde brugt guld.' },
  ph_amenemopet: { n: 'Amenemopet', p: 'Tanis, Egypten', d: 'Et stille årti i Tanis; hans begravelse blev proppet ind i et genanvendt kammer, efterhånden som kongerigets ressourcer svandt.' },
  ph_siamun: { n: 'Siamun', p: 'Tanis, Egypten', d: 'En stærkere konge i Tanis, husket for tempelbyggeri i og omkring byen og af senere forskere knyttet til Egypten i Salomos tid.' },
  ph_psusennes_ii: { n: 'Psusennes II', p: 'Tanis, Egypten', d: 'Den sidste konge af 21. dynasti; hans datters ægteskab ind i Shoshenqs magtfulde libyske slægt banede næste dynastis vej til tronen.' },
  ph_shoshenq_i: { n: 'Shoshenq I', p: 'Bubastis, Egypten', d: 'Efterkommer af den libyske høvding, der genforenede Egypten og marcherede ind i Israel og Judæa — Bibelens “Sjisjak”, som bortførte Jerusalems tempelskatte omkring 925 f.Kr.' },
  ph_osorkon_i: { n: 'Osorkon I', p: 'Bubastis, Egypten', d: 'Han arvede imperiet og brugte dets felttogsrigdomme på templer — alene hans gaver til Bubastis løb op i tonsvis af guld og sølv.' },
  ph_takelot_i: { n: 'Takelot I', p: 'Bubastis, Egypten', d: 'Hans regeringstid holdt nord stabilt, men Theben gled ud af kongelig kontrol mod sine egne præstekonger — næste århundredes splittelse var allerede synlig.' },
  ph_osorkon_ii: { n: 'Osorkon II', p: 'Bubastis, Egypten', d: 'Hans prægtige relieffer fra Sed-festen skjuler den første store krise: besejret i slaget ved Karkar måtte han se Theben krone en rivaliserende farao.' },
  ph_takelot_ii: { n: 'Takelot II', p: 'Bubastis, Egypten', d: 'Hans regeringstid faldt sammen med et thebansk oprør, der delte landet i rivaliserende kongeriger — hans søn Osorkons krønike daterer hvert eneste år af den lange borgerkrig.' },
  ph_shoshenq_iii: { n: 'Shoshenq III', p: 'Bubastis, Egypten', d: 'Han regerede i 52 år over et sammentrumpet nord, mens Theben adlød andre dynastier — kongemagten i Egypten var blevet en regional størrelse.' },
  ph_pedubast_i: { n: 'Pedubast I', p: 'Theben, Egypten', d: 'Den thebanske general, der grundlagde 23. dynasti i åben udfordring af Tanis — i årtier regerede tre faraoer på én gang i et delt land.' },
  ph_tefnakht: { n: 'Tefnakht', p: 'Sais, Egypten', d: 'Prinsen af det vestlige delta, der byggede en koalition mod kushiterne — besejret af Piye erklærede han sig alligevel som farao i nord og grundlagde 24. dynasti.' },
  ph_bakenranef: { n: 'Bakenranef', p: 'Sais, Egypten', d: '“Bokchoris” hos grækerne, husket som en lovgivende konge — indtil Shabaka lod ham brænde levende og tog Egypten for Kush.' },
  ph_piye: { n: 'Piye', p: 'Napata, Nubien', d: 'Den nubiske konge, der sejlede nordpå og gjorde Egypten til sit; hans sejrsstele påbød generalerne at bade og bede før slaget, og kongelige pyramider rejste sig igen ved El-Kurru.' },
  ph_shabaka: { n: 'Shabaka', p: 'Memfis, Egypten', d: 'Han befæstede det kushitiske styre fra Memfis, restaurerede gamle monumenter og lod den memfitiske skabelsesteologi hugge i sten — Shabakastenen, som bevarede den for eftertiden.' },
  ph_shebitku: { n: 'Shebitku', p: 'Memfis, Egypten', d: 'Han sendte kushitiske hære af sted for at standse Assuriens fremmarch i Levanten — det første sammenstød, der trak Assuriens hævn ned over Egypten.' },
  ph_taharqa: { n: 'Taharqa', p: 'Memfis, Egypten', d: 'Bibelens Tirhaka, en byggende konge, hvis monumenter strakte sig fra Nubien til deltaet — indtil Assyrien plyndrede Memfis og Theben og gjorde ende på kushitisk magt i Egypten.' },
  ph_tantamani: { n: 'Tantamani', p: 'Memfis, Egypten', d: 'Den sidste kushitiske farao: han generobrede kort Egypten, men Assuriens modslag brændte Theben så grundigt, at byen aldrig genvandt sin gamle anseelse.' },
  ph_psamtik_i: { n: 'Psametik I', p: 'Sais, Egypten', d: 'En assyrisk vasal, der overlevede sin herres magt og gjorde Egypten uafhængigt igen — hans græske lejesoldater indledte deltaets græske tidsalder.' },
  ph_necho_ii: { n: 'Necho II', p: 'Sais, Egypten', d: 'Den kanalgravnende og flådebyggende konge, der dræbte Josias af Judæa ved Megiddo — og sendte fønikere ud på historiens første optegnede rejse rundt om Afrika.' },
  ph_psamtik_ii: { n: 'Psametik II', p: 'Sais, Egypten', d: 'Han ledede et straffeltog dybt ind i Kush; hans græske lejesoldaters graffiti ved Abu Simbel er den ældste daterede græske skrift, der kendes fra Egypten.' },
  ph_apries: { n: 'Apries', p: 'Sais, Egypten', d: 'Bibelens “Hofra”, hvis hær ikke formåede at redde Jerusalem fra Babylon; hans begunstigelse af græske tropper udløste det indfødte oprør, der førte Amasis til tronen.' },
  ph_amasis_ii: { n: 'Amasis II', p: 'Sais, Egypten', d: 'Tronraneren, der blev Herodots model på en klog og afslappet konge — han grundlagde den græske handelsby Naukratis og overøste templerne med gaver.' },
  ph_psamtik_iii: { n: 'Psametik III', p: 'Sais, Egypten', d: 'Konge i omkring seks måneder; Kambyses’ persere væltede ind over Egypten, og hans henrettelse efter et håbløst oprør lukkede den indfødte styretid i et århundrede.' },
  ph_cambyses_ii: { n: 'Kambyses II', p: 'Memfis, Egypten', d: 'Persiens erobrer af Egypten, kronet til farao i en bevidst omfavnelse af den egyptiske tradition — selv om græske forfattere malede ham som en galning for at have dræbt Apis-tyren.' },
  ph_darius_i: { n: 'Dareios I', p: 'Memfis, Egypten', d: 'En bedre konge, end græsk tradition indrømmer: han kodificerede den egyptiske lov, fuldendte kanalen til det Røde Hav og reparerede templer og gjorde Egypten til imperiets rigeste provins.' },
  ph_xerxes_i: { n: 'Xerxes I', p: 'Memfis, Egypten', d: 'Storkongen, der er berømt fra grækerkrigene, styrede Egypten hårdere, og hans tunge krav skabte det oprør, hans efterfølger måtte slå ned.' },
  ph_artaxerxes_i: { n: 'Artaxerxes I', p: 'Memfis, Egypten', d: 'Egypten brød ud under Inaros med athensk hjælp, og Persien brugte seks år og en stor flåde på at vinde den rige provins tilbage.' },
  ph_darius_ii: { n: 'Dareios II', p: 'Memfis, Egypten', d: 'Den persiske kontrol forfaldt gennem hans regeringstid; inden for et år efter hans død kontrollerede en egyptisk prins, Amyrtaios, atter deltaet.' },
  ph_amyrtaeus: { n: 'Amyrtaios', p: 'Sais, Egypten', d: 'Oprørsprinsen fra Sais, der jagede de persiske garnisoner ud og regerede som den eneste konge af 28. dynasti.' },
  ph_nefaarud_i: { n: 'Nefaarud I', p: 'Mendes, Egypten', d: 'Grundlægger af 29. dynasti i Mendes og en allieret af Sparta i Grækenlands krig mod Persien.' },
  ph_achoris: { n: 'Achoris', p: 'Mendes, Egypten', d: 'En energisk hersker, der finansierede Cypern og Athen mod Persien og stemplede sin kartouche på monumenter overalt — det indfødte Egyptens dygtige sene opblomstring.' },
  ph_nectanebo_i: { n: 'Nektanebos I', p: 'Sebennytos, Egypten', d: 'En general fra den mendesiske slægt, der bemægtigede sig tronen, afviste Persiens store comebackforsøg og begyndte Isis’ tempel på File.' },
  ph_teos: { n: 'Teos', p: 'Sebennytos, Egypten', d: 'Han ledede Egyptens sidste angrebskrig ind i Syrien — hvorefter hans nevø med lejesoldaternes støtte ranede tronen, og felttoget kollapsede.' },
  ph_nectanebo_ii: { n: 'Nektanebos II', p: 'Sebennytos, Egypten', d: 'Egyptens sidste indfødte farao, en gavmild beskytter af templerne — indtil Artaxerxes III med sin store invasion for altid gjorde ende på det indfødte styre; legenden gjorde ham senere til Alexanders hemmelige far.' },
  ph_artaxerxes_iii: { n: 'Artaxerxes III', p: 'Memfis, Egypten', d: 'Den persiske generobrer, hvis generobring af Egypten var brutal; et årti senere ødelagde Alexander imperiet, og Egypten skiftede atter hænder.' },
  ph_ptol_i: { n: 'Ptolemaios I Soter', p: 'Alexandria, Egypten', d: 'Alexanders general, der gjorde Egypten til sit eget kongerige — han sikrede sig Alexanders lig til Alexandria, grundlagde Biblioteket og Museion og skrev den første historie om krige.' },
  ph_ptol_ii: { n: 'Ptolemaios II Philadelphos', p: 'Alexandria, Egypten', d: '“Søsterelskende”: han giftede sig med sin fulde søster Arsinoe II, førte Fyrtårnet på Faros og Biblioteket til deres højdepunkt og bragte Egypten til sin største udstrækning.' },
  ph_ptol_iii: { n: 'Ptolemaios III Euergetes', p: 'Alexandria, Egypten', d: '“Velgøreren” hævnede sin søster ved at invadere Syrien og hente Egyptens gudestatuer hjem; hans regeringstid var det ptolemæiske imperiums videste rækkevidde.' },
  ph_ptol_iv: { n: 'Ptolemaios IV Philopator', p: 'Alexandria, Egypten', d: 'Han besejrede Antiochos III ved Raphia — et slag med 100.000 mænd og krigselefanter — ved at støtte sig til indfødte egyptiske tropper, hvis nye magt begyndte dynastiets fald.' },
  ph_ptol_v: { n: 'Ptolemaios V Epiphanes', p: 'Alexandria, Egypten', d: 'En barnekonge, hvis dekret på Rosettestenen — historiens nøgle til hieroglyfferne — belønnede præsternes loyalitet, mens imperiet smuldrede bort.' },
  ph_ptol_vi: { n: 'Ptolemaios VI Philometor', p: 'Alexandria, Egypten', d: 'Femogtredive års familieborgerkrig med sin bror og den medregerende dronning; han døde af skaderne fra et fald efter en syrisk sejr og efterlod fejden brændende.' },
  ph_ptol_viii: { n: 'Ptolemaios VIII Euergetes II', p: 'Alexandria, Egypten', d: 'Den oppustede, skånselsløse overlever: han dræbte sin nevøkonge, giftede sig med sin søster og derefter hendes datter og testamenterede Egypten til den dronning, der overlevede ham.' },
  ph_ptol_ix: { n: 'Ptolemaios IX Soter II', p: 'Alexandria, Egypten', d: '“Lathyros”, kikærtekongen — to gange jaget ud af sin egen mors fraktion og to gange genindsat; hans fejder tømte Alexandria for de græske lærde.' },
  ph_ptol_x: { n: 'Ptolemaios X Alexander I', p: 'Alexandria, Egypten', d: 'Han stjal tronen fra sin bror og testamenterede Egypten til Rom i sit testamente — et papirkrav, som Augustus indløste et århundrede senere.' },
  ph_ptol_xi: { n: 'Ptolemaios XI Alexander II', p: 'Alexandria, Egypten', d: 'Nitten dage efter at have giftet sig med sin stedmor som medregent myrdede han hende — og Alexandrias pøbel flåede ham ad som hævn.' },
  ph_ptol_xii: { n: 'Ptolemaios XII Auletes', p: 'Alexandria, Egypten', d: '“Fløjtespilleren” købte romersk anerkendelse med ruinerende bestikkelser, flygtede fra et indfødt oprør i 58 f.Kr. og vendte tilbage bag romerske legioner; hans ældste datter var Kleopatra VII.' },
  ph_berenice_iv: { n: 'Berenike IV', p: 'Alexandria, Egypten', d: 'Hun regerede i sin fars eksilår og døde for det — den tilbagevendende Ptolemaios XII henrettede sin egen datter.' },
  ph_ptol_xiii: { n: 'Ptolemaios XIII', p: 'Alexandria, Egypten', d: 'Kleopatras bror og ægtefælle, hvis regenter jagede hende ud og belejrede Cæsar i Alexandria; han druknede i Nilen, i rustning, efter sit endelige nederlag.' },
  ph_ptol_xiv: { n: 'Ptolemaios XIV', p: 'Alexandria, Egypten', d: 'Den yngre bror, indsat som Kleopatras gemal — død inden for tre år, angiveligt på ordre fra søsteren og hustruen.' },
  ph_caesarion: { n: 'Ptolemaios XV Cæsarion', p: 'Alexandria, Egypten', d: '“Lille Cæsar”, Kleopatras søn med Julius Cæsar og den sidste af ptolemæerne — Octavian lod den syttenårige sætte til livs efter Actium med bemærkningen, at for mange Cæsarer ikke var godt.' },
});

/* Mesopotamian rulers - 45 entries (2026-10-30) */
Object.assign(window.DATA_DA, {
  me_enmebaragesi: { n: 'Enmebaragesi', p: 'Kish, Mesopotamien', d: 'Den første mesopotamiske hersker, arkæologien kan bevise — bevidnet på en knust vase fra Nippur og husket af traditionen som fader til den konge, Gilgamesh kæmpede imod.' },
  me_gilgamesh: { n: 'Gilgamesh', p: 'Uruk, Mesopotamien', d: 'En virkelig konge af Uruk omkring 2700 f.Kr., senere helten i verdens første store epos — bymuren, lyder det i den sumeriske kongeliste, strakte sig over fem kilometer.' },
  me_mesannepada: { n: 'Mesannepada', p: 'Ur, Mesopotamien', d: 'Grundlægger af Urs første dynasti, hvis kongelige gravplads frembragte de gyldne hjelme og lyrerne med oksehoveder, der definerer Sumers storhedstid.' },
  me_eannatum: { n: 'Eannatum', p: 'Lagash, Mesopotamien', d: 'Han lod Gribbestelen udhugge til ære for sejren over Umma — historiens første detaljerede billede af et slag, med skjoldmur, spydkæmpere og en konge på krigsvogn.' },
  me_lugalzagesi: { n: 'Lugalzagesi', p: 'Uruk, Mesopotamien', d: 'Den sidste indfødte sumeriske overherre: han forenede sydlandet fra Uruk og tabte derefter alt til Sargon af Akkad, der ifølge sagnet førte ham i hundehalsbånd frem til Nippurs porte.' },
  me_sargon: { n: 'Sargon af Akkad', p: 'Akkad, Mesopotamien', d: 'Vinskænkeren, der greb kongemagten og smedede historiens første multietniske rige fra sin by Agade — hvis beliggenhed endnu er ukendt; sagnene fortalte, hvordan spædbarnet i en sivkurv drev ned ad Eufrat.' },
  me_naram_sin: { n: 'Naram-Sin', p: 'Akkad, Mesopotamien', d: 'Den første mesopotamiske konge, der erklærede sig selv for gud — hans bjergsejrsrelief viser gudekongen marchere hen over Zagrosbjergene, og under ham nåede riget sin videste udstrækning, før det begyndte at sprække.' },
  me_sharkalisharri: { n: 'Shar-Kali-Sharri', p: 'Akkad, Mesopotamien', d: '“Konge over de fire verdenshjørner”: en regeringstid med endeløse felttog, der holdt riget sammen — efter ham opløstes Akkad i gutiernes styre inden for en generation.' },
  me_utuhegal: { n: 'Utu-Hegal', p: 'Uruk, Mesopotamien', d: 'Uruk-kongen, der jagede gutiernes bjergfolk ud og genskabte den sumeriske kongemagt — hans sejrsstel hører til de sidste store monumenter fra det gamle Sumer.' },
  me_gudea: { n: 'Gudea', p: 'Lagash, Mesopotamien', d: 'Herskeren i Lagash, der efterlod sig mere end to dusin afklarede dioritstatuer — og en beretning på lercylindre om en gudgiven drøm, der fik ham til at bygge Ningirsus tempel.' },
  me_urnammu: { n: 'Ur-Nammu', p: 'Ur, Mesopotamien', d: 'Grundlægger af Ur III-riget: hans store ziggurat i Ur står endnu, og hans lovsamling — århundreder før Hammurapis — er den ældste, der er fundet.' },
  me_shulgi: { n: 'Shulgi', p: 'Ur, Mesopotamien', d: 'En regeringstid på 48 år med vejstationer, standardiserede skriveskoler og rigsdækkende lov — kronet af en selvskrevet hymne, der pralede af, at han engang løb 320 kilometer på én dag.' },
  me_ibbisin: { n: 'Ibbi-Sin', p: 'Ur, Mesopotamien', d: 'Urs sidste konge, udsultet af amoritternes herjinger og elamitiske hære — klagesangen over Urs fald blev tidens mest kopierede digt.' },
  me_ishbierra: { n: 'Ishbi-Erra', p: 'Isin, Mesopotamien', d: 'En amoritisk officer i Urs tjeneste, der kastede elamiterne ud og grundlagde Isin-dynastiet og gjorde krav på det faldne rigs lærde og hellige arv.' },
  me_lipitishtar: { n: 'Lipit-Ishtar', p: 'Isin, Mesopotamien', d: 'Hans lovsamling, ristet halvandet århundrede før Hammurapis, beskyttede enker og forældreløse — og hans skolehymner gjorde ham senere til skrivernes gud.' },
  me_rimsin: { n: 'Rim-Sin I', p: 'Larsa, Mesopotamien', d: 'Han regerede i tres år over Larsa — længere end nogen dokumenteret konge før den moderne tid — og tabte derpå sin hovedstad i ét eneste felttog til Hammurapi af Babylon.' },
  me_sumuabum: { n: 'Sumu-abum', p: 'Babylon, Mesopotamien', d: 'Amorithøvdingen, der gjorde Babylon til et dynastisæde — en ubetydelig flodby, som hans slægt skulle løfte op til verdens midtpunkt.' },
  me_hammurabi: { n: 'Hammurapi', p: 'Babylon, Mesopotamien', d: 'Skaberen af Babylons rige — han tog Larsa, Mari og Assyrien efter tur, og hans lovstele, rejst “for at de stærke ikke skulle undertrykke de svage”, blev i århundreder stående som retfærdighedens symbol.' },
  me_samsuiluna: { n: 'Samsu-iluna', p: 'Babylon, Mesopotamien', d: 'Han arvede sin faders rige, slog en kassitisk invasion tilbage og så det fjerne syd løsrive sig som dynastiet i Havlandet — imperiets kanter var allerede ved at gå op.' },
  me_burnaburiash: { n: 'Burna-Buriash II', p: 'Babylon, Mesopotamien', d: 'Kassitkongen, hvis breve til Egyptens faraoner, fundet i Amarna, prutter om guld og kongelige bruder — bronzealderens stormagtsdiplomati på sit allerfineste.' },
  me_kurigalzu_ii: { n: 'Kurigalzu II', p: 'Babylon, Mesopotamien', d: 'En stridende kassitkonge, der standsede Assyriens fremvækst i hård kamp og smykkede Dur-Kurigalzu med en ziggurat, hvis stump endnu ruver vest for Bagdad.' },
  me_nebuchadnezzar_i: { n: 'Nebukadnezar I', p: 'Babylon, Mesopotamien', d: 'Han hævnede Babylons ydmygelse: hærgede dybt ind i Elam og førte guden Marduks stjålne statue hjem i triumf — en gerning, som senere babylonske konger vedblev at fejre.' },
  me_mardukaplaiddina: { n: 'Marduk-apla-iddina II', p: 'Babylon, Mesopotamien', d: 'Bibelens “Merodach-Baladan”: en kaldeisk høvding, der to gange bemægtigede sig Babylon og trodsede Sargon II og Sanherib i to årtier, mens han søgte allierede så langt borte som i Judæa.' },
  me_shamashshumukin: { n: 'Shamash-shum-ukin', p: 'Babylon, Mesopotamien', d: 'Assurbanipals bror, indsat som Babylons konge under assyrisk overherredømme — hans seks år lange oprør for Babylons frihed endte i en belejring, hvor han ifølge én kilde brændte i sit eget palads.' },
  me_nabopolassar: { n: 'Nabopolassar', p: 'Babylon, Mesopotamien', d: 'Kaldeeren, der genoprettede Babylons frihed og begravde Assyrien — med mediske allierede stormede han Ninive i 612 f.Kr. og overlod de sidste felttog i vest til sin søn.' },
  me_nebuchadnezzar_ii: { n: 'Nebukadnezar II', p: 'Babylon, Mesopotamien', d: 'Babylons største konge: han besejrede Egypten ved Karkemish, tog Jerusalem og brændte det i 586 f.Kr. og opførte Ishtarporten og den ziggurat, der huskes som Babelstårnet.' },
  me_amelmarduk: { n: 'Amel-Marduk', p: 'Babylon, Mesopotamien', d: 'Bibelens “Evil-Merodach”, som løslod Judæas fangne konge fra fængslet — to år senere myrdede hans svoger Neriglissar ham.' },
  me_neriglissar: { n: 'Neriglissar', p: 'Babylon, Mesopotamien', d: 'En babylonsk general, der tog tronen ved mord, førte krig i Kilikien og døde efter fire år — han efterlod en guttearving til sammensvornes nåde.' },
  me_labashimarduk: { n: 'Labashi-Marduk', p: 'Babylon, Mesopotamien', d: 'En guttekonge i ni måneder, myrdet af sammensvorne, der overgav kronen til Nabonidus — dynastiets sidste krampetrækning før faldet.' },
  me_nabonidus: { n: 'Nabonidus', p: 'Babylon, Mesopotamien', d: 'Babylons sidste konge: en tilbeder af måneguden Sin, der stødte Marduks præster fra sig, tilbragte et årti ved oasen Teima og mistede sin by til Kyros af Persien uden kamp i 539 f.Kr.' },
  me_shamshiadad: { n: 'Shamshi-Adad I', p: 'Shubat-Enlil, Assyrien', d: 'Amoritten, der skabte et rige i Øvre Mesopotamien fra Assur til Middelhavet og satte sine sønner som guvernører — hans breve med skælderud til en vildfarende arving er bevaret i arkiverne i Mari.' },
  me_zimrilim: { n: 'Zimri-Lim', p: 'Mari, Mesopotamien', d: 'Kongen af Mari, hvis paladsarkiver — tusindvis af breve, retssager og profetier — er vores vindue ind til det gammelbabylonske liv; Hammurapi tog hans by og brændte den.' },
  me_ashuruballit_i: { n: 'Assuruballit I', p: 'Assur, Assyrien', d: 'Han kastede Mitannis åg af sig og gjorde Assyrien til en stormagt — den første assyrer, der skrev til Egypten som ligeværdig blandt “store konger”.' },
  me_tukultininurta_i: { n: 'Tukulti-Ninurta I', p: 'Assur, Assyrien', d: 'Han knuste kassiterne og tog Babylon og bortførte Marduks statue — derefter byggede han en ny hovedstad, Kar-Tukulti-Ninurta, og døde myrdet af egne sønner.' },
  me_tiglathpileser_i: { n: 'Tiglat-Pileser I', p: 'Assur, Assyrien', d: 'En kriger og jæger fra bronzealderen, der marcherede til Middelhavet og påstod at have dræbt 920 løver fra sin stridsvogn; efter ham skrumpede Assyrien ind til sit hjemland i to århundreder.' },
  me_adadnirari_ii: { n: 'Adad-nirari II', p: 'Assur, Assyrien', d: 'Genopretteren: han brød den aramæiske ring omkring Assur, genvandt Habur-landene og satte Assyrien på den to århundreder lange vej mod imperiet.' },
  me_ashurnasirpal_ii: { n: 'Assurnasirpal II', p: 'Nimrud, Assyrien', d: 'Levantens skræk, der flyttede hovedstaden til Nimrud — relieffer med flåede oprørere og et gæstebud for 69.574 gæster viser de to sider af assyrisk kongemagt.' },
  me_shalmaneser_iii: { n: 'Salmanassar III', p: 'Nimrud, Assyrien', d: 'Hans 34 år med felttog mødte Levantens første store koalition ved Karkar i 853 f.Kr. — og den sorte obelisk viser Israels Jehu bøje sig for at yde tribut.' },
  me_tiglathpileser_iii: { n: 'Tiglat-Pileser III', p: 'Assur, Assyrien', d: 'Reformkejseren: en professionel hær, massedeportation som politik, Babylon erobret som “Pulu”, og Judæa og Israel gjort til tributbetalere — Bibelens “Pul”.' },
  me_sargon_ii: { n: 'Sargon II', p: 'Dur-Sharrukin, Assyrien', d: 'Han tog Samaria og gjorde ende på Israels kongerige, anlagde en ny hovedstad med firkantet bymur ved Dur-Sharrukin og faldt i kamp mod kimmerierne — hans lig blev aldrig fundet.' },
  me_sennacherib: { n: 'Sanherib', p: 'Ninive, Assyrien', d: 'Han gjorde Ninive til et underværk af kanaler og mure, brændte Babylon i 689 f.Kr. og belejrede Jerusalem i 701 f.Kr. — og blev myrdet af sine egne sønner i et tempel.' },
  me_esarhaddon: { n: 'Esarhaddon', p: 'Ninive, Assyrien', d: 'Han genopbyggede det Babylon, hans fader lagde øde, erobrede Egypten og indtog Memfis i 671 f.Kr. og døde derpå atter på vej til Egypten — og efterlod en omhyggeligt tilrettelagt dobbelt arvefølge.' },
  me_ashurbanipal: { n: 'Assurbanipal', p: 'Ninive, Assyrien', d: 'Den lærde konge: hans bibliotek i Ninive bevarede Gilgamesh-eposset for os, hans relieffer viser ham holde fest under en død fjendes hoved — og inden for én generation efter hans død var riget borte.' },
  me_sinsharishkun: { n: 'Sin-shar-ishkun', p: 'Ninive, Assyrien', d: 'Hans regeringstid løb ud i borgerkrig — så kom mederne og babylonerne: Ninive faldt i 612 f.Kr. så fuldstændigt, at stedet blev glemt inden for århundreder.' },
  me_ashuruballit_ii: { n: 'Assuruballit II', p: 'Harran, Assyrien', d: 'Assyriens sidste konge, kronet i Harran over imperiets rester; egyptisk undsætning slog fejl, og med hans nederlag forsvandt Assyrien fra historien i to tusind år.' },
});
/* da translations — Napoleonic Wars battles (2026-10-30) */
Object.assign(window.DATA_DA, {
  nb_toulon: { n: 'Belejringen af Toulon', p: 'Toulon, Frankrig', d: 'En ung artillerikaptajn ved navn Napoleon Bonaparte planlægger erobringen af den britiske flådebase — hans første kommando og springbrættet til alt, hvad der følger.' },
  nb_lodi: { n: 'Slaget ved Lodi', p: 'Lodi, Italien', d: 'Angrebet over Adda-broen gør den unge general til en helt for sine egne soldater — »den lille korporal« er født, og Italien bliver hans laboratorium.' },
  nb_arcole: { n: 'Slaget ved Arcole', p: 'Arcole, Italien', d: 'Tre dages kamp i sumpene ved Alpone: Napoleon erobrer personligt den berømte bro under beskydning og tvinger til sidst østrigerne under Alvinczi til at vende om.' },
  nb_rivoli: { n: 'Slaget ved Rivoli', p: 'Rivoli, Italien', d: 'Det første italienske felttogs afsluttende mesterværk — koncentriske angreb knuser fire østrigske kolonner, og Mantua kapitulerer endelig.' },
  nb_pyramids: { n: 'Slaget ved pyramiderne', p: 'Giza, Ægypten', d: '»Soldater, fra toppen af disse pyramider betragter fyrre århundreder jer« — infanteriets karréer knuser mamelukkernes kavaleri foran Kairo.' },
  nb_nile: { n: 'Slaget på Nilen', p: 'Abukirbugten, Ægypten', d: 'Nelson ankreder op side om side med den franske flåde og ødelægger den i nattens løb — hæren i Ægypten er afskåret, og Storbritannien behersker Middelhavet.' },
  nb_novi: { n: 'Slaget ved Novi', p: 'Novi Ligure, Italien', d: 'Suvorovs østrig-russiske hær knuser franskmændene i Apenninernes udløbere; den unge general Joubert dræbes af den første salve.' },
  nb_marengo: { n: 'Slaget ved Marengo', p: 'Marengo, Italien', d: 'Et slag, der først tabes og så reddes af den vendende kolonne under Desaix og et masseret kavaleriangreb — og som Napoleon for altid genfortæller som Konsulatets grundlæggende legende.' },
  nb_hohenlinden: { n: 'Slaget ved Hohenlinden', p: 'Hohenlinden, Tyskland', d: 'Moreaus baghold i de frosne skove vest for München sønderslår en østrigsk hær og tvinger Wien til Freden i Lunéville.' },
  nb_copenhagen: { n: 'Slaget på Reden', p: 'København, Danmark', d: 'Nelson sætter kikkerten for sit blinde øje, ignorerer signalet om at trække sig tilbage og ødelægger den danske flåde — Storbritanniens svar på den væbnede neutralitet i nord.' },
  nb_ulm: { n: 'Slaget ved Ulm', p: 'Ulm, Tyskland', d: 'Syv franske korps drejer i en kæmpe bue rundt om Schwarzwald og opsluger Macks hele østrigske hær — 60 000 fanger for knap 500 franske faldne.' },
  nb_trafalgar: { n: 'Slaget ved Trafalgar', p: 'Kap Trafalgar, Spanien', d: 'Nelson gennembryder den fransk-spanske linje ud for Kap Trafalgar og vinder den mest afgørende søsejr i britisk historie — han dør i triumfens øjeblik; en invasion af England bliver umulig.' },
  nb_austerlitz: { n: 'Slaget ved Austerlitz', p: 'Austerlitz, Mæhren', d: 'Napoleons mesterværk: han lokker de allierede til at forlade Pratzen-højderne og deler deres centrum i tågen — »solen over Austerlitz« gør ende på den tredje koalition.' },
  nb_jena_auerstedt: { n: 'Slaget ved Jena–Auerstedt', p: 'Jena, Tyskland', d: 'To slag på én morgen: Napoleon knuser en preussisk hær ved Jena, mens Davout besejrer en større ved Auerstedt — Preussen kollapser inden for tre uger.' },
  nb_eylau: { n: 'Slaget ved Eylau', p: 'Eylau, Preussen', d: 'Et frossent og uafgjort blodbad i sneen — Napoleons første store modgang mod Bennigsens russere; Ney rider over slagmarken: »For et slagteri! Og uden resultat«.' },
  nb_friedland: { n: 'Slaget ved Friedland', p: 'Friedland, Preussen', d: 'Lannes fastlåser russerne med ryggen mod floden Alle, og Napoleon fuldender værket — vejen til Tilsit åbner sig, hvor to kejsere deler Europa.' },
  nb_bailen: { n: 'Slaget ved Bailén', p: 'Bailén, Spanien', d: 'Et helt fransk korps under general Dupont overgiver sig til spanske regulære tropper — det første store nederlag for de napoleonske våben, hvis nyhed tænder oprør over hele Europa.' },
  nb_vimeiro: { n: 'Slaget ved Vimeiro', p: 'Vimeiro, Portugal', d: 'Wellesleys opstilling på bakkens bagside knuser Junots angreb — halvøhærens første slag indleder seks års næsten uafbrudt succes.' },
  nb_zaragoza: { n: 'Belejringen af Zaragoza', p: 'Zaragoza, Spanien', d: 'To belejringer og gadekamp fra hus til hus gør byen under Palafox til et synonym for folkelig modstand — omkring 50 000 spanske døde på få måneder.' },
  nb_somosierra: { n: 'Slaget ved Somosierra', p: 'Somosierra-passet, Spanien', d: 'Polske lette ryttere rider lige op ad det røgslørede bjergpas ind i de spanske kanoner og åbner vejen til Madrid — epokens mest berømte kavaleribravstykke.' },
  nb_corunna: { n: 'Slaget ved A Coruña', p: 'A Coruña, Spanien', d: 'Den grufulde tilbagetrækning til kysten koster den britiske hær dens chef: Sir John Moore falder som sejrherre, mens flåden sejler tropperne hjem.' },
  nb_talavera: { n: 'Slaget ved Talavera', p: 'Talavera, Spanien', d: 'En nat med forvirret kamp og et hårdt angreb midt på dagen slår fejl mod Wellesleys linje — en vikomtetitel til Wellington og bevis på, at krigen i Spanien kan vindes.' },
  nb_eckmuhl: { n: 'Slaget ved Eckmühl', p: 'Eckmühl, Tyskland', d: 'Davouts korps holder alene stand, derefter vender Napoleon personligt den østrigske flanke — ærkehertug Karl undslipper nord for Donau, besejret.' },
  nb_aspern_essling: { n: 'Slaget ved Aspern-Essling', p: 'Wien, Østrig', d: 'Napoleons første store nederlag: Donaus oversvømmelser skærer pontonbroerne over, og Lannes dør, mens han holder kornmagasinet i Essling — Europa lærer, at kejseren kan besejres.' },
  nb_wagram: { n: 'Slaget ved Wagram', p: 'Wagram, Østrig', d: '300 000 mand og det største slag, Europa endnu har set: en frontal udmattelseskamp hen over Marchfeld, hvor store batterier skyder på direkte sigte, gør ende på den femte koalition.' },
  nb_busaco: { n: 'Slaget ved Bussaco', p: 'Bussaco, Portugal', d: 'Masséna kaster sin hær op ad bakke gennem morgentågen og slås blodigt tilbage på Serra — Wellington smutter derefter bag Torres Vedras-linjerne.' },
  nb_torres_vedras: { n: 'Torres Vedras-linjerne', p: 'Torres Vedras, Portugal', d: '152 fæstningsværker og redouter skjuler Wellingtons hær for en sultende fransk vinter — »det mest ubehagelige felttog«, Masséna nogensinde udkæmpede, uden et eneste regulært slag.' },
  nb_fuentes_onoro: { n: 'Slaget ved Fuentes de Oñoro', p: 'Fuentes de Oñoro, Spanien', d: 'Tre dage omkring en brændende landsby — »Havde Boney været her, var vi blevet slået«: Wellington holder stand, og Massénas sidste offensiv i Portugal ender.' },
  nb_albuera: { n: 'Slaget ved Albuera', p: 'Albuera, Spanien', d: 'Soults flankemarch møder Beresfords hær af mange nationer: den britiske fusilierbrigade afgør hele krigens blodigste eftermiddag.' },
  nb_ciudad_rodrigo: { n: 'Belejringen af Ciudad Rodrigo', p: 'Ciudad Rodrigo, Spanien', d: 'Wellington stormer grænsefæstningen på tolv vinterdage, hans tunge fortropper erobrer den store bresche — porten til felttoget i 1812.' },
  nb_badajoz: { n: 'Belejringen af Badajoz', p: 'Badajoz, Spanien', d: 'Krigens blodigste storm: tre brescher taget i en nat af raseri og en plyndring, der bliver en plet på hærens erindring.' },
  nb_salamanca: { n: 'Slaget ved Salamanca', p: 'Salamanca, Spanien', d: 'Wellington ser Marmonts hær overstrække sig og slår til i de fyrre minutter, der ødelægger den — »min dygtigste sejr«, med hans egne ord.' },
  nb_smolensk: { n: 'Slaget ved Smolensk', p: 'Smolensk, Rusland', d: 'Grande Armée indtager en brændende by og finder ingen afgørelse — Kutuzovs hær undslipper mod øst og lokker franskmændene stadig dybere ind i Rusland.' },
  nb_borodino: { n: 'Slaget ved Borodino', p: 'Borodino, Rusland', d: 'Napoleonskrigenes blodigste enkelt dag: den store redoute tages og generobres, 70 000 falder — og Kutuzovs hær går intakt fra slagmarken for at kæmpe igen.' },
  nb_maloyaroslavets: { n: 'Slaget ved Malojaroslavets', p: 'Malojaroslavets, Rusland', d: 'En lille by skifter ejere otte gange; når støvet lægger sig, vender Napoleon fra den nye sydlige vej tilbage til den afbrændte hovedvej fra Moskva — tilbagetrækningen er beseglet.' },
  nb_berezina: { n: 'Slaget ved Berezina', p: 'Berezina, Rusland', d: 'Éblés pontonører bygger broer ud i en iskold flod, mens begge bredder brænder — Grande Armée undslipper en dødelig fælde, og »Bérézina« bliver fransk for en overlevet katastrofe.' },
  nb_lutzen: { n: 'Slaget ved Lützen', p: 'Lützen, Tyskland', d: 'Napoleon, tilbage fra Rusland med en hær af uruttede rekrutter, overrasker de allierede i solsikkemarkerne, hvor Gustav Adolf faldt 180 år tidligere — og atter slipper de væk om natten.' },
  nb_bautzen: { n: 'Slaget ved Bautzen', p: 'Bautzen, Tyskland', d: 'En todages sejr uden sin fælde: en tabt ordre lader de allierede undslippe mod øst — begge sider indgår våbenhvilen i Pläswitz og tæller værnepligtige.' },
  nb_grossbeeren: { n: 'Slaget ved Großbeeren', p: 'Großbeeren, Tyskland', d: 'Oudinots march mod Berlin standses i et tordenvejr af Bülows preussere — mange af dem uruttede Landwehr-soldater — og hovedstaden forbliver for altid uden for fransk rækkevidde.' },
  nb_dresden: { n: 'Slaget ved Dresden', p: 'Dresden, Tyskland', d: 'Napoleons sidste store sejr på tysk jord: et modangreb fra den undertallige besætning opsluger 35 000 allierede fanger — betalt igen få dage senere ved Kulm.' },
  nb_kulm: { n: 'Slaget ved Kulm', p: 'Kulm, Bøhmen', d: 'Vandamme forfølger ned gennem bjergpassene og bliver grebet i dalens munding — 13 000 franske fanger udjævner regnskabet fra Dresden.' },
  nb_dennewitz: { n: 'Slaget ved Dennewitz', p: 'Dennewitz, Tyskland', d: 'En anden march mod Berlin dør i et preussisk modstød, der knuser Neys korps — Bernadottes svenskere lukker flanken.' },
  nb_leipzig: { n: 'Folkeslaget ved Leipzig', p: 'Leipzig, Tyskland', d: 'Folkeslaget: 600 000 mand over fire dage, Europas største slag frem til Verdenskrigen — det saksiske korps deserterer midt i kampen, og kejserriget øst for Rhinen er slut.' },
  nb_hanau: { n: 'Slaget ved Hanau', p: 'Hanau, Tyskland', d: 'Wrede forsøger at spærre den franske vej hjem bag Kinzig — den tilbagetrækkende Grande Armée slår sig alligevel igennem og når Rhinen.' },
  nb_victoria: { n: 'Slaget ved Vitoria', p: 'Vitoria, Spanien', d: 'Den franske hær opløses i en trafikprop af plyndringsvogne på vejen til Frankrig: Joseph Bonaparte mister Spanien, sin trone — og sit sølvtøj.' },
  nb_la_rothiere: { n: 'Slaget ved La Rothière', p: 'La Rothière, Frankrig', d: 'Napoleon angriber de allierede kolonner i sneen i Champagne, og for første gang tæller slaget imod ham.' },
  nb_montmirail: { n: 'Slaget ved Montmirail', p: 'Montmirail, Frankrig', d: 'Seksdagesfelttoget på sit højdepunkt: to allierede hære besejret én efter den anden af samme franske styrke på to dage — den gamle magi vender kortvarigt tilbage.' },
  nb_craonne: { n: 'Slaget ved Craonne', p: 'Craonne, Frankrig', d: 'Den unge garde udbløder under stormen af plateauet over Chemin des Dames — en sejr købt til en pris, der chokerer selv marskallerne; vejen til Laon forbliver spærret.' },
  nb_paris_battle: { n: 'Slaget om Paris', p: 'Paris, Frankrig', d: 'Seks dages angreb fra de allierede; marskallerne overgiver hovedstaden — og Napoleon, forladt af sin egen Senat, abdicerer i Fontainebleau inden for samme uge.' },
  nb_toulouse: { n: 'Slaget ved Toulouse', p: 'Toulouse, Frankrig', d: 'Soults skanser koster halvøhæren sin blodigste franske eftermiddag — begge sider kæmper videre i en krig, der sluttede, da Paris faldt og Napoleon abdikerede.' },
  nb_ligny: { n: 'Slaget ved Ligny', p: 'Ligny, Belgien', d: 'Napoleons sidste sejr: preusserne slås tilbage fra bækken ved Ligny, den gamle Blücher kastes af hesten i et kavaleriangreb — men hæren er ikke knækket, og den vil marchere.' },
  nb_quatre_bras: { n: 'Slaget ved Quatre Bras', p: 'Quatre Bras, Belgien', d: 'Neys langsomme angreb møder Wellingtons linje, der netop når frem i sidste øjeblik, mellem rugmarkerne — vejkrydset holder, og de to koalitionshære samles to dage senere ved Waterloo.' },
  nb_wavre: { n: 'Slaget ved Wavre', p: 'Wavre, Belgien', d: 'Grouchy udkæmper en biskamp ved Wavre, mens kanonerne ved Waterloo drøner — 33 000 mand og hele felttoget afhænger af en march, han aldrig foretager.' },
});

/* da translations — Alexander den Stores felttog (2026-10-30) */
Object.assign(window.DATA_DA, {
  aw_granicus: { n: 'Slaget ved Granikos', p: 'Floden Granikos, Anatolien', d: 'I sit første store slag i Asia rir Alexander næsten lige ned over floden mod det persiske center og undgår døden med nød og næppe — men det makedonske kavaleri knuser satrapernes linje; vejen ind i Dareios’ rige står åben.' },
  aw_issus: { n: 'Slaget ved Issos', p: 'Issos, Kilikien', d: 'Dareios III kommer bag på Alexander i Kilikien — og møder ham på en kystslette for smal til hans tallmessige overlegenhed; storkongen flygter og efterlader mor, hustru og det gyldne telt, mens Alexander afviser alle fredstilbud.' },
  aw_tyre: { n: 'Belejringen af Tyros', p: 'Tyros, Fønikien', d: 'Tyros nægter at slippe Alexander ind og holder stand i syv måneder fra øen en halv kilometer ude i vandet; han fylder sundet med en dæmning — oldtidens store ingeniørbelejring, der ender med storm, massakre og 30 000 indbyggere solgt som slaver.' },
  aw_alexandria_found: { n: 'Grundlæggelsen af Alexandria', p: 'Nildeltaet, Egypten', d: 'Tilbage fra Ammons orakel i Siwa udstikker Alexander Alexandria ved Faros, øen Homer sang om — byen der bliver ptolmæernes hovedstad og hjemmet for biblioteket, museion og Faros-fyrtårnet.' },
  aw_gaugamela: { n: 'Slaget ved Gaugamela', p: 'Gaugamela, Assyrien', d: 'Dareios planerer terrænet for sine seglhjulte stridsvogne og en enorm hær; Alexander glider med linjen mod højre og kaster kilen gennem det persiske center — storkongen flygter til Ekbatana, og Babylon, Susa og Persepolis åbner portene.' },
  aw_persian_gate: { n: 'Slaget ved perserportene', p: 'Zagros-bjergene, Persien', d: 'Ariobarzanes spærrer det smalle pas med nogle få tusind mand og stopper hele hæren i ugevis — Thermopylerne på hovedet; Alexander deler styrkerne og går ham i flanken gennem sneen, med Persepolis og rigets skatkammer lige bagved.' },
  aw_alexandria_eschate: { n: 'Grundlæggelsen af Alexandria Eschate', p: 'Jaxartes, Sogdien', d: 'Ved Jaxartes — for grækerne verdens yderste rand — grundlægger Alexander «Alexandria den yderste», dagens Khujand, og slår de skytiske ryttere, der rider over floden for at møde ham.' },
  aw_hydaspes: { n: 'Slaget ved Hydaspes', p: 'Floden Hydaspes, Indien', d: 'I monsunregn sætter Alexander en del af hæren over den svulmende flod om natten og besejrer Porus’ 200 krigselefanter — hans kostbareste sejr; ved Hyphasis nægter veteranerne at marchere mod øst, og Alexander vender om.' },
  ww_sarajevo: { n: 'Attentatet i Sarajevo', p: 'Sarajevo, Bosnien', d: 'Gavrilo Princip skyder ærkehertug Franz Ferdinand ved Latinerbroens hjørne — gnisten, der med Wiens ultimatum bliver til en almeneuropeisk krig inden for fem uger.' },
  ww_july_crisis: { n: 'Julikrisen', p: 'Wien, Østrig', d: 'En måned med ultimatum og mobiliseringsure: Wien straffer Serbien, Berlin giver Østrig »blank check«, Rusland mobiliserer — og enhver generalstabs køreplan indleder en krig, som ingen kan standse.' },
  ww_frontiers: { n: 'Grænzeslagene', p: 'Charleroi, Belgien', d: 'Fransk Plan XVII marcherer ind i tysk kanonild i Lorraine og Ardennerne; ved Mons affyrer det lille British Expeditionary Force sine første skud — og derefter falder alle allierede tilbage for Schlieffen-fremrykningen.' },
  ww_tannenberg: { n: 'Slaget ved Tannenberg', p: 'Stębark (Tannenberg), Østpreussen', d: 'Hindenburg og Ludendorff omringer Samsonovs 2. armé i de østpreussiske søer — 90.000 fanger, generallen skyder sig selv, og Tysklands legende om østfronten er født.' },
  ww_galicia_1914: { n: 'Slaget i Galicien', p: 'Lwów, Galicien', d: 'Det største slag i 1914: russiske hære bryder den østrig-ungarske front, erobrer Lwów og når Karpaterne — imperiet mister sin bedste feltarmé, og krigen når ukrainsk jord.' },
  ww_marne_1: { n: 'Første slag ved Marne', p: 'Marne, Frankrig', d: 'Joffres modstød — parisiske taxaer, der kører reserver frem til fronten — bryder det tyske fremstød mod Paris; bevægelseskrigen ender i skyttegravslinjer, som knap nok flytter sig de følgende fire år.' },
  ww_masurian_1: { n: 'Første slag ved de masuriske søer', p: 'De masuriske søer, Østpreussen', d: 'En anden tysk sejr kaster Rennenkampfs 1. armé ud af Preussen — og østfronten falder til ro i den polske frontbue for vinteren.' },
  ww_antwerp: { n: 'Belejringen af Antwerpen', p: 'Antwerpen, Belgien', d: 'Tysklands tunge haubitser knuser Belgiens sidste fæstning på ti dage; den belgiske hær undslipper langs kysten — og vestfronten strækker sig helt til Nordsøen.' },
  ww_ypres_1: { n: 'Første slag ved Ypern', p: 'Ypern, Belgien', d: 'Omkring den flamske klædeby bruges den britiske regulærhær fra før krigen op på at holde Belgiens sidste åbne hjørne — »Old Contemptibles« dør her, og Ypern-frontbuen opstår.' },
  ww_kolubara: { n: 'Slaget ved Kolubara', p: 'Kolubara, Serbien', d: 'Serbien går til modangreb gennem vintermudderet og generobrer Beograd — ententens første klare sejr over Østrig-Ungarn, vundet af veteraner fra to Balkankrige.' },
  ww_coronel: { n: 'Slaget ved Coronel', p: 'Ud for Coronel, Chile', d: 'Graf Spees østasiatiske eskadre sænker to britiske panserkrydsere ud for Chile — Storbritanniens første sønederlag i et århundrede — og sender Royal Navy på jagt over halve jordkloden.' },
  ww_falkland_battle: { n: 'Slaget ved Falklandsøerne', p: 'Falklandsøerne', d: 'Fem uger efter Coronel hævner Sturdees slagkrydsere nederlaget: Spees eskadre udryddes i Sydatlanten, og Tysklands oversøiske søkrig er forbi.' },
  ww_tsingtao: { n: 'Belejringen af Tsingtao', p: 'Qingdao (Tsingtao), Kina', d: 'Japan, Storbritanniens allierede, stormer Tysklands befæstede kinesiske havn — krigens eneste store slag i Østasien og Japans krav på en stormagtsplads ved freden.' },
  ww_christmas_truce: { n: 'Julevåbenhvilen', p: 'Ploegsteert, Belgien', d: 'Langs store strækninger af vestfronten mødes tyske og britiske soldater i ingenmandsland — julesange, cigaretter, fodbold — noget, der alarmerer overkommandoerne så meget, at det aldrig må ske igen.' },
  ww_east_africa: { n: 'Felttoget i Østafrika', p: 'Dar es Salaam, Tysk Østafrika', d: 'General von Lettow-Vorbeck binder hundredtusinder af allierede tropper i fire års bushkrig — og kapitulerer i Nordrhodesia, ubesejret, elleve dage efter våbenhvilen.' },
  ww_sarikamish: { n: 'Slaget ved Sarıkamış', p: 'Sarıkamış, Kaukasus', d: 'Enver paschas vinteroffensiv ind i Kaukasus kollapser i sneen — en hær på 90.000 mand smadres, og krigspropagandaen leder efter en syndebuk: armenierne.' },
  ww_dogger_bank: { n: 'Søslaget ved Doggerbanke', p: 'Nordsøen', d: 'Britiske slagkrydsere opsnapper et tysk angreb mod Yorkshires kyst og sænker panserkrydseren Blücher — det første tegn på, at Hochseeflotten foretrækker havn frem for slag.' },
  ww_przemysl: { n: 'Belejringen af Przemyśl', p: 'Przemyśl, Galicien', d: 'Østrig-Ungarns store galiciske fæstning falder i marts efter et halvt års belejring — 120.000 fanger, krigens største — og kanonerne er knap nok blevet kolde, før Gorlice-Tarnów indleder den russiske tilbagetrækning.' },
  ww_ypres_2: { n: 'Andet slag ved Ypern', p: 'Ypern, Belgien', d: 'Kloringas driver over skyttegravene for første gang i historien; canadiere tætner den brudte linje — og kemisk krigsførelse bliver en kendsgerning i det tyvende århundrede.' },
  ww_gallipoli: { n: 'Felttoget ved Gallipoli', p: 'Gallipoli-halvøen, Det Osmanniske Rige', d: 'Ententens forsøg på at forcere Dardanellerne dør på klipperne: ANZAC-landingen, ni måneders stillstand, en kvart million faldne og sårede — og en hemmelig evakuering, der bliver grundstenen i Australiens, New Zealands og Tyrkiets nationale erindring.' },
  ww_armenian: { n: 'Det armenske folkedrab', p: 'Konstantinopel, Det Osmanniske Rige', d: 'Den 24. april arresterer den osmanniske regering Konstantinopels armenske elite og begynder deportationerne til den syriske ørken — omkring en million mennesker dør undervejs: det tyvende århundredes første folkedrab.' },
  ww_gorlice: { n: 'Gennembrudsoffensiven ved Gorlice-Tarnów', p: 'Gorlice, Galicien', d: 'Mackensens tysk-østrigske gennembrud flår den russiske front op i Galicien — Przemyśl og Lwów generobres på få uger, og zarens hære begynder den »store tilbagetrækning«.' },
  ww_lusitania: { n: 'Sænkningen af Lusitania', p: 'Ud for Kinsale, Irland', d: 'Én enkelt torpedo sender det store passagerskib til bunds på atten minutter — 1.198 døde, 128 af dem amerikanere — og Tysklands første uindskrænkede ubådskampagne opgives under amerikanske protester.' },
  ww_italy_enters: { n: 'Italien træder ind i krigen', p: 'Rom, Italien', d: 'Storbritannien betaler for Rom med den hemmelige Londonpagt: Italien erklærer Østrig-Ungarn krigen »for Trento og Trieste« — og åbner en bjergfront, der kommer til at koste en million faldne og sårede.' },
  ww_isonzo: { n: 'De elleve slag ved Isonzo', p: 'Gorizia, Italien', d: 'Cadornas hære kaster sig elleve gange på to år mod karstlandskabet over Isonzo for nogle få kilometer stenet floddal — det tolvte forsøg, ved Caporetto, bryder den anden vej.' },
  ww_warsaw_1915: { n: 'Erobringen af Warszawa', p: 'Warszawa, Polen', d: 'I august opgiver zarens hære Warszawa, Vilna og det meste af Polen — fronten stabiliseres en års march længere mod øst, og Rusland bliver krigens mindst pålidelige stormagt.' },
  ww_serbia_1915: { n: 'Serbiens fald', p: 'Beograd, Serbien', d: 'Bulgarien tilslutter sig centralmagterne, og tre hære knuser Serbien på seks uger; den besejrede hær trækker sig tilbage over de albanske bjerge til Korfu — og ententens front ved Saloniki opstår.' },
  ww_kut: { n: 'Belejringen af Kut', p: 'Kut, Mesopotamien', d: 'Townshends britisk-indiske division belejres i Mesopotamiens mudder i 147 dage; ethvert undsætningsforsøg mislykkes — Storbritanniens værste ydmygelse i krigen, og halvdelen af fangerne dør i fangenskab.' },
  ww_verdun: { n: 'Slaget ved Verdun', p: 'Verdun, Frankrig', d: '»De skal ikke passere«: Falkenhayns maskine til at bløde Frankrig hvidt maler videre i ti måneder på Meuses bakker — 700.000 faldne og sårede, historiens længste slag, Frankrigs nationale epos.' },
  ww_sykes_picot: { n: 'Sykes-Picot-aftalen', p: 'London', d: 'En britisk og en fransk diplomat deler Mellemøsten efter krigen med en blyant — Syrien til Paris, Mesopotamien til London — et kort så hemmeligt, at bolsjevikernes trykning af det i 1917 knuser aravernes tillid.' },
  ww_jutland: { n: 'Søslaget ved Jylland', p: 'Nordsøen, ud for Jylland', d: 'Det eneste sammenstød mellem de store dreadnoughtflåder: 250 skibe, 8.600 døde — Tyskland sænker mest tonnage, Storbritannien fastholder blokaden, og begge sider gør krav på havet.' },
  ww_brusilov: { n: 'Brusilov-offensiven', p: 'Luck, Volhynien', d: 'Ruslands sidste store sejr: overraskelsesangreb på en 500 km lang front i Volhynien og Galicien smadrer Østrig-Ungarns hære — 400.000 fanger — men tabene knuser zarhæren, og revolutionen er kun et år borte.' },
  ww_arab_revolt: { n: 'Det arabiske oprør', p: 'Medina, Hijaz', d: 'Mekkas sherif rejser sig mod osmannerne med britisk guld og riffeller: ørkenraidene og Lawrence rider ind i legenden — og der loves et hashemitisk kongerige til Damaskus.' },
  ww_somme: { n: 'Slaget ved Somme', p: 'Somme, Frankrig', d: '57.470 britiske faldne og sårede den første morgen; kampvogne dukker op i september; da novemberregnen gør ende på slaget, ligger en halv million mand døde for ti kilometer af Picardie — krigens varige billede på spild.' },
  ww_bucharest: { n: 'Rumænien træder ind i krigen', p: 'Bukarest, Rumænien', d: 'Bukarest satser på ententen, mens Brusilov rykker frem — og taber alt på fire måneder: Transsylvanien overrendt, hovedstaden erobret i december, regeringen i eksil i Iaşi.' },
  ww_zimmermann: { n: 'Zimmermann-telegrammet', p: 'Mexico City, Mexico', d: 'Londons kodeknækkere overbringer Washington Berlins tilbud til Mexico — Texas, Arizona og New Mexico for en alliance; trykt i den amerikanske presse gør det mere end nogen ubåd for at gøre ende på neutraliteten.' },
  ww_unrestricted: { n: 'Uindskrænket ubådskrig', p: 'Berlin, Tyskland', d: 'Tysklands admiraler lover at sulte Storbritannien ud på fem måneder — og ethvert handelsskib i Atlanten bliver et mål, med konsekvenser i Washington, som de ikke havde regnet med.' },
  ww_us_enters: { n: 'USA træder ind i krigen', p: 'Washington, USA', d: '»Verden skal gøres sikker for demokratiet«: Wilson beder Kongressen om krig i april 1917 — to millioner amerikanere krydser Atlanten, og ententen får et arsenal, der ikke kan udtømmes.' },
  ww_nivelle: { n: 'Nivelle-offensiven og mytterierne', p: 'Chemin des Dames, Frankrig', d: 'Nivelle lover gennembrud på 48 timer; da miraklet udebliver, nægter halvdelen af den franske hær at angribe mere — 68 divisioner i mytteri, i stilhed slået ned af Pétains reformer.' },
  ww_kerensky: { n: 'Kerenskij-offensiven', p: 'Ternopil, Galicien', d: 'Den provisoriske regerings sidste spil — et angreb i Galicien for at bevise, at revolutionært Rusland stadig kæmper; det kollapser på få dage, og hundredtusindvis af desertører bærer riffellerne hjem til sovjetterne.' },
  ww_riga_1917: { n: 'Erobringen af Riga', p: 'Riga, Letland', d: 'Tysklands nye stormtrooptaktik overvælder Riga og derefter de estiske øer (Operation Albion) — en generalprøve på 1918 på en front, der allerede er ved at opløses.' },
  ww_passchendaele: { n: 'Tredje slag ved Ypern', p: 'Passchendaele, Belgien', d: 'Haigs offensiv i Flandern drukner i det vådeste efterår i tredive år — en halv million faldne og sårede på begge sider for otte kilometer mudder; Passchendaele bliver krigens ord for meningsløshed.' },
  ww_caporetto: { n: 'Slaget ved Caporetto', p: 'Kobarid (Caporetto), Slovenien', d: 'Tyske bjergtropper og gas jager den italienske 2. armé på flugt over 100 km — 265.000 fanger; Cadorna afsættes, og Italien holder kun Piave-linjen.' },
  ww_balfour: { n: 'Balfour-deklarationen', p: 'London', d: 'Et brev på 67 ord fra den britiske udenrigsminister støtter »et nationalt hjem for det jødiske folk« i Palæstina — en sætning fra krigens diplomati, hvis konsekvenser stadig diskuteres et århundrede senere.' },
  ww_cambrai: { n: 'Slaget ved Cambrai', p: 'Cambrai, Frankrig', d: 'Næsten 400 kampvogne og intet forudgående bombardement: den 20. november knuser det første masseangreb med kampvogne Hindenburglinjen — og det tyske modangreb ti dage senere lærer begge sider den nye krigsførelses regler.' },
  ww_jerusalem: { n: 'Storbritannien erobrer Jerusalem', p: 'Jerusalem, Palæstina', d: 'Allenby går — ikke rider — ind i den hellige by den 11. december og gør ende på fire århundreders osmannisk styre; Gaza og Beersheba er allerede faldet på vejen, der ender i Damaskus.' },
  ww_brest_litovsk: { n: 'Brest-Litovsk-freden', p: 'Brest-Litovsk, Hviderusland', d: 'I Brest-fæstningen slutter centralmagterne først fred med den ukrainske folkerepublik (9. februar, med anerkendelse af dens uafhængighed), derefter med Sovjetrusland — Tyskland tager en fjerdedel af det gamle imperium og mister den igen inden for året.' },
  ww_spring_offensive: { n: 'Tysklands våroffensiv', p: 'Somme, Frankrig', d: 'Ludendorffs fem store angreb — stormtropper, gas og intet andet mål end et gennembrud: tyskerne trænger længere frem end nogen gang siden 1914 og udmatter sig mod et forsvar, der ikke brister.' },
  ww_czechoslovak_legion: { n: 'Den tjekkoslovakiske legion', p: 'Tjeljabinsk, Rusland', d: 'Halvtreds tusind tidligere krigsfanger kæmper sig vej gennem Sibirien, efter at sovjetterne forsøger at afvæbne dem — de besætter den transsibiriske jernbane og tvinger de allierede til at anerkende et uafhængigt Tjekkoslovakiet.' },
  ww_marne_2: { n: 'Andet slag ved Marne', p: 'Marne, Frankrig', d: 'Det sidste tyske storangreb løber tør ved Marne igen — og det allierede modstød bringer 85.000 friske amerikanere og hundredvis af lette kampvogne; fra juli 1918 holder ententen aldrig op med at rykke frem.' },
  ww_amiens: { n: 'Slaget ved Amiens', p: 'Amiens, Frankrig', d: 'Kampvogne, fly og en tavs spærreild rykker elleve kilometer frem den 8. august — Ludendorffs »sorte dag for den tyske hær«: de hundrede dage triller videre mod den belgiske grænse.' },
  ww_meuse_argonne: { n: 'Meuse-Argonne-offensiven', p: 'Argonne-skoven, Frankrig', d: '1,25 millioner amerikanske soldater maler sig frem gennem Argonne i 47 dage — det største slag i amerikansk historie — for at skære den tyske hærs sidste jernbaneforbindelse ud af Frankrig.' },
  ww_megiddo: { n: 'Slaget ved Megiddo', p: 'Megiddo, Palæstina', d: 'Allenbys mesterstykke i kombineret krigsførelse knuser hele den osmanniske hær i Palæstina på 38 dage — Lawrence rider forrest ind i Damaskus — og krigen i Mellemøsten slutter to måneder før våbenhvilen.' },
  ww_vittorio_veneto: { n: 'Slaget ved Vittorio Veneto', p: 'Vittorio Veneto, Italien', d: 'Italiens hævn for Caporetto: habsburgernes front smuldrer op på en uge, og 400.000 kapitulerer — Østrig-Ungarn, i våben i fire år, underskriver en våbenhvile, der i virkeligheden er en opløsning.' },
  ww_mudros: { n: 'Våbenhvilen i Mudros', p: 'Moudros, Lemnos', d: 'På Lemnos skriver Det Osmanniske Rige under på krigens ende den 30. oktober — sundene åbnes, og Storbritanniens flåde sejler gennem Dardanellerne, som den ikke kunne forcere i 1915.' },
  ww_villa_giusti: { n: 'Våbenhvilen i Villa Giusti', p: 'Padua, Italien', d: 'Habsburgermonarkiet underskriver sin våbenhvile i Padua den 3. november — men imperiet har allerede opløst sig selv i tjekkoslovakiske, polske, jugoslaviske, ungarske og østrigske efterfølgerstater.' },
  ww_kiel_mutiny: { n: 'Matrosoprøret i Kiel og novemberrevolutionen', p: 'Kiel, Tyskland', d: 'Matroserne nægter en sidste selvmordsudsejling, det røde flag vajer over flåden, rådene overtager hver eneste tyske by — den 9. november udråbes republikken, og kejseren flygter til Holland.' },
  ww_armistice: { n: 'Våbenhvilen 11. november 1918', p: 'Rethondes, Frankrig', d: 'I en jernbanevogn i Compiègne-skoven skriver delegationerne under kl. 5.10 om morgenen, og kanonerne tier kl. 11 — tyve millioner døde — »en våbenhvile på tyve år«, vil Foch sige — og tage fejl med to måneder.' },
  ww_poland_1918: { n: 'Polen genopstår', p: 'Warszawa, Polen', d: 'Den dag krigen slutter, overtager Piłsudski kommandoen i Warszawa: efter 123 år med delinger er Polen tilbage på kortet — med grænser, der stadig skal kæmpes for.' },
  ww_czechoslovakia: { n: 'Tjekkoslovakiet grundlægges', p: 'Prag, Tjekkiet', d: 'Den 28. oktober overtager Nationalkomiteen magten i Prag: en republik af tjekker og slovakker, bygget af Masaryk fra Pittsburgh-aftalen til anerkendelsen i Paris — mellemkrigstidens eneste stabile nye demokrati.' },
  ww_habsburg_end: { n: 'Østrig-Ungarn opløses', p: 'Wien, Østrig', d: 'I de sidste uger af oktober 1918 går imperiets folk simpelthen ud af det — Prag, Zagreb, Budapest og Wien udråber deres egne stater; Habsburgermonarkiet slutter ikke med en traktat, men med et vakuum.' },
  ww_yugoslavia: { n: 'Jugoslavien udråbes', p: 'Beograd, Serbien', d: 'Staten af slovenere, kroater og serbere forenes med Serbien den 1. december — et kongerige med tre navne, to alfabeter og fire religioner, samlet af Østrig-Ungarns vragrester.' },
  ww_russian_civil_war: { n: 'Den russiske borgerkrig', p: 'Tsaritsyn, Rusland', d: 'Røde mod hvide fra Østersøen til Stillehavet, med et dusin fremmede hære og den tjekkiske legion imellem — tre år, ti millioner døde, og enpartistaten: Sovjetunionen udråbes i 1922.' },
  ww_saint_germain: { n: 'Saint-Germain-traktaten', p: 'Saint-Germain-en-Laye, Frankrig', d: 'Østrig underskriver sig ned til en restrepublik på syv millioner indbyggere — Sydtyrol til Italien, Galicien til Polen, Sudeterlandet til Tjekkoslovakiet — og selve ordet »Anschluss« gøres forbudt.' },
  ww_weimar: { n: 'Weimarrepublikken', p: 'Weimar, Tyskland', d: 'Tysklands første demokrati fødes af revolution og nederlag — en forfatning af vidundere, kvinders valgret inkluderet — men det beskyldes for Versailles af sine fjender og forsvares aldrig af sine venner, før det er for sent.' },
  ww_neuilly: { n: 'Neuilly-traktaten', p: 'Neuilly, Frankrig', d: 'Bulgarien, det første der brød sammen, mister kysten mod det Ægæiske Hav og betaler krigsskadeserstatning — Balkankortet justeret, og intet løst.' },
  ww_league: { n: 'Oprettelsen af Folkeforbundet', p: 'Genève, Schweiz', d: 'Pagten træder i kraft i januar 1920: den første verdensorganisation for fred, Wilsons Nobelpris — og uden USA en vogter, der er for svag til 1930’erne.' },
  ww_trianon: { n: 'Trianon-traktaten', p: 'Versailles, Frankrig', d: 'Ungarn mister to tredjedele af sit territorium og tres procent af sin befolkning til Rumænien, Tjekkoslovakiet og Jugoslavien — et sår, der organiserer ungarsk politik den dag i dag.' },
  ww_sevres: { n: 'Sèvres-traktaten', p: 'Sèvres, Frankrig', d: 'Traktaten, der skulle skære Anatolien op — Smyrna til Grækenland, sundaerne internationaliseret — underskrives af en sultan, der ikke længere kontrollerer landet: Kemals Ankara afviser den, og kampene begynder igen.' },
  ww_turkish_war: { n: 'Den tyrkiske frihedskrig', p: 'Ankara, Tyrkiet', d: 'Fra Ankara kæmper Mustafa Kemal mod sultanen, grækerne og ententen til en sejr, ingen havde forventet: Republikken Tyrkiet udråbes i 1923, og sultanatet afskaffes.' },
  ww_lausanne: { n: 'Lausanne-traktaten', p: 'Lausanne, Schweiz', d: 'Traktaten, der erstatter Sèvres, anerkender det nye Tyrkiet, ratificerer en græsk-tyrkisk udveksling af 1,6 millioner mennesker og gør ende på det østerlandske spørgsmål, der var begyndt med Europas syge mand.' },
});

/* ww2 translations — World War II batch (79 entries, 2026-10-31) */
Object.assign(window.DATA_DA, {
  ww2_unit_731: { n: 'Enhed 731', p: 'Pingfang, Manchuriet', d: 'I et hemmeligt anlæg nær Harbin gør Shiro Ishiis ”vandrensningsenhed” pest, miltbrand og kolera til våben og afprøver dem på tusindvis af fanger — og bytter til sidst alle dataene til amerikanerne mod straffrihed.' },
  ww2_marco_polo: { n: 'Den anden kinesisk-japanske krig', p: 'Wanping, Kina', d: 'En natlig træfning ved Marco Polo-broen 7. juli 1937 vokser til Japans fulde invasion af Kina: Shanghai og Nanjing brænder, nationalisterne trækker sig op ad Yangtze til Chongqing — en slidende otteårig krig, der smelter sammen med 2. verdenskrig.' },
  ww2_nanjing: { n: 'Massakren i Nanjing', p: 'Nanjing, Kina', d: 'Japanske tropper stormer den kinesiske hovedstad og bruger seks uger på at dræbe: op til 300 000 soldater og civilister døde, titusinder af kvinder voldtaget — ”voldtægten af Nanking” chokerer verden.' },
  ww2_anschluss: { n: 'Anschluss', p: 'Wien, Østrig', d: 'Tyske tropper rykker ind i Østrig uden modstand og hilses med blomster; Wiens jøder tvinges til at skrubbe gaderne. Europas kort tegnes om uden at et eneste skud løsnes.' },
  ww2_munich: { n: 'München-aftalen', p: 'München, Tyskland', d: 'Storbritannien og Frankrig overdrager Hitler Sudeterlandet for at købe ”fred for vor tid”. Seks måneder senere opsluger han resten af Tjekkoslovakiet — eftergivenhedspolitikens symbol og vejen mod Polen.' },
  ww2_kristallnacht: { n: 'Krystalnatten', p: 'Berlin, Tyskland', d: 'I hele Riget brænder synagoger, og omkring 7 500 jødiske forretninger smadres i én koordineret nat; 30 000 jødiske mænd sendes i lejre — Holocausts indledende crescendo.' },
  ww2_khalkhin_gol: { n: 'Slagene ved Khalkhin Gol', p: 'Khalkhin Gol, Mongoliet', d: 'Zhukovs kampvogne og artilleri udsletter Japans Kwantung-armé på den mongolske steppe; Tokyo vender sig mod syd og Stillehavet i stedet for nord — en beslutning, der former 1941.' },
  ww2_molotov_ribbentrop: { n: 'Molotov–Ribbentrop-pagten', p: 'Moskva, Sovjetunionen', d: 'De to store fjender underskriver en ikke-angrebspagt med en hemmelig protokol, der deler Østeuropa i interessesfærer — Polen, Baltikum, Bessarabien og Finland fordelt på en enkelt nat.' },
  ww2_poland_invasion: { n: 'Invasionen af Polen', p: 'Westerplatte, Danzig, Polen', d: 'Ved daggry åbner det gamle slagskib Schleswig-Holstein ild mod Westerplatte — de første skud i 2. verdenskrig. Blitzkrig, Stukaer og 1,5 million mand knuser Polen på fem uger.' },
  ww2_anglo_french_decl: { n: 'Storbritannien og Frankrig erklærer krig', p: 'London, Storbritannien', d: 'To dage efter, at Polen er blevet invaderet, fortæller Chamberlain radiolytterne, at Storbritannien nu er i krig med Tyskland; Frankrig følger timer senere. Historiens dødeligste konflikt er begyndt.' },
  ww2_soviet_poland: { n: 'Den sovjetiske invasion af Polen', p: 'Brest, Polen', d: 'Stalin tager sin del af den hemmelige protokol: 17. september rykker Den Røde Hær ind i det østlige Polen, og en fælles tysk-sovjetisk parade markerer den nye grænse ved Brest.' },
  ww2_enigma: { n: 'Bletchley Park — knækningen af Enigma', p: 'Bletchley Park, Storbritannien', d: 'Et hemmeligt gods med matematikere, krydsordsmestre og verdens første elektroniske computere knækker Tysklands chiffermaskiner; konvojerne styrer uden om U-bådernes ulveflokke, og krigen forkortes med år.' },
  ww2_atlantic: { n: 'Slaget om Atlanterhavet', p: 'Nordatlanten', d: 'Krigens længste kampagne: U-bådernes ulveflokke mod konvojer, eskortehangarskibe og kodeknækkere om livlinjen, der holder Storbritannien mæt og Den Røde Hær forsynet — 3 500 handelsskibe og 783 U-både tabt.' },
  ww2_katyn: { n: 'Katyn-massakren', p: 'Katyn, Sovjetunionen', d: 'På Stalins ordre skyder NKVD 22 000 polske officerer, politifolk og intellektuelle — fra Katyn-skoven til lejrene i Starobilsk og Ostashkov — og lægger skylden på tyskerne i halvtreds år.' },
  ww2_dunkirk: { n: 'Evakueringen fra Dunkerque', p: 'Dunkerque, Frankrig', d: 'Fanget op mod Kanalen føres 338 000 britiske og franske soldater hjem af destroyere, fiskerbåde og lystdampere — ”redningens mirakel”, der holder Storbritannien i krigen.' },
  ww2_france_falls: { n: 'Frankrigs fald', p: 'Compiègne, Frankrig', d: 'Hæren, der holdt stand i 1918, kollapser på seks uger; Hitler tvinger franskmændene til at underskrive i samme jernbanevogn, hvor Tyskland kapitulerede i 1918. Halvdelen af landet kommer under Vichy-styre.' },
  ww2_vichy: { n: 'Vichy-Frankrig', p: 'Vichy, Frankrig', d: 'Marskal Pétains kollaborationsstat erstatter Republikken og skiber jøder og dissidenter af sted mod øst, mens de Gaulle fra London forsikrer, at Frankrig har ”tabt et slag, ikke krigen”.' },
  ww2_battle_of_britain: { n: 'Slaget om Storbritannien', p: 'Sydengland, Storbritannien', d: '”Aldrig har så mange skyldt så få så meget”: Spitfires, Hurricanes og radarkæden besejrer Luftwaffe i luften over England — Nazi-Tysklands første strategiske nederlag.' },
  ww2_blitz: { n: 'Blitzen', p: 'London, Storbritannien', d: 'I 57 nætter i træk brænder London under tyske bomber, og 43 000 civilister dør i hele Storbritannien; londonerne sover i undergrundsstationer — og byen arbejder videre.' },
  ww2_greco_italian: { n: 'Den græsk-italienske krig', p: 'Pindos, Grækenland', d: 'Mussolini invaderer Grækenland fra Albanien 28. oktober ”for at matche Hitlers bedrifter” — og den græske hær jager italienerne tilbage op i bjergene og tvinger Tyskland til at redde sin allierede.' },
  ww2_lend_lease: { n: 'Lend-Lease', p: 'Washington, USA', d: 'Roosevelt gør Amerika til ”demokratiets arsenal”: omkring 50 milliarder dollars i kampvogne, lastbiler, mad og flybrændstof — alene 400 000 lastbiler og jeeps til Den Røde Hær.' },
  ww2_balkans: { n: 'Invasionen af Jugoslavien og Grækenland', p: 'Beograd, Jugoslavien', d: 'Efter at et kup i Beograd har sprængt aksepagten, bomber Hitlers Luftwaffe byen til ruiner; Wehrmacht fejer gennem Balkan på tre uger — og Europas største partisanbevægelse opstår.' },
  ww2_tobruk: { n: 'Belejringen af Tobruk', p: 'Tobruk, Libyen', d: 'De australske ”Tobruk-rotter” holder fæstningshavnen i 241 dage mod Rommels Afrikakorps — det første stop for Ørkenrævens march mod Egypten.' },
  ww2_crete: { n: 'Slaget om Kreta', p: 'Kreta, Grækenland', d: 'Det største luftbårne angreb hidtil: tyske faldskærmstropper erobrer Kreta til en pris, der får Hitler til at forbyde faldskærmslandsætninger i stor stil for altid — men øen falder, og Ægæerhavet bliver Aksemagternes indre sø.' },
  ww2_barbarossa: { n: 'Operation Barbarossa', p: 'Brest, Sovjetunionen', d: 'Tre millioner aksetropper invaderer Sovjetunionen på en 2 900 km lang front — historiens største invasion. Fire år og 27 millioner sovjetiske døde senere står Den Røde Hær i Berlin.' },
  ww2_continuation_war: { n: 'Fortsættelseskrigen', p: 'Karelen, Finland', d: 'Finland kæmper igen ved Tysklands side for at generobre det tabte Karelen, rykker frem og holder derefter tre års skyttegravskrig — og standser Sovjetunionens store offensiv i 1944 og bevarer sin uafhængighed.' },
  ww2_leningrad: { n: 'Belejringen af Leningrad', p: 'Leningrad, Sovjetunionen', d: 'I 872 dage beskydes og sultes byen: brød rationeret til 125 gram om dagen, over en million civilister døde, Livets vej over den frosne Ladogasø som den eneste forbindelse — og byen overgiver sig aldrig.' },
  ww2_kyiv_1941: { n: 'Slaget om Kyiv (1941)', p: 'Kyiv, Ukraine', d: 'Historiens største omringning: fire sovjetiske arméer indfanget øst for Dnepr, og over 600 000 fanger marcherer ind i tyske lejre. Det besatte Kyiv gennemlider massakrer — og Guderians drejning mod syd forsinker fremstødet mod Moskva.' },
  ww2_moscow: { n: 'Slaget om Moskva', p: 'Moskva, Sovjetunionen', d: 'Tyske angrebsspidser når hovedstadens udkant, og panik breder sig i Moskva — så ankommer friske sibiriske divisioner med toget, og Zhukov går til modangreb. Blitzkrigen dør i sneen.' },
  ww2_sevastopol: { n: 'Belejringen af Sevastopol', p: 'Sevastopol, Krim', d: 'Søfæstningen holder stand i 250 dage mod Mansteins 11. armé, 80 cm-kanonen Dora medregnet, før den falder — og Sortehavsflådens helteby betaler i blod.' },
  ww2_pearl_harbor: { n: 'Angrebet på Pearl Harbor', p: 'Pearl Harbor, Hawaii, USA', d: '”En dag, der vil leve i vanære”: 353 japanske hangarskibsfly angriber den amerikanske Stillehavsflåde ved ankerpladsen — 2 400 døde, otte slagskibe ramt — og USA går ind i krigen.' },
  ww2_wannsee: { n: 'Wannsee-konferencen', p: 'Wannsee, Berlin, Tyskland', d: 'Femten embedsmænd mødes i en villa ved søen i halvfems minutter for at koordinere ”den endelige løsning”: Europas elleve millioner jøder skrives op til deportation og mord.' },
  ww2_singapore: { n: 'Singapores fald', p: 'Singapore', d: '”Det værste nederlag og den største kapitulation i britisk historie”: 80 000 Commonwealth-soldater overgiver sig til en mindre japansk styrke, der er cyklet ned gennem Malaya — imperiets prestige kommer sig aldrig.' },
  ww2_bataan: { n: 'Dødsmarchen fra Bataan', p: 'Bataan, Filippinerne', d: 'Efter kapitulationen ved Bataan marcheres 75 000 amerikanske og filippinske fanger tvunget 106 km i tropisk hede — tusindvis dør undervejs, og befrielsen er tre år væk.' },
  ww2_coral_sea: { n: 'Slaget i Koralhavet', p: 'Koralhavet', d: 'Det første søslag, hvor flåderne aldrig ser hinanden — hangarskibsfly angriber ud over horisonten. Japanernes fremstød mod Port Moresby vendes for første gang.' },
  ww2_kharkiv_1942: { n: 'Det andet slag om Kharkiv', p: 'Kharkiv, Ukraine', d: 'Timosjenkos forårsoffensiv for at generobre byen løber ind i en modfælde: en kvart million sovjetiske soldater går tabt i Barvenkovo-lommen — katastrofen, der åbner vejen til Don og Stalingrad.' },
  ww2_heydrich: { n: 'Attentatet på Heydrich — Lidice', p: 'Prag, Tjekkoslovakiet', d: 'Tjekkiske faldskærmssoldater fra Operation Anthropoid kaster granater ind i ”Bøddelens” åbne bil; SS jævner landsbyerne Lidice og Ležáky med jorden som hævn og deporterer deres børn.' },
  ww2_midway: { n: 'Slaget om Midway', p: 'Midway-atollen, Stillehavet', d: 'Takket være kodeknækkere lægger amerikanske hangarskibe baghold for den japanske flåde: i fem minutters styrtbombning brænder fire hangarskibe — og ligevægten i Stillehavskrigen vender 4. juni 1942.' },
  ww2_guadalcanal: { n: 'Kampagnen på Guadalcanal', p: 'Guadalcanal, Salomonøerne', d: 'Seks måneder med jungle, malaria og natlige sødueller omkring en flueramte ø — Amerikas første landoffensiv, hvor japanernes fremrykning i Stillehavet endelig knækker.' },
  ww2_stalingrad: { n: 'Slaget om Stalingrad', p: 'Stalingrad, Sovjetunionen', d: 'Hvert hus en fæstning, hver gade et slag: fem måneders byslagt ender med 91 000 overlevende fra 6. armé, der marcherer i fangenskab — vendepunktet i krigen i Europa.' },
  ww2_el_alamein: { n: 'Slaget ved El Alamein', p: 'El Alamein, Egypten', d: 'Montgomerys 8. armé bryder Rommels linje hundrede kilometer fra Alexandria — ”før Alamein havde vi aldrig en sejr; efter Alamein havde vi aldrig et nederlag”.' },
  ww2_torch: { n: 'Operation Torch', p: 'Algier, Algeriet', d: 'Angloamerikanske landsætninger fanger Rommels hær bagfra; i maj 1943 overgiver en kvart million aksetropper sig i Tunesien, og Middelhavet bliver de allieredes indhav.' },
  ww2_manhattan: { n: 'Manhattan-projektet', p: 'Los Alamos, USA', d: 'I hemmelige laboratorier i New Mexico bygger Oppenheimers hold den første atombombe — en indsats på to milliarder dollars med 130 000 mennesker, der vil afslutte krigen og åbne atomalderen.' },
  ww2_bengal_famine: { n: 'Hungersnøden i Bengalen', p: 'Bengalen, Britisk Indien', d: 'Krigens beslaglæggelse af både, hamstrering og Churchills kabinets afvisning af nødskibe efterlader Bengalen i hungersnød, mens krigen raser i Burma — tre millioner mennesker dør.' },
  ww2_koriukivka: { n: 'Tragedien i Koriukivka', p: 'Koriukivka, Ukraine', d: 'Som hævn for partisanbaghold myrder tyske SS- og ungarske enheder omkring 6 700 beboere og brænder byen Koriukivka ned — den største enkeltstående massakre på civilister i krigstidens Ukraine.' },
  ww2_khatyn: { n: 'Khatyn-massakren', p: 'Khatyn, Hviderusland', d: 'En straffebataljon under SS-kommando driver en hviderussisk landsbys beboere ind i en lade og brænder dem levende — 149 mennesker, 75 af dem børn; en skæbne, der ramte omkring 9 200 hviderussiske landsbyer.' },
  ww2_warsaw_ghetto: { n: 'Opstanden i Warszawa-ghettoen', p: 'Warszawa, Polen', d: 'Krigens største jødiske opstand: let bevæbnede kæmpere holder SS-panseren tilbage i næsten en måned, før ghettoen brænder — kæmpet, som overlevende sagde, for at dø på egne præmisser.' },
  ww2_kursk: { n: 'Slaget om Kursk', p: 'Kursk, Sovjetunionen', d: 'Historiens største panserslag: 6 000 kampvogne støder sammen på steppen, og Hitlers sidste østoffensiv knuses mod et forsvar otte bælte dybt — herfra rykker Den Røde Hær frem for godt.' },
  ww2_dnipro: { n: 'Slaget om Dnepr', p: 'Dnepr-floden, Ukraine', d: 'Fem sovjetiske fronter stormer den store flod på en 1 400 km lang front — ponton efter ponton, spejdere der erobrer brohoveder om natten. Wehrmachts ”Østmuren” bryder sammen, og vejen til Kyiv og vest ligger åben.' },
  ww2_italy_armistice: { n: 'Italien kapitulerer', p: 'Rom, Italien', d: 'Mussolini afsættes og fængsles; Badoglio underskriver en våbenstilstand med de allierede — og Tyskland afvæbner en million italienske soldater på få dage og overtager halvdelen af landet.' },
  ww2_kyiv_1943: { n: 'Befrielsen af Kyiv', p: 'Kyiv, Ukraine', d: '6. november 1943 tager Den Røde Hær Kyiv fra brohovedet ved Ljutezj — den første besatte republikhovedstad, der generobres; byen træder frem efter 778 dages besættelse og massakrer.' },
  ww2_tehran: { n: 'Teherankonferencen', p: 'Teheran, Iran', d: 'Stalin, Roosevelt og Churchill mødes for første gang: den anden front fastlægges til maj 1944, Polens grænser skitseres over middagen — Den Store Alliance på sit højdepunkt.' },
  ww2_monte_cassino: { n: 'Slaget om Monte Cassino', p: 'Monte Cassino, Italien', d: 'Fire angreb på fire måneder, et kloster fra 500-tallet bombet til grus, og til sidst hejser polske tropper deres flag over ruinerne — Gustav-linjen bryder sammen, og vejen til Rom ligger åben.' },
  ww2_deportations: { n: 'Sovjetiske straffedeportationer', p: 'Krim og Nordkaukasus', d: 'Stalin stryger hele folkeslag af kortet, fordi de erklæres ”illoyale”: den tsjetsjensk-ingusiske befolkning sendes af sted i kvægvogne i februar 1944, krimtatarerne den 18. maj — næsten halvdelen dør undervejs; først hjem igen årtier senere.' },
  ww2_bagration: { n: 'Operation Bagration', p: 'Minsk, Hviderusland', d: 'På dagen tre år efter Barbarossa udsletter Den Røde Hær Heeresgruppe Mitte — 28 divisioner udvisket på fem uger, Wehrmachts værste nederlag — og fronten rykker 600 km mod vest.' },
  ww2_bretton_woods: { n: 'Bretton Woods-konferencen', p: 'Bretton Woods, USA', d: 'Mens krigen raser, tegner 44 nationer freden: IMF og Verdensbanken fødes, og dollaren bliver verdens ankervaluta — efterkrigstidens økonomiske skelet.' },
  ww2_lviv_1944: { n: 'Lviv–Sandomierz-offensiven', p: 'Lviv, Ukraine', d: 'I juli 1944 bryder sovjetiske arméer Brody-lommen og indtager Lviv og når inden for en måned frem til Wisła — Heeresgruppe Nordukraine smadres, og fronten krydser ind i det besatte Polen.' },
  ww2_wallenberg: { n: 'Raoul Wallenberg i Budapest', p: 'Budapest, Ungarn', d: 'Mens Eichmanns transporter fragter 437 000 ungarske jøder til Auschwitz på otte uger, udsteder en svensk diplomat beskyttelsespas og gemmer tusindvis i ”svenske huse” — titusinder overlever.' },
  ww2_warsaw_uprising: { n: 'Warszawa-opstanden', p: 'Warszawa, Polen', d: 'Hjemmehæren gør oprør 1. august for at befri byen, før sovjetterne når frem; efter 63 dages gadekampe er Warszawa jævnet med jorden, og omkring 200 000 polakker er døde — mens Den Røde Hær ser til fra den anden side af Wisła.' },
  ww2_paris: { n: 'Befrielsen af Paris', p: 'Paris, Frankrig', d: 'Leclercs fri-franske division og Modstandsbevægelsens barrikader befrier hovedstaden efter fire års besættelse; Choltitz kapitulerer uden at sætte broerne i brand, og de Gaulle går ned ad Champs-Élysées.' },
  ww2_slovak_uprising: { n: 'Den slovakiske nationale opstand', p: 'Banská Bystrica, Slovakiet', d: 'Den slovakiske hær vender sine våben mod Tiso-regimet og dets tyske beskytter; to måneders bjergkampe ender i nederlag — men Slovakiet skrives ind i de allieredes regnskab.' },
  ww2_v2: { n: 'V-2 — raketalderen', p: 'Peenemünde, Tyskland', d: 'Fra hemmelige laboratorier ved Østersøen falder verdens første ballistiske missil over London og Antwerpen hurtigere end lyden; Hitlers ”hævnvåben” redder ham ikke — men grundlægger rumfartens tidsalder.' },
  ww2_market_garden: { n: 'Operation Market Garden', p: 'Arnhem, Holland', d: 'En bro for meget: Det største luftlandingsangreb nogensinde sætter alt ind på at nå over Rhinen — og pansertropperne står ved Arnhem. Krigen sliber videre gennem endnu en vinter.' },
  ww2_percentages: { n: 'Procentaftalen', p: 'Moskva, Sovjetunionen', d: 'På et halvt ark papir deler Churchill og Stalin Balkan: Rumænien 90 procent sovjetisk, Grækenland 90 procent britisk, Jugoslavien halvt om halvt — ”mon det ikke ville synes ret kynisk?”' },
  ww2_leyte: { n: 'Slaget i Leytebugten', p: 'Leytebugten, Filippinerne', d: 'Det største søslag, der nogensinde er udkæmpet: fire separate træfninger, de første kamikazeangreb og den japanske flådes sidste udfald — Den Kejserlige Flåde ophører med at være en kampstyrke.' },
  ww2_bulge: { n: 'Slaget om Ardennerne', p: 'Ardennerne, Belgien', d: 'Hitlers sidste hasardspil i vest: kampvogne vælter gennem de snedækkede Ardenner for at splitte de allierede; Bastogne holder stand — ”Nuts!” — og Wehrmacht brænder sine sidste reserver af.' },
  ww2_vistula_oder: { n: 'Wisła–Oder-offensiven', p: 'Poznań, Polen', d: 'På tre vinteruger rykker Den Røde Hær 500 km frem fra Wisła til 70 km fra Berlin — Schlesien erobret, Warszawa forbi — og den tyske østfront kommer sig aldrig.' },
  ww2_yalta: { n: 'Jaltakonferencen', p: 'Jalta, Krim', d: 'De tre store udformer efterkrigstidens verden i et palæ på Krim: besættelseszoner i Tyskland, FN, løfter om frie valg i Polen — som aldrig indfries. Her tegnes kortet til den kolde krig.' },
  ww2_dresden: { n: 'Bombardementet af Dresden', p: 'Dresden, Tyskland', d: 'Fire angreb på 36 timer antænder en ildstorm i den flygtningefyldte ”Firenze ved Elben”; omkring 25 000 dør — og et stående udtryk for tæppebombardementers etik er født.' },
  ww2_iwo_jima: { n: 'Slaget om Iwo Jima', p: 'Iwo Jima, Japan', d: '21 kvadratkilometer vulkansk aske koster 26 000 amerikanske tab mod tunnelbaserede forsvarsstillinger — flaget på bjerget Suribachi bliver krigens mest berømte fotografi.' },
  ww2_tokyo_fire: { n: 'Brandbombningen af Tokyo', p: 'Tokyo, Japan', d: 'Natten mellem 9. og 10. marts slipper omkring 300 B-29’ere brandbomber over det træbyggede Tokyo — omkring 100 000 døde på få timer, historiens dødeligste luftangreb, et halvt år før atombomberne.' },
  ww2_okinawa: { n: 'Slaget om Okinawa', p: 'Okinawa, Japan', d: 'Den sidste ø før Japan: 82 dage, 12 000 amerikanske og omkring 100 000 japanske døde, 150 000 okinawanske civilister mistet, kamikazeangreb i massevis — selve invasionen af Japan lurer forude.' },
  ww2_battle_of_berlin: { n: 'Slaget om Berlin', p: 'Berlin, Tyskland', d: 'To og en halv million sovjetiske soldater indtager Rigets hovedstad gade for gade; Hitler begår selvmord i bunkeren, og Rigsdagsbygningen falder 30. april — krigen i Europa er dage fra slutningen.' },
  ww2_elbe_day: { n: 'Elbe-dagen', p: 'Torgau, Tyskland', d: 'Amerikanske og sovjetiske patruljer rækker hinanden hånden på en ødelagt bro over Elben — øst og vest har mødt hinanden; champagnen deles, og kortet over et delt Europa begynder at hærde.' },
  ww2_ve_day: { n: 'V-E-dagen', p: 'Reims, Frankrig', d: 'Tyskland kapitulerer betingelsesløst — i Reims 7. maj, og igen i Berlin-Karlshorst over for sovjeterne 8. maj. Seks års krig i Europa slutter med titals millioner døde.' },
  ww2_nagasaki: { n: 'Atombombningen af Nagasaki', p: 'Nagasaki, Japan', d: 'Skydække over Kokura flytter målet: ”Fat Man” detonerer over Nagasakis Urakami-dal — 40 000 dør med det samme, 70 000 inden udgangen af året, og Japans krigsråd er endeligt brudt.' },
  ww2_japan_surrender: { n: 'Japan kapitulerer', p: 'Tokyo-bugten, Japan', d: 'På dækket af USS Missouri underskriver Japan kapitulationserklæringen — historiens dødeligste krig er forbi: 70–85 millioner døde, og to stormagter står ansigt til ansigt over en ødelagt verden.' },
  ww2_nuremberg: { n: 'Nürnbergprocessen', p: 'Nürnberg, Tyskland', d: 'Fireogtyve naziledere stilles til ansvar for en international domstol i den sønderbombte partiby: forbrydelser mod menneskeheden skrives ind i loven, ”overordnede ordrer” holder ikke længere som forsvar, og tolv hænges.' },
  ww2_expulsions: { n: 'Fordrivelsen af tyskerne fra Østeuropa', p: 'Østeuropa', d: 'Historiens største tvangsflytning: 12–14 millioner tyskere drives ud af Polen, Tjekkoslovakiet og Baltikum — en halv million dør på vejene i den ”ordnede og humane” overførsel.' },
});
